# Registro de actividad de miembros. Las acciones de moderación se identifican
# mediante la auditoría de Discord; ante falta de permisos se clasifica como salida.
@_i18n_context
async def classify_member_departure(member):
    guild = member.guild
    observed = datetime.now(timezone.utc)
    if not guild.me or not guild.me.guild_permissions.view_audit_log:
        return "member_leave", None, None, _t('text.54c7347d142744')
    audit_checked = False
    for delay in (2, 3, 5):
        await asyncio.sleep(delay)
        try:
            for action, event in ((discord.AuditLogAction.ban, "member_ban"),
                                  (discord.AuditLogAction.kick, "member_kick")):
                async for entry in guild.audit_logs(limit=25, action=action, after=observed - timedelta(seconds=20)):
                    if (getattr(entry.target, "id", None) == member.id
                            and abs((entry.created_at - observed).total_seconds()) <= 20):
                        return event, entry.user, entry.reason, None
            audit_checked = True
        except discord.Forbidden:
            return "member_leave", None, None, _t('text.e9f20818e3a6af')
        except discord.HTTPException:
            continue
    if not audit_checked:
        return "member_leave", None, None, _t('text.1b4089dd688c9d')
    return "member_leave", None, None, _t('text.a994b56142fdee')



@_i18n_context
def member_departure_description(
    member: discord.Member, kind: str, *,
    moderator: discord.abc.User | None = None,
    reason: str | None = None,
    uncertainty: str | None = None,
    ban_duration_known: bool = False,
    ban_duration_minutes: int | None = None,
    ban_expires_at: datetime | None = None,
    extra: list[tuple[str, str]] | None = None,
) -> str:
    """Tarjeta compacta con hechos comprobados del evento, sin enlaces ficticios."""
    guild = member.guild
    joined = discord.utils.format_dt(member.joined_at, "R") if member.joined_at else _t('text.b781f6bd9b98e4')
    roles = [role.mention for role in member.roles if role.id != guild.default_role.id]
    shown: list[str] = []
    for role in roles:
        if len(_i18n_join(", ", (*shown, role))) > 850:
            break
        shown.append(role)
    roles_text = _i18n_join(", ", shown) if shown else _t('text.9e3fc69d0d9cdc')
    if len(shown) < len(roles):
        roles_text += _t('text.ae7023b76cf9e6', p0=f'{len(roles) - len(shown)}')
    name = discord.utils.escape_markdown(str(member.display_name))[:100]
    lines = [
        _t('text.c3691afdda514b', p0=f'{name}', p1=f'{member.mention}'),
        _t('text.ecb90f9fd3926c', p0=f'{member.id}'),
        _t('text.5da655faefdff3', p0=f'{joined}'),
        _t('text.59a43064588266', p0=f'{roles_text}'),
        _t('text.004e5c3ee5d5a6', p0=f"{(guild.member_count if guild.member_count is not None else _t('text.b781f6bd9b98e4'))}"),
    ]
    if kind in {"member_kick", "member_ban"}:
        if reason:
            clean_reason = discord.utils.escape_markdown(str(reason)[:500]).replace("\n", " ")
            lines.append(_t('text.e6e29092a21a9c', p0=f'{clean_reason}'))
        if moderator is not None:
            lines.append(_t('text.dba327ecb10f83', p0=f'{moderator.mention}'))
    if kind == "member_ban":
        if ban_duration_known:
            duration = format_duration(ban_duration_minutes) if ban_duration_minutes else _t('text.d8fc3bee61ea28')
            lines.append(_t('text.6844eee90394ec', p0=f'{duration}'))
            if ban_duration_minutes and ban_expires_at:
                lines.append(_t('text.7b42fea6d7378e', p0=f"{discord.utils.format_dt(ban_expires_at, 'R')}"))
        else:
            lines.append(_t('text.a628ac7e8ba302'))
    if kind == "member_leave" and uncertainty:
        lines.append(_t('text.6e39e7feb39194', p0=f'{discord.utils.escape_markdown(uncertainty[:220])}'))
    for label, value in (extra or []):
        lines.append(f"> **{label}:** {value}")
    return _i18n_join("\n", lines)


@_i18n_context
def member_departure_embed(member: discord.Member, kind: str, **kwargs) -> discord.Embed:
    """Respeta el editor de plantillas existente, con avatar por defecto."""
    title = dict(LOG_EVENT_CATALOG["members"])[kind]
