class AgeVerificationTimeModal(discord.ui.Modal, title=_t('text.344945fa629cac')):
    verify_timeout = discord.ui.TextInput(
        label=_t('text.6b3325a1ff899b'), required=True,
        max_length=6, placeholder=_t('text.1437f4226f110e'))

    @_i18n_context
    def __init__(self, guild_id: int) -> None:
        super().__init__()
        self.guild_id = guild_id
        self.initial = str(max(1, (get_verify_timeout(guild_id) + 59) // 60))
        self.verify_timeout.default = self.initial

    @_i18n_context
    async def on_submit(self, interaction: discord.Interaction) -> None:
        if not await configuration_access(interaction, self.guild_id):
            return
        value = str(self.verify_timeout).strip()
        try:
            minutes = int(value)
            if not 1 <= minutes <= 40320:
                raise ValueError
        except ValueError:
            await interaction.response.send_message(
                _t('text.be0fabdb963630'),
                ephemeral=True)
            return
        if value == self.initial:
            await interaction.response.send_message(_t('text.ed5c91affb2e42'), ephemeral=True)
            return
        await confirm_configuration(interaction, self.guild_id,
                                    {"verify_timeout": str(minutes * 60)})


