HERALDO_CHANNEL_DEFINITIONS = {
    "logs": (_t('setup.module.logging.label'), "El Heraldo"),
    "condemned": (_t('text.5c855e784bb201'), "Condenados"),
    "honeypot": ("Honeypot", "Honeypot"),
    "verification": (_t('setup.module.verification.label'), "Verificación"),
    "questions": (_t('channel.purpose.questions'), "Dudas"),
}


@_i18n_context
def heraldo_channels_summary(guild: discord.Guild) -> str:
    lines: list[str] = []
    for key, (label, default_name) in HERALDO_CHANNEL_DEFINITIONS.items():
        channel_id = get_guild_channel_id(guild.id, key)
        channel = guild.get_channel(channel_id) if channel_id else None
        if isinstance(channel, discord.TextChannel):
            lines.append(f"**{label}:** {channel.mention}")
            continue
        exact = next(
            (c for c in guild.text_channels if c.name.casefold() == default_name.casefold()),
            None,
        )
        if exact is not None:
            lines.append(_t('text.3553c58f96b29c', p0=f'{label}', p1=f'{exact.mention}'))
        else:
            lines.append(_t('text.323e705eaf254e', p0=f'{label}', p1=f'{default_name}'))
    return _i18n_join("\n", lines)


