class JoinRolesUserIdModal(discord.ui.Modal, title=_t('text.9e54f590fbae7a')):
    user_id_input = discord.ui.TextInput(
        label=_t('text.838ec21bd0b926'),
        required=True,
        max_length=24,
        placeholder=_t('text.17309a971ae71d'),
    )

    @_i18n_context
    def __init__(self, parent_view: "HeraldoJoinRolesUsersView") -> None:
        super().__init__()
        self.parent_view = parent_view
        if parent_view.selected_user_id:
            self.user_id_input.default = str(parent_view.selected_user_id)

    @_i18n_context
    async def on_submit(self, interaction: discord.Interaction) -> None:
        raw = str(self.user_id_input).strip()
        try:
            user_id = int(raw)
            if user_id <= 0:
                raise ValueError
        except ValueError:
            await interaction.response.send_message(
                _t('text.9a45e246bb00ab'), ephemeral=True
            )
            return
        self.parent_view.selected_user_id = user_id
        await interaction.response.edit_message(
            content=self.parent_view._content(interaction.guild) + _t('text.b80ddedd238aaa', p0=f'{user_id}'),
            view=self.parent_view,
        )



