class HeraldoHoneypotActionView(HeraldoHoneypotDraftSubView):
    """Acciones y parámetros configurables en /setup; solo Guardar persiste."""

    @_i18n_context
    def __init__(self, parent: HeraldoHoneypotSetupView) -> None:
        super().__init__(parent)
        current = parent.pending_action or hp_action(parent.guild_id)
        choices = [
            (_t('text.c07967d4d13350'), "role", _t('text.ab1b25d29aa190')),
            (_t('text.13086cfd03bf14'), "log", _t('text.88c2b22b8820d4')),
            (_t('text.22b733ebaab166'), "timeout", _t('text.01326245d7cbcc')),
            (_t('text.ffb1a9c946e708'), "kick", _t('text.1f31f733ae33f1')),
            (_t('text.e1e571bc9280a3'), "ban", _t('text.db8a344bf93d88')),
        ]
        selector = discord.ui.Select(
            placeholder=_t('text.eb40da97b68a78'),
            options=[
                discord.SelectOption(
                    label=label, value=value, description=description, default=value == current,
                )
                for label, value, description in choices
            ], row=0,
        )
        selector.callback = self.choose
        self.add_item(selector)
        self.parameters.disabled = current == "log"

    @_i18n_context
    def _embed(self, guild: discord.Guild) -> discord.Embed:
        action = self.parent.pending_action or hp_action(guild.id)
        details = {
            "kick": _t('text.d6964f891ddc2d'),
            "ban": _t('text.7000c1331affb2'),
            "role": _t('text.998a39ec4f14b6'),
            "timeout": _t('text.8832bef16a2be5'),
            "log": _t('text.f842827b3f5568'),
        }
        return discord.Embed(
            title=_t('text.725f95b19b80a0'),
            description=(
                _t('text.808abf752571ba', p0=f'{HONEYPOT_ACTION_LABELS.get(action, action)}', p1=f'{details[action]}')
            ),
            color=discord.Color.blurple(),
        )

    @honeypot_operation
    @_i18n_context
    async def choose(self, interaction: discord.Interaction) -> None:
        await interaction.response.defer()
        values = interaction.data.get("values", []) if interaction.data else []
        if len(values) != 1 or values[0] not in {"role", "log", "timeout", "kick", "ban"}:
            await interaction.followup.send(_t('text.daf147fed20bee'), ephemeral=True)
            return
        old_action = self.parent.pending_action or hp_action(self.parent.guild_id)
        if values[0] != old_action:
            self.parent.pending_kick_purge_minutes = None
            self.parent.pending_ban_minutes = None
            self.parent.pending_timeout_minutes = None
            self.parent.pending_purge_spec = None
        self.parent.pending_action = (
            values[0] if values[0] != hp_action(self.parent.guild_id) else None
        )
        self.parent._sync_controls()
        updated = HeraldoHoneypotActionView(self.parent)
        await interaction.edit_original_response(
            content=None, embed=updated._embed(interaction.guild), view=updated,
        )

    @discord.ui.button(label=_t('text.1adfb90c41eab8'), style=discord.ButtonStyle.primary, row=1)
    @honeypot_operation
    @_i18n_context
    async def parameters(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        await interaction.response.defer()
        view = HeraldoHoneypotParametersView(self.parent)
        await interaction.edit_original_response(
            content=None, embed=view._embed(interaction.guild), view=view,
        )


class HeraldoHoneypotParametersView(HeraldoHoneypotDraftSubView):
    """Selectores contextuales de la acción activa. Ninguno guarda automáticamente."""

    @_i18n_context
    def __init__(self, parent: HeraldoHoneypotSetupView) -> None:
        super().__init__(parent)
        self.action = parent.pending_action or hp_action(parent.guild_id)
        if self.action == "kick":
            choices = [(v, f"{format_duration(v)}") for v in (1440, 2880, 4320, 10080, 20160, 43200)]
            selected = parent.pending_kick_purge_minutes or hp_kick_purge_minutes(parent.guild_id)
            self._add_duration_selector(choices, selected, self.select_kick_purge, _t('text.0bf605a34005c3'), 0)
        elif self.action == "ban":
            selected = (
                parent.pending_ban_minutes if parent.pending_ban_minutes is not None
                else (hp_ban_duration_minutes(parent.guild_id) or 0)
            )
            choices = [(v, (_t('text.d8fc3bee61ea28') if v == 0 else format_duration(v)))
                       for v in (0, 5, 60, 1440, 10080, 43200)]
            self._add_duration_selector(choices, selected, self.select_ban_duration, _t('text.06e8d8668da9b9'), 0)
        elif self.action == "timeout":
            selected = parent.pending_timeout_minutes or hp_timeout_minutes(parent.guild_id)
            choices = [(v, format_duration(v)) for v in (10, 30, 60, 360, 1440, 10080, 40320)]
            self._add_duration_selector(choices, selected, self.select_timeout, _t('text.b4b9e45395fbdf'), 0)
            self._add_purge_selector(1)
        elif self.action == "role":
            self._add_purge_selector(0)

    @_i18n_context
    def _add_duration_selector(self, choices, selected, callback, placeholder, row) -> None:
        options = [
            discord.SelectOption(label=label, value=str(minutes), default=minutes == selected)
            for minutes, label in choices
        ]
        select = discord.ui.Select(placeholder=placeholder, options=options, row=row)
        select.callback = callback
        self.add_item(select)

    @_i18n_context
    def _add_purge_selector(self, row: int) -> None:
        selected = self.parent.pending_purge_spec or hp_purge_spec(self.parent.guild_id)
        options = [
            discord.SelectOption(
                label=label, value=f"{kind}:{value}", default=(kind, value) == selected,
            )
            for kind, value, label in [
                ("none", 0, _t('text.035eb329ac8593')),
                ("time", 60, _t('text.4c306ea7369bad')),
                ("time", 360, _t('text.b6ea67dd67d09f')),
                ("time", 1440, _t('text.173f1180fcb9b8')),
                ("time", 4320, _t('text.2b12265a428d59')),
                ("time", 10080, _t('text.bb16b73fa6875b')),
            ]
        ]
        select = discord.ui.Select(placeholder=_t('text.310a3bfa68cebc'), options=options, row=row)
        select.callback = self.select_purge
        self.add_item(select)

    @_i18n_context
    def _embed(self, guild: discord.Guild) -> discord.Embed:
        action = self.action
        lines = [_t('text.7f538fc34aadb2', p0=f'{HONEYPOT_ACTION_LABELS[action]}')]
        if action == "kick":
            minutes = self.parent.pending_kick_purge_minutes or hp_kick_purge_minutes(guild.id)
            lines.extend([
                _t('text.bbaa126ac474a5', p0=f'{format_duration(minutes)}'),
                _t('text.25b7cb2ec5e804'),
            ])
        elif action == "ban":
            minutes = (
                self.parent.pending_ban_minutes if self.parent.pending_ban_minutes is not None
                else hp_ban_duration_minutes(guild.id)
            )
            lines.append(
                _t('text.ec85114caf913f', p0=f"{(format_duration(minutes) if minutes else _t('text.d8fc3bee61ea28'))}")
            )
            lines.append(_t('text.381eacf890e270'))
        elif action == "timeout":
            minutes = self.parent.pending_timeout_minutes or hp_timeout_minutes(guild.id)
            lines.append(_t('text.ec85114caf913f', p0=f'{format_duration(minutes)}'))
        elif action == "role":
            role_id = hp_punish_role_id(guild.id)
            lines.append(_t('text.bbf8f7a34ed877', p0=f"{(f'<@&{role_id}>' if role_id else _t('text.67db68445a607d'))}"))
            lines.append(_t('text.652e027f61c267'))
        if action in {"role", "timeout"}:
            spec = self.parent.pending_purge_spec or hp_purge_spec(guild.id)
            lines.append(_t('text.0efed973910136', p0=f'{format_purge_spec(*spec)}'))
        lines.append(_t('text.9138b3c1be198e'))
        return discord.Embed(
            title=_t('text.5fc6e4b4e07d52'),
            description=_i18n_join("\n", lines),
            color=discord.Color.blurple(),
        )

    @_i18n_context
    async def _stage(self, interaction: discord.Interaction) -> None:
        updated = HeraldoHoneypotParametersView(self.parent)
        await interaction.edit_original_response(
            content=None, embed=updated._embed(interaction.guild), view=updated,
        )

    @honeypot_operation
    @_i18n_context
    async def select_kick_purge(self, interaction: discord.Interaction) -> None:
        await interaction.response.defer()
        value = int(interaction.data["values"][0])
        if value not in {1440, 2880, 4320, 10080, 20160, 43200}:
            await interaction.followup.send(_t('text.afb060eb7cb379'), ephemeral=True)
            return
        saved = hp_kick_purge_minutes(self.parent.guild_id)
        self.parent.pending_kick_purge_minutes = value if value != saved else None
        await self._stage(interaction)

    @honeypot_operation
    @_i18n_context
    async def select_timeout(self, interaction: discord.Interaction) -> None:
        await interaction.response.defer()
        value = int(interaction.data["values"][0])
        if value not in {10, 30, 60, 360, 1440, 10080, 40320}:
            await interaction.followup.send(_t('text.91f725ecf8beaa'), ephemeral=True)
            return
        self.parent.pending_timeout_minutes = (
            value if value != hp_timeout_minutes(self.parent.guild_id) else None
        )
        await self._stage(interaction)

    @honeypot_operation
    @_i18n_context
    async def select_ban_duration(self, interaction: discord.Interaction) -> None:
        await interaction.response.defer()
        value = int(interaction.data["values"][0])
        if value not in {0, 5, 60, 1440, 10080, 43200}:
            await interaction.followup.send(_t('text.a639592a88ed15'), ephemeral=True)
            return
        # Si Honeypot aún no tiene duración propia, elegir Permanente
        # (0) debe producir un cambio pendiente explícito.
        current = hp_ban_override_minutes(self.parent.guild_id)
        self.parent.pending_ban_minutes = value if current is None or value != current else None
        await self._stage(interaction)

    @honeypot_operation
    @_i18n_context
    async def select_purge(self, interaction: discord.Interaction) -> None:
        await interaction.response.defer()
        value = interaction.data["values"][0]
        allowed = {"none:0", "time:60", "time:360", "time:1440", "time:4320", "time:10080"}
        if value not in allowed:
            await interaction.followup.send(_t('text.8953d5bd49f38d'), ephemeral=True)
            return
        kind, minutes = value.split(":")
        spec = (kind, int(minutes))
        self.parent.pending_purge_spec = (
            spec if spec != hp_purge_spec(self.parent.guild_id) else None
        )
        await self._stage(interaction)


@_i18n_context
def hp_notice_snapshot(guild_id: int) -> tuple:
    """Estado visible del aviso; permite invalidar confirmaciones obsoletas."""
    return (
        hp_warning_enabled(guild_id),
        hp_warning_style(guild_id),
        hp_warning_text(guild_id),
        tuple(sorted(hp_warning_custom(guild_id).items())),
    )


class HoneypotPublishWarningConfirmView(discord.ui.View):
    """Confirmación efímera: ejecutar una sola vez y actualizar el panel de origen."""

    @_i18n_context
    def __init__(
        self, guild_id: int, owner_id: int, *,
        panel_interaction: discord.Interaction | None = None,
        panel_view: discord.ui.View | None = None,
    ) -> None:
        super().__init__(timeout=300)
        self.guild_id = guild_id
        self.owner_id = owner_id
        self.panel_interaction = panel_interaction
        self.panel_view = panel_view
        self.original_traps = set(hp_traps(guild_id))
        self.original_notice = hp_notice_snapshot(guild_id)
        self.finished = False

    @_i18n_context
    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        return await configuration_access(interaction, self.guild_id, self.owner_id)

    @_i18n_context
    async def _dismiss(self, interaction: discord.Interaction) -> None:
        """Quitar el segundo mensaje; si Discord lo impide, retirar sus controles."""
        try:
            await interaction.delete_original_response()
        except discord.HTTPException:
            try:
                await interaction.edit_original_response(content=_t('text.9066d15234c291'), embed=None, view=None)
            except discord.HTTPException:
                print("Honeypot: no se pudo retirar la confirmación temporal.")

    @_i18n_context
    async def _refresh_panel(self, guild: discord.Guild, status: str) -> bool:
        if self.panel_interaction is None or self.panel_view is None:
            return False
        try:
            self.panel_view.last_publication_status = status
            await self.panel_interaction.edit_original_response(
                content=None, embed=self.panel_view._embed(guild), view=self.panel_view,
            )
            return True
        except discord.HTTPException:
            print("Honeypot: no se pudo actualizar el panel después de publicar.")
            return False

    @discord.ui.button(label=_t('text.971971842cc3be'), style=discord.ButtonStyle.success)
    @honeypot_operation
    @_i18n_context
    async def confirm(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        # Aceptar la pulsación ANTES de consultar SQLite o permisos por canal (< 3 s).
        await interaction.response.defer()
        if self.finished:
            await interaction.followup.send(_t('text.1abd43408fdbb0'), ephemeral=True)
            return
        if not await self.interaction_check(interaction):
            self.finished = True
            self.stop()
            await self._dismiss(interaction)
            return
        if self.finished:
            await interaction.followup.send(_t('text.1abd43408fdbb0'), ephemeral=True)
            return

        # No realizar llamadas con await entre la comprobación y el bloqueo del botón.
        self.finished = True
        self.stop()
        guild = interaction.guild
        problem = None
        if (
            guild is None or guild.id != self.guild_id
            or set(hp_traps(self.guild_id)) != self.original_traps
            or hp_notice_snapshot(self.guild_id) != self.original_notice
        ):
            problem = _t('text.b936c38c29a06a')
        elif self.panel_view is not None and self.panel_view.parent._pending_lines(guild):
            problem = _t('text.b0277d01889d0b')
        elif not self.original_traps:
            problem = _t('text.272c3825ceb139')
        else:
            me = guild.me
            for channel_id in sorted(self.original_traps):
                channel = guild.get_channel(channel_id)
                if not isinstance(channel, discord.TextChannel) or me is None:
                    problem = _t('text.0c76ac52a05952')
                    break
                perms = channel.permissions_for(me)
                if not all(
                    getattr(perms, name, False)
                    for name in ("view_channel", "send_messages", "manage_messages",
                                 "read_message_history", "embed_links")
                ):
                    problem = (
                        _t('text.c8dbf72e934a36', p0=f'{channel.mention}')
                    )
                    break
        if problem:
            await interaction.followup.send(problem, ephemeral=True)
            await self._dismiss(interaction)
            return

        errors = None
        try:
            if not hp_warning_enabled(self.guild_id):
                hp_setting_set(self.guild_id, "honeypot_warning_enabled", "1")
            errors = await hp_sync_all_warnings(guild)
        except Exception as exc:
            # Puede haber cambios guardados o avisos publicados parcialmente.
            print(f"Honeypot: sincronización de aviso interrumpida ({type(exc).__name__}).")
            errors = [_t('text.d12eafd0cd6caa')]

        status = (
            _t('text.7052e95d23cf82')
            if errors else _t('text.25319b2ef20482', p0=f'{len(self.original_traps)}')
        )
        refreshed = await self._refresh_panel(guild, status)
        if errors:
            await interaction.followup.send(
                _t('text.a1321bc042d0bf')
                + _i18n_join("\n", (f"• {error}" for error in errors[:8])),
                ephemeral=True,
            )
        elif not refreshed:
            await interaction.followup.send(
                _t('text.95e9609afa3a9b'),
                ephemeral=True,
            )
        await self._dismiss(interaction)

    @discord.ui.button(label=_t('text.bb9dbb406dcbd5'), style=discord.ButtonStyle.danger)
    @_i18n_context
    async def cancel(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        await interaction.response.defer()
        if self.finished:
            await interaction.followup.send(_t('text.1abd43408fdbb0'), ephemeral=True)
            return
        if not await self.interaction_check(interaction):
            return
        if self.finished:
            await interaction.followup.send(_t('text.1abd43408fdbb0'), ephemeral=True)
            return
        self.finished = True
        self.stop()
        # Descartar no cambia la configuración ni publica avisos.
        await self._dismiss(interaction)


class HeraldoHoneypotNoticeView(HeraldoHoneypotSubView):
    @_i18n_context
    def _embed(self, guild: discord.Guild) -> discord.Embed:
        traps = hp_traps(guild.id)
        enabled = hp_warning_enabled(guild.id)
        registered = sum(message_id is not None for message_id in traps.values())
        last_status = getattr(self, "last_publication_status", None)
        return discord.Embed(
            title=_t('text.4c9297e3d8b098'),
            description=(
                _t('text.f21a7d7b083e4f', p0=f"{(_t('text.0a0ca661486c7e') if enabled else _t('text.e252efe6974743'))}", p1=f'{len(traps)}', p2=f'{registered}', p3=f'{len(traps)}')
                + (_t('text.93ed5724be24f0', p0=f'{last_status}') if last_status else "")
                + _t('text.9e0b38fb1b91b0')
            ), color=discord.Color.blurple(),
        )

    # Compatibilidad con vistas antiguas todavía visibles: el editor se abre
    # directamente desde el botón principal; no hay dos editores redundantes.

    @discord.ui.button(label=_t('text.f4421f99c123b7'), style=discord.ButtonStyle.success, row=1)
    @honeypot_operation
    @_i18n_context
    async def publish_warning(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        await interaction.response.defer()
        if self.parent._pending_lines(interaction.guild):
            await interaction.followup.send(
                _t('text.c93f4077803608'), ephemeral=True,
            )
            return
        if not hp_traps(self.parent.guild_id):
            await interaction.followup.send(
                _t('text.ac24f020f7fcb5'), ephemeral=True,
            )
            return
        initially_disabled = not hp_warning_enabled(self.parent.guild_id)
        await interaction.followup.send(
            _t('text.a255305f583f35')
            + (
                _t('text.0094ec4e1c522c')
                if initially_disabled else _t('text.f0d3365a4787b1')
            ),
            view=HoneypotPublishWarningConfirmView(
                self.parent.guild_id, self.parent.owner_id,
                panel_interaction=interaction, panel_view=self,
            ),
            ephemeral=True, wait=True,
        )


