@_i18n_context
def validate_setup_view_layouts(guild_id: int) -> list[str]:
    """Construye las vistas de /setup para detectar errores de layout al arrancar."""
    factories = [
        ("HeraldoSetupView", lambda: HeraldoSetupView(guild_id, 0)),
        ("HeraldoChannelSetupView", lambda: HeraldoChannelSetupView(guild_id, 0)),
        ("HeraldoRoleSetupView", lambda: HeraldoRoleSetupView(guild_id, 0)),
        ("HeraldoOrientationSetupView", lambda: HeraldoOrientationSetupView(guild_id, 0)),
        ("HeraldoMotwSetupView", lambda: HeraldoMotwSetupView(guild_id, 0)),
        ("HeraldoHoneypotSetupView", lambda: HeraldoHoneypotSetupView(guild_id, 0)),
        ("HeraldoVerificationSetupView", lambda: HeraldoVerificationSetupView(guild_id, 0)),
        ("HeraldoRaidSetupView", lambda: HeraldoRaidSetupView(guild_id, 0)),
        ("HeraldoMessagesSetupView", lambda: HeraldoMessagesSetupView(guild_id, 0)),
        ("AutoFeedsHomeView", lambda: __import__("autofeed_setup").AutoFeedsHomeView(globals(), guild_id, 0)),
        ("HeraldoJoinRolesSetupView", lambda: HeraldoJoinRolesSetupView(guild_id, 0)),
        ("HeraldoJoinRolesBasicView", lambda: HeraldoJoinRolesBasicView(guild_id, 0)),
        ("HeraldoJoinRolesUsersView", lambda: HeraldoJoinRolesUsersView(guild_id, 0)),
        ("HeraldoJoinRolesBotsView", lambda: HeraldoJoinRolesBotsView(guild_id, 0)),
        ("HeraldoJoinRolesSyncView", lambda: HeraldoJoinRolesSyncView(guild_id, 0)),
        ("HeraldoModerationSetupView", lambda: HeraldoModerationSetupView(guild_id, 0)),
        ("HeraldoUserReportsSetupView", lambda: HeraldoUserReportsSetupView(guild_id, 0)),
        ('ReportReminderSetupView', lambda: ReportReminderSetupView(guild_id, 0)),
        ("HeraldoDateFormatSetupView", lambda: HeraldoDateFormatSetupView(guild_id, 0)),
        ("HeraldoCasesSetupView", lambda: HeraldoCasesSetupView(guild_id, 0)),
        ("HeraldoCondemnationSetupView", lambda: HeraldoCondemnationSetupView(guild_id, 0)),
        ("HeraldoAutomodSetupView", lambda: HeraldoAutomodSetupView(guild_id, 0)),
        ("CustodioSetupView", lambda: __import__("custodio_setup").CustodioSetupView(
            guild_id, 0, get_setting=guild_config_get,
            save_atomic=verification_atomic_setup_save,
            access_check=configuration_access,
            parent_factory=lambda: HeraldoAutomodSetupView(guild_id, 0))),
        ("HeraldoVerificationHubView", lambda: HeraldoVerificationHubView(guild_id, 0)),
        ("HeraldoLoggingSetupView", lambda: HeraldoLoggingSetupView(guild_id, 0)),
        ("HeraldoReactionRolesSetupView", lambda: HeraldoReactionRolesSetupView(guild_id, 0)),
        ("HeraldoReactionRolesEditorView", lambda: HeraldoReactionRolesEditorView(
            guild_id, 0, {"channel_id": 0, "roles": []})),
        ('DefaultMessageStudioView:verification:preview', lambda: DefaultMessageStudioView(guild_id, 0, "verification", "preview", "messages_setup")),
        ('DefaultMessageStudioView:verification:edit', lambda: DefaultMessageStudioView(guild_id, 0, "verification", "edit", "messages_setup")),
        ("DefaultMessageStudioView:verify_dm:edit", lambda: DefaultMessageStudioView(guild_id, 0, "verify_dm", "edit", "messages_setup")),
        ('DefaultMessageStudioView:suggestions:edit', lambda: DefaultMessageStudioView(guild_id, 0, "suggestions", "edit", "messages_setup")),
        ('DefaultMessageStudioView:honeypot:edit', lambda: DefaultMessageStudioView(guild_id, 0, "honeypot", "edit", "messages_setup")),
        ('DefaultMessageStudioView:condemnation:edit', lambda: DefaultMessageStudioView(guild_id, 0, "condemnation", "edit", "messages_setup")),
        ('LogTemplateEditorView:preview', lambda: LogTemplateEditorView(guild_id, 0, "general", None, "messages_setup", "preview")),
        ('LogTemplateEditorView:edit', lambda: LogTemplateEditorView(guild_id, 0, "general", None, "messages_setup", "edit")),
        ('LogTemplateEditorView:variables', lambda: LogTemplateEditorView(guild_id, 0, "general", None, "messages_setup", "variables")),
    ]
    errors: list[str] = []
    for name, factory in factories:
        try:
            view = factory()
            if len(view.children) > 25:
                errors.append(_t('text.d7b546cda890d2', p0=f'{name}', p1=f'{len(view.children)}'))
            view.stop()
        except Exception as exc:
            errors.append(f"{name}: {type(exc).__name__}: {exc}")
    return errors



class ModerationReactionEditModal(discord.ui.Modal, title=_t('text.bf821eff7cdee7')):
    emoji = discord.ui.TextInput(label=_t('text.61ad8976e650e1'), required=True, max_length=100, placeholder="📢")
    label = discord.ui.TextInput(label=_t('text.1032c6c8175690'), required=True, max_length=100, placeholder=_t('text.94a9eac404c8c6'))

    @_i18n_context
    def __init__(self, parent_view: "HeraldoUserReportsSetupView", index: int | None = None) -> None:
        super().__init__()
        self.parent_view = parent_view
        self.index = index
        self.original_item = (copy.deepcopy(parent_view._working_reactions()[index])
                              if index is not None else None)
        if index is not None:
            item = parent_view._working_reactions()[index]
            self.emoji.default = str(item["emoji"])
            self.label.default = str(item["label"])
        elif not any(_moderation_emoji_key(str(item["emoji"])) == _moderation_emoji_key("❗")
                     for item in parent_view._working_reactions()):
            # Ofrecer la nueva advertencia por defecto sin alterar reglas guardadas.
            self.emoji.default = "❗"
            self.label.default = _t('text.8e0e9e0ddc829f')

    @_i18n_context
    async def on_submit(self, interaction: discord.Interaction) -> None:
        if not await self.parent_view.interaction_check(interaction):
            return
        current = self.parent_view._working_reactions()
        if self.index is not None and (
            self.index >= len(current) or current[self.index] != self.original_item
        ):
            await interaction.response.send_message(
                _t('text.cfe67e323f8a68'),
                ephemeral=True,
            )
            return
        emoji = str(self.emoji).strip()
        label = str(self.label).strip()
        key = _moderation_emoji_key(emoji)
        condemn_key = _moderation_emoji_key(self.parent_view.pending_condemn_emoji or get_condemnation_emoji(self.parent_view.guild_id))
        if key == condemn_key:
            await interaction.response.send_message(_t('text.2bc1816a7a66f6'), ephemeral=True)
            return
        reactions = [dict(item) for item in self.parent_view._working_reactions()]
        for idx, item in enumerate(reactions):
            if idx != self.index and _moderation_emoji_key(str(item["emoji"])) == key:
                await interaction.response.send_message(_t('text.b55e813a54f230'), ephemeral=True)
                return
        if self.index is None:
            if len(reactions) >= MODERATION_REPORT_MAX_REACTIONS:
                await interaction.response.send_message(_t('text.d67febde94a035', p0=f'{MODERATION_REPORT_MAX_REACTIONS}'), ephemeral=True)
                return
            is_default_warning = (key == _moderation_emoji_key("❗")
                                  and label in _i18n_variants('text.8e0e9e0ddc829f'))
            reactions.append({
                "emoji": emoji, "label": label,
                "action": "warn" if is_default_warning else "report",
                "duration_minutes": None, "threshold": 1, "purge_minutes": None,
            })
            self.parent_view.selected_reaction_index = len(reactions) - 1
        else:
            reactions[self.index]["emoji"] = emoji
            reactions[self.index]["label"] = label
            self.parent_view.selected_reaction_index = self.index
        self.parent_view.pending_reactions = reactions
        self.parent_view._rebuild_reaction_select()
        await interaction.response.edit_message(content=self.parent_view._content(interaction.guild), view=self.parent_view)


class ModerationReactionRuleModal(discord.ui.Modal, title=_t('text.514dd71bd7e5a2')):
    duration = discord.ui.TextInput(label=_t('text.2a3916e8138d70'), required=False, max_length=30, placeholder=_t('text.1bc6a17f53e2e0'))
    threshold = discord.ui.TextInput(label=_t('text.95a3680cb2cf17'), required=True, max_length=2, placeholder=_t('text.b6cec808f437ea'))
    purge = discord.ui.TextInput(label=_t('text.b5881bed703bc3'), required=False, max_length=30, placeholder=_t('text.2b130bb3f0addd'))

    @_i18n_context
    def __init__(self, parent_view: "HeraldoUserReportsSetupView", index: int) -> None:
        super().__init__()
        self.parent_view = parent_view
        self.index = index
        item = parent_view._working_reactions()[index]
        self.original_item = copy.deepcopy(item)
        duration = item.get("duration_minutes")
        self.duration.default = format_duration(int(duration)) if duration else "-"
        self.threshold.default = str(item.get("threshold", 1))
        purge = item.get("purge_minutes")
        self.purge.default = format_duration(int(purge)) if purge else "-"
        action = str(item.get("action", "report"))
        if action in {"report", "warn", "kick"}:
            self.remove_item(self.duration)
        if action in {"report", "warn"}:
            self.remove_item(self.purge)

    @_i18n_context
    async def on_submit(self, interaction: discord.Interaction) -> None:
        # La acción pertenece al selector desplegable del editor.
        if not await self.parent_view.interaction_check(interaction):
            return
        current = self.parent_view._working_reactions()
        if self.index >= len(current) or current[self.index] != self.original_item:
            await interaction.response.send_message(
                _t('text.8bd1a2812a098b'),
                ephemeral=True,
            )
            return
        action = str(current[self.index].get("action", "report"))
        if action not in MODERATION_REPORT_ACTIONS:
            await interaction.response.send_message(_t('text.8ffe56f72c4fa8'), ephemeral=True)
            return
        try:
            threshold = int(str(self.threshold).strip())
            if not 1 <= threshold <= 25:
                raise ValueError
        except ValueError:
            await interaction.response.send_message(_t('text.b02743e024cb70'), ephemeral=True)
            return
        duration_raw = str(self.duration).strip().lower()
        duration_minutes = None
        if duration_raw not in {"", "-", "none"} and not i18n.indefinite_input(duration_raw):
            try:
                duration_minutes = parse_duration(duration_raw, 1, (365 if action == "ban" else 28) * 24 * 60)
            except ValueError as exc:
                await interaction.response.send_message(_t('text.9c9f4ce11850c8', p0=f'{exc}'), ephemeral=True)
                return
        if action == "timeout" and duration_minutes is None:
            await interaction.response.send_message(_t('text.b252fbd24e0b1f'), ephemeral=True)
            return
        purge_raw = str(self.purge).strip().lower()
        purge_minutes = None
        if purge_raw not in {"", "-", "0", "none", "no"}:
            try:
                kind, value = parse_purge_spec(purge_raw)
                if kind != "time":
                    raise ValueError(_t('text.e8fb62d4a70f74'))
                purge_minutes = value
            except ValueError as exc:
                await interaction.response.send_message(_t('text.93571df1810510', p0=f'{exc}'), ephemeral=True)
                return
        if action == "warn":
            duration_minutes, purge_minutes, threshold = None, None, 1
        elif action in {"report", "kick"}:
            duration_minutes = None
        if action == "report":
            purge_minutes = None
        if action == "report" and purge_minutes:
            await interaction.response.send_message(
                _t('text.1d6fc3c93fcc5d'), ephemeral=True
            )
            return
        reactions = [dict(item) for item in self.parent_view._working_reactions()]
        reactions[self.index].update(
            action=action, duration_minutes=duration_minutes, threshold=threshold, purge_minutes=purge_minutes
        )
        self.parent_view.pending_reactions = reactions
        self.parent_view.selected_reaction_index = self.index
        self.parent_view._rebuild_reaction_select()
        await interaction.response.edit_message(content=self.parent_view._content(interaction.guild), view=self.parent_view)

class ModerationCondemnEmojiModal(discord.ui.Modal, title=_t('text.d0327face763e5')):
    emoji = discord.ui.TextInput(label=_t('text.419ad2ed6330c4'), required=True, max_length=100, placeholder="☠️")

    @_i18n_context
    def __init__(self, parent_view: "HeraldoUserReportsSetupView") -> None:
        super().__init__()
        self.parent_view = parent_view
        self.emoji.default = parent_view.pending_condemn_emoji or get_condemnation_emoji(parent_view.guild_id)

    @_i18n_context
    async def on_submit(self, interaction: discord.Interaction) -> None:
        if not await self.parent_view.interaction_check(interaction):
            return
        emoji = str(self.emoji).strip()
        if not emoji:
            await interaction.response.send_message(_t('text.37ad1f8c7a9080'), ephemeral=True)
            return
        report_mappings = self.parent_view.pending_reactions
        if report_mappings is None:
            report_mappings = moderation_report_reactions(self.parent_view.guild_id)
        conflict = next((item for item in report_mappings if _moderation_emoji_key(item["emoji"]) == _moderation_emoji_key(emoji)), None)
        if conflict:
            await interaction.response.send_message(
                _t('text.98372568b6db1c', p0=f"{conflict['label']}", p1=f"{moderation_action_label(str(conflict.get('action', 'report')))}", p2=f"{conflict.get('threshold', 1)}"), ephemeral=True)
            return
        self.parent_view.pending_condemn_emoji = emoji
        await interaction.response.edit_message(content=self.parent_view._content(interaction.guild), view=self.parent_view)


class HeraldoWarningLimitSelectView(discord.ui.View):
    """Borrador de política de advertencias y sanciones por reacción."""

    POLICY_ACTIONS = (
        ("warn", _t('text.1cd7c711e626d3'), _t('text.0b8e5264b488f3')),
        ("timeout", _t('text.e57f389344d2ea'), _t('text.453b728c093cf9')),
        ("kick", _t('text.ffb1a9c946e708'), _t('text.b1c0a569c85a27')),
        ("ban", _t('text.e1e571bc9280a3'), _t('text.256fb20269e877')),
        ("condemn", _t('text.49c04f00c2a806'), _t('text.a918d507ed5ae2')),
    )

    @_i18n_context
    def __init__(self, guild_id: int, owner_id: int) -> None:
        super().__init__(timeout=300)
        self.guild_id = guild_id
        self.owner_id = owner_id
        self.original_raw = {
            "moderation_warn_limit": guild_config_get(guild_id, "moderation_warn_limit"),
            "moderation_warn_limit_action": guild_config_get(guild_id, "moderation_warn_limit_action"),
            "moderation_warn_limit_mute_minutes": guild_config_get(guild_id, "moderation_warn_limit_mute_minutes"),
        }
        for key, _, _ in self.POLICY_ACTIONS:
            name = f"moderation_reaction_{key}_enabled"
            self.original_raw[name] = guild_config_get(guild_id, name)
        self.max_warns = moderation_warning_limit(guild_id)
        self.escalation = moderation_warn_escalation_action(guild_id)
        self.mute_minutes = moderation_warn_escalation_duration(guild_id)
        self.enabled_actions = {
            action for action, _, _ in self.POLICY_ACTIONS
            if moderation_report_punishment_enabled(guild_id, action)
        }
        self.max_select = discord.ui.Select(
            placeholder=_t('text.d720988b416352'),
            options=[
                discord.SelectOption(
                    label=_t('text.f43a239b05c658', p0=f'{value}', p1=f"{('s' if value > 1 else '')}"), value=str(value),
                    default=value == self.max_warns,
                ) for value in range(1, MODERATION_WARN_MAX_ALLOWED + 1)
            ], row=0,
        )
        self.max_select.callback = self.select_max
        self.add_item(self.max_select)
        self.escalation_select = discord.ui.Select(
            placeholder=_t('text.a117c67ac9c5cb'),
            options=[
                discord.SelectOption(label=label, value=action, description=hint,
                                     default=action == self.escalation)
                for action, label, hint in (
                    ("none", _t('text.312db41e982943'), _t('text.758ee92b68cc28')),
                    ("timeout", _t('text.22b733ebaab166'), _t('text.17bde07ad7426a')),
                    ("kick", _t('text.ffb1a9c946e708'), _t('text.8f94641e8638ac')),
                    ("ban", _t('text.e1e571bc9280a3'), _t('text.8f94641e8638ac')),
                    ("condemn", _t('text.49c04f00c2a806'), _t('text.e2d4572d506142')),
                )
            ], row=1,
        )
        self.escalation_select.callback = self.select_escalation
        self.add_item(self.escalation_select)
        self.duration_select = discord.ui.Select(
            placeholder=_t('text.6f85e3cd67f8db'),
            options=[
                discord.SelectOption(label=format_duration(minutes), value=str(minutes),
                                     default=minutes == self.mute_minutes)
                for minutes in MODERATION_WARN_ESCALATION_DURATION_CHOICES
            ],
            disabled=self.escalation != "timeout", row=2,
        )
        self.duration_select.callback = self.select_duration
        self.add_item(self.duration_select)
        self.punishment_select = discord.ui.Select(
            placeholder=_t('text.d91694e8816537'),
            options=[
                discord.SelectOption(label=label, value=action, description=hint,
                                     default=action in self.enabled_actions)
                for action, label, hint in self.POLICY_ACTIONS
            ],
            min_values=0, max_values=len(self.POLICY_ACTIONS), row=3,
        )
        self.punishment_select.callback = self.select_punishments
        self.add_item(self.punishment_select)

    @_i18n_context
    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        return await configuration_access(interaction, self.guild_id, self.owner_id)

    @_i18n_context
    def _content(self) -> str:
        names = {"none": _t('text.716ff07341bc5e'), "timeout": _t('text.e57f389344d2ea'), "kick": _t('text.ffb1a9c946e708'),
                 "ban": _t('text.e1e571bc9280a3'), "condemn": _t('text.49c04f00c2a806')}
        toggles = _i18n_join(", ", (label for action, label, _ in self.POLICY_ACTIONS
                            if action in self.enabled_actions)) or _t('text.265a0222634a7a')
        return (
            _t('text.37dd3fcdb335d9', p0=f'{self.max_warns}', p1=f'{self.max_warns}', p2=f'{names[self.escalation]}')
            + (_t('text.2b364d09092d2e', p0=f'{format_duration(self.mute_minutes)}') if self.escalation == "timeout" else "")
            + _t('text.04b35dd633cec1', p0=f'{toggles}')
        )

    @_i18n_context
    async def select_max(self, interaction: discord.Interaction) -> None:
        values = interaction.data.get("values", []) if interaction.data else []
        if len(values) != 1 or values[0] not in {"1", "2", "3", "4", "5"}:
            await interaction.response.send_message(_t('text.c439c98240361c'), ephemeral=True)
            return
        self.max_warns = int(values[0])
        for option in self.max_select.options:
            option.default = option.value == values[0]
        await interaction.response.edit_message(content=self._content(), view=self)

    @_i18n_context
    async def select_escalation(self, interaction: discord.Interaction) -> None:
        values = interaction.data.get("values", []) if interaction.data else []
        if len(values) != 1 or values[0] not in MODERATION_WARN_ESCALATION_ACTIONS:
            await interaction.response.send_message(_t('text.e508b78647e723'), ephemeral=True)
            return
        self.escalation = values[0]
        self.duration_select.disabled = self.escalation != "timeout"
        for option in self.escalation_select.options:
            option.default = option.value == self.escalation
        await interaction.response.edit_message(content=self._content(), view=self)

    @_i18n_context
    async def select_duration(self, interaction: discord.Interaction) -> None:
        values = interaction.data.get("values", []) if interaction.data else []
        if (len(values) != 1 or not values[0].isdigit()
                or int(values[0]) not in MODERATION_WARN_ESCALATION_DURATION_CHOICES):
            await interaction.response.send_message(_t('text.cba64c7ab30b98'), ephemeral=True)
            return
        self.mute_minutes = int(values[0])
        for option in self.duration_select.options:
            option.default = option.value == values[0]
        await interaction.response.edit_message(content=self._content(), view=self)

    @_i18n_context
    async def select_punishments(self, interaction: discord.Interaction) -> None:
        values = interaction.data.get("values", []) if interaction.data else []
        valid = {item[0] for item in self.POLICY_ACTIONS}
        if len(values) != len(set(values)) or not set(values).issubset(valid):
            await interaction.response.send_message(_t('text.ff718844a7e8c1'), ephemeral=True)
            return
        self.enabled_actions = set(values)
        for option in self.punishment_select.options:
            option.default = option.value in self.enabled_actions
        await interaction.response.edit_message(content=self._content(), view=self)

    @discord.ui.button(label=_t('text.bc60796c79da12'), style=discord.ButtonStyle.primary, row=4)
    @_i18n_context
    async def review(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        if any(guild_config_get(self.guild_id, key) != raw
               for key, raw in self.original_raw.items()):
            await interaction.response.send_message(
                _t('text.4f50534b8a3647'), ephemeral=True
            )
            return
        action = self.escalation
        if action != "none" and action in self.enabled_actions:
            required = {"timeout": "moderate_members", "kick": "kick_members",
                        "ban": "ban_members", "condemn": "manage_roles"}[action]
            bot_member = interaction.guild.me
            if bot_member is None or not getattr(bot_member.guild_permissions, required, False):
                await interaction.response.send_message(
                    _t('text.ce1a9baf44fc3f'),
                    ephemeral=True,
                )
                return
        changes = {
            "moderation_warn_limit": str(self.max_warns),
            "moderation_warn_limit_action": self.escalation,
            "moderation_warn_limit_mute_minutes": str(self.mute_minutes),
        }
        for name, _, _ in self.POLICY_ACTIONS:
            changes[f"moderation_reaction_{name}_enabled"] = (
                "1" if name in self.enabled_actions else "0"
            )
        # Omitir valores semánticamente iguales, incluidos los valores predeterminados.
        changes = {
            key: value for key, value in changes.items()
            if (self.original_raw[key] if self.original_raw[key] is not None else
                "3" if key == "moderation_warn_limit" else
                "none" if key == "moderation_warn_limit_action" else
                "60" if key == "moderation_warn_limit_mute_minutes" else "1") != value
        }
        if not changes:
            await interaction.response.send_message(_t('text.ed5c91affb2e42'), ephemeral=True)
            return
        await confirm_configuration(interaction, self.guild_id, changes)

    @discord.ui.button(label=_t('text.bb9dbb406dcbd5'), style=discord.ButtonStyle.danger, row=4)
    @_i18n_context
    async def cancel(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        self.stop()
        await interaction.response.edit_message(
            content=_t('text.40bb00b053beae'), view=None,
        )


REPORT_REMINDER_HELP = (
    _t('text.5ccf4f5f85c482')
)


@_i18n_context
def reminder_settings(guild_id):
    return {key: guild_config_get(guild_id, key) or fallback for key, fallback in {
        "report_reminder_enabled": "0",
        "report_reminder_channel": "0",
        "report_reminder_frequency": "weekly",
        "report_reminder_day": "0",
        "report_reminder_hour": "12",
        "report_reminder_interval": "7d",
        "report_reminder_start": "",
    }.items()}


@_i18n_context
def reminder_preview(guild_id):
    lines = []
    for item in moderation_report_reactions(guild_id):
        if item.get("action") == "warn":
            continue
        lines.append(_t('text.a4b44b483f36fa', p0=f"{item['emoji']}", p1=f"{discord.utils.escape_markdown(str(item['label']))}", p2=f"{item.get('threshold', 1)}"))
    return (_t('text.5d4decf366f299')
            + (_i18n_join("\n", lines) or _t('text.fafc3fe984c376'))
            + _t('text.27ab166caf064d'))[:1900]


class ReportReminderOptionsModal(discord.ui.Modal, title=_t('text.8fc45189cc5975')):
    days = discord.ui.TextInput(label=_t('text.32dd7bcc6f08f2'), placeholder=_t('text.db355ca643a358'), max_length=10)
    date = discord.ui.TextInput(label=_t('text.0fd452b43bf5c7'), placeholder=_t('text.159a055643b7a0'), required=False, max_length=10)
    @_i18n_context
    def __init__(self, parent):
        super().__init__()
        self.parent = parent
        current = parent.pending["report_reminder_interval"]
        self.days.default = current if re.fullmatch(r"(\d+)(s|m|h|d)", current) else f"{current}d"
        self.date.default = parent.pending["report_reminder_start"]
    @_i18n_context
    async def on_submit(self, interaction):
        if not await self.parent.interaction_check(interaction):
            return
        try:
            interval = str(self.days).strip().lower()
            match = re.fullmatch(r"(\d+)(s|m|h|d)", interval)
            if not match:
                raise ValueError()
            number, unit = int(match.group(1)), match.group(2)
            seconds = number * {"s": 1, "m": 60, "h": 3600, "d": 86400}[unit]
            is_test = heraldo_is_test()
            if seconds < (10 if is_test else 86400) or seconds > 365 * 86400 or (unit == "s" and not is_test):
                raise ValueError()
            start = str(self.date).strip()
            if start:
                datetime.strptime(start, "%Y-%m-%d")
        except ValueError:
            await interaction.response.send_message(_t('text.ba197b2069f756'), ephemeral=True)
            return
        self.parent.pending.update(report_reminder_interval=interval, report_reminder_start=start, report_reminder_frequency="custom")
        self.parent._refresh_controls()
        await interaction.response.edit_message(content=self.parent.summary(), view=self.parent)


class ReportReminderSetupView(_SetupDirtySaveView):
    """Editor de recordatorios: borrador separado de activación inmediata."""
    FREQUENCIES = {"daily": _t('text.ffa5b3464a52f5'), "weekly": _t('text.01ab23786167d1'),
                   "fortnightly": _t('text.3c1f686b4ecb2f'),
                   "monthly": _t('text.acacad0708eeed'), "custom": _t('text.4290938ed5e690')}

    @_i18n_context
    def __init__(self, guild_id, owner_id):
        super().__init__(timeout=900)
        self.guild_id, self.owner_id = guild_id, owner_id
        self.original = reminder_settings(guild_id)
        self.original_raw = {key: guild_config_get(guild_id, key) for key in self.original}
        self.pending = dict(self.original)
        self.selectors = {}
        self.weekday_names = (_t('text.d0e80862185ff7'), _t('text.fff8867b824e73'),
                              _t('text.0635bc16ddbe4c'), _t('text.ca7b8cbccb8fd8'),
                              _t('text.7e9a9f126f1f58'), _t('text.f7a8575b1a8fe0'),
                              _t('text.424e93aa513406'))
        menus = [
            ("report_reminder_frequency", 0, list(self.FREQUENCIES.items())),
            ("report_reminder_day", 1, [(str(i), label) for i, label in enumerate(self.weekday_names)]),
            ("report_reminder_hour", 2, [(str(i), f"{i:02d}:00") for i in range(24)]),
        ]
        placeholders = {
            "report_reminder_frequency": _t('text.e1867c7f9bb33f'),
            "report_reminder_day": _t('text.443602a5f76f49'),
            "report_reminder_hour": _t('text.a956c649a226cc'),
        }
        for field, row, options in menus:
            select = discord.ui.Select(
                placeholder=placeholders[field], row=row,
                options=[discord.SelectOption(label=label, value=value,
                           default=value == self.pending[field]) for value, label in options],
            )

            @_i18n_context
            async def change(interaction, name=field, control=select):
                value = (interaction.data or {}).get("values", [None])[0]
                if value not in {item.value for item in control.options}:
                    await interaction.response.edit_message(
                        content=self.summary(_t('text.a7c68929bd9fe8')), view=self)
                    return
                if name == "report_reminder_frequency" and value == "custom":
                    # Elegir «Personalizado» abre los parámetros reales del intervalo.
                    await interaction.response.send_modal(ReportReminderOptionsModal(self))
                    return
                self.pending[name] = value
                if name == "report_reminder_frequency" and value != "custom":
                    # Un ancla oculta de otro modo no puede afectar la nueva frecuencia.
                    self.pending["report_reminder_start"] = ""
                self._refresh_controls()
                await interaction.response.edit_message(content=self.summary(), view=self)

            select.callback = change
            self.selectors[field] = select
            self.add_item(select)
        channel = discord.ui.ChannelSelect(
            placeholder=_t('text.231c902172232f'),
            channel_types=[discord.ChannelType.text], row=3,
        )
        channel.callback = self.channel_changed
        self.channel_select = channel
        self.add_item(channel)
        self._refresh_controls()

    @_i18n_context
    async def interaction_check(self, interaction):
        return await configuration_access(interaction, self.guild_id, self.owner_id)

    def _has_pending_changes(self):
        return any(self.pending[key] != self.original[key]
                   for key in self.pending if key != "report_reminder_enabled")

    @_i18n_context
    def _refresh_controls(self):
        for field, select in self.selectors.items():
            for option in select.options:
                option.default = option.value == self.pending[field]
        # El selector de día únicamente se utiliza en el modo semanal.
        day_select = self.selectors["report_reminder_day"]
        if self.pending["report_reminder_frequency"] == "weekly":
            if day_select not in self.children:
                self.add_item(day_select)
        elif day_select in self.children:
            self.remove_item(day_select)
        channel_id = int(self.pending["report_reminder_channel"])
        self.channel_select.default_values = (
            [discord.SelectDefaultValue(id=channel_id, type=discord.SelectDefaultValueType.channel)]
            if channel_id else []
        )
        enabled = self.original["report_reminder_enabled"] == "1"
        self.toggle.label = _t('text.7ef1cd2d3486b2') if enabled else _t('text.8e38c2571d87f6')
        self.toggle.style = discord.ButtonStyle.danger if enabled else discord.ButtonStyle.success
        self.confirm.disabled = not self._has_pending_changes()

    @_i18n_context
    def summary(self, notice=""):
        p = self.pending
        frequency = p["report_reminder_frequency"]
        detail = self.FREQUENCIES.get(frequency, frequency)
        if frequency == "weekly":
            detail += f" ({self.weekday_names[int(p['report_reminder_day'])]})"
        elif frequency == "custom":
            detail += f" ({p['report_reminder_interval']})"
        channel_id = int(p["report_reminder_channel"])
        channel = f"<#{channel_id}>" if channel_id else _t('text.3488019931bf2e')
        now = datetime.now(timezone.utc)
        due = None
        if p == self.original:
            signature = guild_config_get(self.guild_id, "report_reminder_signature")
            saved = guild_config_get(self.guild_id, "report_reminder_next_due")
            if saved and signature == json.dumps(p, sort_keys=True):
                try:
                    candidate = datetime.fromisoformat(saved)
                    if candidate.tzinfo is not None and candidate > now:
                        due = candidate
                except ValueError:
                    pass
        if due is None:
            due = reminder_next_due(p, now)
        state = (_t('text.0a0ca661486c7e') if self.original["report_reminder_enabled"] == "1"
                 else _t('text.e252efe6974743'))
        content = _t('text.2e2c1ff499c328', p0=f'{REPORT_REMINDER_HELP}',
                     p1=f'{state}', p2=f'{detail}',
                     p3=f"{int(p['report_reminder_hour']):02d}", p4=f'{channel}',
                     p5=f'{format_configured_datetime(self.guild_id, due)}')
        return content + (f"\n\n{notice}" if notice else "")

    @_i18n_context
    async def channel_changed(self, interaction):
        values = (interaction.data or {}).get("values", [])
        channel = interaction.guild.get_channel(int(values[0])) if values else None
        if not isinstance(channel, discord.TextChannel):
            await interaction.response.edit_message(
                content=self.summary(_t('text.41863cde0a5312')), view=self)
            return
        me = interaction.guild.me
        perms = channel.permissions_for(me) if me else None
        if not perms or not (perms.view_channel and perms.send_messages and perms.embed_links):
            await interaction.response.edit_message(
                content=self.summary(_t('text.000135b3cd2a46')), view=self)
            return
        self.pending["report_reminder_channel"] = str(channel.id)
        self._refresh_controls()
        await interaction.response.edit_message(content=self.summary(), view=self)

    @discord.ui.button(label=_t('text.af283098bcccea'), style=discord.ButtonStyle.primary, row=4)
    @_i18n_context
    async def custom(self, interaction, button):
        await interaction.response.send_modal(ReportReminderOptionsModal(self))

    @discord.ui.button(label=_t('text.c5341f198fc2f4'), style=discord.ButtonStyle.secondary, row=4)
    @_i18n_context
    async def preview(self, interaction, button):
        await interaction.response.send_message(content=reminder_preview(self.guild_id), ephemeral=True)

    @discord.ui.button(label=_t('text.8e38c2571d87f6'), style=discord.ButtonStyle.success, row=4)
    @_i18n_context
    async def toggle(self, interaction, button):
        # Activar/desactivar persiste únicamente el estado, jamás otros borradores.
        enabled = self.original["report_reminder_enabled"] == "1"
        if not enabled:
            saved = reminder_settings(self.guild_id)
            channel = interaction.guild.get_channel(int(saved["report_reminder_channel"]))
            me = interaction.guild.me
            perms = channel.permissions_for(me) if isinstance(channel, discord.TextChannel) and me else None
            if not perms or not (perms.view_channel and perms.send_messages and perms.embed_links):
                await interaction.response.edit_message(
                    content=self.summary(_t('text.949b46403f79ae')), view=self)
                return
        next_state = "0" if enabled else "1"
        if not verification_atomic_setup_save(
            self.guild_id,
            {"report_reminder_enabled": self.original_raw["report_reminder_enabled"]},
            {"report_reminder_enabled": next_state},
        ):
            await interaction.response.edit_message(
                content=self.summary(_t('text.b1b45910f213f2')), view=self)
            return
        self.original_raw["report_reminder_enabled"] = next_state
        self.original["report_reminder_enabled"] = next_state
        self.pending["report_reminder_enabled"] = next_state
        self._refresh_controls()
        await interaction.response.edit_message(content=self.summary(), view=self)

    @discord.ui.button(label=_t('text.14bdfaf2face3a'), style=discord.ButtonStyle.success, row=4)
    @_i18n_context
    async def confirm(self, interaction, button):
        # Guardar solo campos de programación; activar es una operación independiente.
        changes = {k: v for k, v in self.pending.items()
                   if k != "report_reminder_enabled" and v != self.original[k]}
        if not changes:
            await interaction.response.edit_message(
                content=self.summary(_t('text.ed5c91affb2e42')), view=self)
            return
        if self.original["report_reminder_enabled"] == "1":
            channel = interaction.guild.get_channel(int(self.pending["report_reminder_channel"]))
            me = interaction.guild.me
            perms = channel.permissions_for(me) if isinstance(channel, discord.TextChannel) and me else None
            if not perms or not (perms.view_channel and perms.send_messages and perms.embed_links):
                await interaction.response.edit_message(
                    content=self.summary(_t('text.000135b3cd2a46')), view=self)
                return
        if not verification_atomic_setup_save(
            self.guild_id,
            {key: self.original_raw[key] for key in changes},
            changes,
        ):
            await interaction.response.edit_message(
                content=self.summary(_t('text.b1b45910f213f2')), view=self)
            return
        self.original = reminder_settings(self.guild_id)
        self.original_raw = {key: guild_config_get(self.guild_id, key) for key in self.original}
        self.pending = dict(self.original)
        self._refresh_controls()
        await interaction.response.edit_message(content=self.summary(), view=self)

    @discord.ui.button(label=_t('text.ab26ae7bca3621'), style=discord.ButtonStyle.secondary, row=4)
    @_i18n_context
    async def cancel(self, interaction, button):
        # Volver descarta el borrador sin generar otro mensaje.
        self.stop()
        parent = HeraldoUserReportsSetupView(self.guild_id, self.owner_id)
        await interaction.response.edit_message(content=parent._content(interaction.guild), view=parent)


def reminder_next_due(settings, now):
    """Calcula una fecha futura en horario de Santo Domingo (UTC-4)."""
    local = now.astimezone(timezone(timedelta(hours=-4)))
    hour = max(0, min(23, int(settings["report_reminder_hour"])))
    candidate = local.replace(hour=hour, minute=0, second=0, microsecond=0)
    frequency = settings["report_reminder_frequency"]
    if frequency == "daily":
        days = 1
    elif frequency == "weekly":
        days = 7
        candidate += timedelta(days=(int(settings["report_reminder_day"]) - candidate.weekday()) % 7)
    elif frequency == "fortnightly":
        days = 14
    elif frequency == "monthly":
        days = None  # Los meses no tienen siempre 30 días.
    else:
        interval = str(settings["report_reminder_interval"]).lower()
        match = re.fullmatch(r"(\d+)(s|m|h|d)", interval)
        if match:
            seconds = int(match.group(1)) * {"s": 1, "m": 60, "h": 3600, "d": 86400}[match.group(2)]
        else:
            seconds = max(1, min(365, int(interval))) * 86400  # configuración heredada
        is_test = heraldo_is_test()
        seconds = max(10 if is_test else 86400, min(seconds, 365 * 86400))
        days = None
    start = settings["report_reminder_start"]
    if frequency in {"custom", "fortnightly", "monthly"} and start:
        try:
            candidate = datetime.strptime(start, "%Y-%m-%d").replace(
                tzinfo=timezone(timedelta(hours=-4)), hour=hour)
        except ValueError:
            pass
    # Evitar millones de iteraciones si un intervalo corto parte de una fecha antigua.
    # Se salta directamente al próximo vencimiento, sin recuperar avisos omitidos.
    if frequency == "custom" and candidate <= local:
        elapsed = (local - candidate).total_seconds()
        steps = int(elapsed // seconds) + 1
        candidate += timedelta(seconds=steps * seconds)
    while candidate <= local:
        if frequency == "monthly":
            import calendar
            next_year = candidate.year + (candidate.month == 12)
            next_month = candidate.month % 12 + 1
            day = min(candidate.day, calendar.monthrange(next_year, next_month)[1])
            candidate = candidate.replace(year=next_year, month=next_month, day=day)
        elif frequency == "custom":
            candidate += timedelta(seconds=seconds)
        else:
            candidate += timedelta(days=days)
    return candidate.astimezone(timezone.utc)


@tasks.loop(seconds=10)
@_i18n_context
async def report_reminders_loop():
    """No ejecuta publicaciones atrasadas ni repite envíos de resultado incierto."""
    now = datetime.now(timezone.utc)
    for guild in bot.guilds:
        with _i18n_guild(guild.id):
            settings = reminder_settings(guild.id)
            if settings["report_reminder_enabled"] != "1":
                continue
            channel = guild.get_channel(int(settings["report_reminder_channel"]))
            if not isinstance(channel, discord.TextChannel):
                continue
            me = guild.me
            perms = channel.permissions_for(me) if me is not None else None
            if perms is None or not (perms.view_channel and perms.send_messages and perms.embed_links):
                continue
            signature = json.dumps(settings, sort_keys=True)
            next_due_key = "report_reminder_next_due"
            signature_key = "report_reminder_signature"
            try:
                conn = db_connect()
                try:
                    conn.execute("BEGIN IMMEDIATE")
                    rows = conn.execute(
                        "SELECT key, value FROM guild_settings WHERE guild_id = ? AND key IN (?, ?)",
                        (guild.id, next_due_key, signature_key)).fetchall()
                    stored = {row[0]: row[1] for row in rows}
                    if stored.get(signature_key) != signature or not stored.get(next_due_key):
                        next_due = reminder_next_due(settings, now)
                        claim = False
                    else:
                        try:
                            next_due = datetime.fromisoformat(stored[next_due_key])
                            if next_due.tzinfo is None:
                                raise ValueError("naive datetime")
                        except ValueError:
                            next_due = reminder_next_due(settings, now)
                        claim = next_due <= now
                        if claim:
                            next_due = reminder_next_due(settings, now)
                    for key, value in (
                        (next_due_key, next_due.isoformat()), (signature_key, signature)
                    ):
                        conn.execute(
                            "INSERT INTO guild_settings(guild_id, key, value) VALUES (?, ?, ?) "
                            "ON CONFLICT(guild_id, key) DO UPDATE SET value=excluded.value",
                            (guild.id, key, value))
                    conn.commit()
                finally:
                    conn.close()
                if claim:
                    # La fecha siguiente se persiste antes de enviar, para no duplicar
                    # notificaciones tras fallos ambiguos o reinicios.
                    await channel.send(content=reminder_preview(guild.id),
                                       allowed_mentions=discord.AllowedMentions.none())
            except (discord.HTTPException, sqlite3.Error, ValueError, TypeError):
                print(f"Advertencia: recordatorio pendiente en servidor {guild.id}")
            except Exception:
                traceback.print_exc()


@report_reminders_loop.before_loop
async def before_report_reminders_loop():
    await bot.wait_until_ready()


class HeraldoUserReportsSetupView(_SetupDirtySaveView):
    @_i18n_context
    def __init__(self, guild_id: int, owner_id: int) -> None:
        super().__init__(timeout=900)
        self.guild_id = guild_id
        self.owner_id = owner_id
        self.original_channel_id = moderation_report_channel_id(guild_id)
        self.original_reactions = copy.deepcopy(moderation_report_reactions(guild_id))
        self.original_condemn_emoji = get_condemnation_emoji(guild_id)
        self.pending_channel_id: int | None = None
        self.pending_reactions: list[dict[str, object]] | None = None
        self.pending_condemn_emoji: str | None = None
        self.selected_reaction_index: int | None = None

        channel_select = discord.ui.ChannelSelect(
            placeholder=_t('text.f942fe90afc8fb'),
            channel_types=[discord.ChannelType.text], min_values=1, max_values=1, row=0,
        )
        channel_select.callback = self.select_channel
        self.channel_select = channel_select
        self.add_item(channel_select)
        self.reaction_select: discord.ui.Select | None = None
        self.action_select: discord.ui.Select | None = None
        self._rebuild_reaction_select()

    @_i18n_context
    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if not await configuration_access(interaction, getattr(self, "guild_id", None), getattr(self, "owner_id", None)):
            return False
        if interaction.user.id != self.owner_id:
            await interaction.response.send_message(_t('text.62876186654ca2'), ephemeral=True)
            return False
        return True

    @_i18n_context
    def _working_reactions(self) -> list[dict[str, object]]:
        return self.pending_reactions if self.pending_reactions is not None else moderation_report_reactions(self.guild_id)

    @_i18n_context
    def _has_pending_changes(self) -> bool:
        return (
            (self.pending_channel_id is not None and self.pending_channel_id != self.original_channel_id)
            or (self.pending_reactions is not None and self.pending_reactions != self.original_reactions)
            or (self.pending_condemn_emoji is not None and self.pending_condemn_emoji != self.original_condemn_emoji)
        )

    @_i18n_context
    def _update_change_buttons(self) -> None:
        pending = self._has_pending_changes()
        self.save_changes.disabled = not pending
        self.discard_changes.disabled = not pending

    @_i18n_context
    def _rebuild_reaction_select(self) -> None:
        channel_id = self.pending_channel_id if self.pending_channel_id is not None else moderation_report_channel_id(self.guild_id)
        self.channel_select.default_values = [discord.SelectDefaultValue(id=channel_id, type=discord.SelectDefaultValueType.channel)] if channel_id else []
        if self.reaction_select is not None:
            self.remove_item(self.reaction_select)
        reactions = self._working_reactions()
        if reactions:
            options = []
            for index, item in enumerate(reactions):
                action = moderation_action_label(str(item.get("action", "report")))
                options.append(discord.SelectOption(
                    label=str(item["label"])[:100],
                    value=str(index),
                    emoji=str(item["emoji"]),
                    description=_t('text.680fbc1439e5d9', p0=f'{action}', p1=f"{item.get('threshold', 1)}")[:100],
                    default=index == self.selected_reaction_index,
                ))
            select = discord.ui.Select(placeholder=_t('text.12e8b2e1b81bc6', p0=f'{len(reactions)}', p1=f'{MODERATION_REPORT_MAX_REACTIONS}'), options=options, row=1)
            select.callback = self.select_reaction
        else:
            select = discord.ui.Select(
                placeholder=_t('text.2afbaf2ddb19ac', p0=f'{MODERATION_REPORT_MAX_REACTIONS}'),
                options=[discord.SelectOption(label=_t('text.bb5fb436e507c8'), value="-1")],
                disabled=True, row=1,
            )
        self.reaction_select = select
        self.add_item(select)
        self._rebuild_action_select()

    @_i18n_context
    def _rebuild_action_select(self) -> None:
        if self.action_select is not None:
            self.remove_item(self.action_select)
        reactions = self._working_reactions()
        index = self.selected_reaction_index
        selected = reactions[index] if index is not None and 0 <= index < len(reactions) else None
        current_action = str(selected.get("action", "report")) if selected else "report"
        selector = discord.ui.Select(
            placeholder=_t('text.f65de190f1d526'),
            options=[
                discord.SelectOption(
                    label=moderation_action_label(action),
                    value=action,
                    default=action == current_action,
                )
                for action in ("report", "warn", "timeout", "condemn", "kick", "ban")
            ],
            disabled=selected is None,
            row=2,
        )
        selector.callback = self.select_action
        self.action_select = selector
        self.add_item(selector)

    @_i18n_context
    async def select_action(self, interaction: discord.Interaction) -> None:
        values = interaction.data.get("values", []) if interaction.data else []
        index = self.selected_reaction_index
        if (index is None or not 0 <= index < len(self._working_reactions())
                or len(values) != 1 or values[0] not in MODERATION_REPORT_ACTIONS):
            await interaction.response.send_message(
                _t('text.28eb346ddb3bda'), ephemeral=True
            )
            return
        reactions = [dict(item) for item in self._working_reactions()]
        reactions[index]["action"] = values[0]
        if values[0] in {"report", "warn"}:
            # Los reportes y las advertencias no eliminan mensajes.
            reactions[index]["purge_minutes"] = None
        if values[0] == "warn":
            reactions[index]["threshold"] = 1
        if values[0] in {"report", "warn", "kick"}:
            # Estas acciones no admiten duración; evita presentar valores inertes.
            reactions[index]["duration_minutes"] = None
        self.pending_reactions = reactions
        self._rebuild_reaction_select()
        notice = ""
        if values[0] == "report":
            notice = _t('text.580d87e754e049')
        elif values[0] == "warn":
            notice = _t('text.cef0650db563d1')
        elif values[0] == "timeout" and not reactions[index].get("duration_minutes"):
            notice = _t('text.3fa31273f517a8')
        await interaction.response.edit_message(
            content=self._content(interaction.guild) + notice, view=self
        )

    @_i18n_context
    def _content(self, guild: discord.Guild) -> str:
        lines: list[str] = []
        if self.pending_channel_id is not None:
            channel = guild.get_channel(self.pending_channel_id)
            lines.append(_t('text.e62f0ac567bc4e', p0=f'{(channel.mention if channel else self.pending_channel_id)}'))
        if self.pending_reactions is not None:
            lines.append(_t('text.c5a00598549be6', p0=f'{len(self.pending_reactions)}', p1=f'{MODERATION_REPORT_MAX_REACTIONS}'))
        if self.pending_condemn_emoji is not None:
            lines.append(_t('text.e9f7f1658486ac', p0=f'{self.pending_condemn_emoji}'))
        selected = ""
        if self.selected_reaction_index is not None:
            reactions = self._working_reactions()
            if 0 <= self.selected_reaction_index < len(reactions):
                item = reactions[self.selected_reaction_index]
                duration = item.get("duration_minutes")
                purge = item.get("purge_minutes")
                action = str(item.get("action", "report"))
                count = int(item.get("threshold", 1))
                selected = (
                    _t('text.38f433a153bd0c', p0=f"{item['emoji']}", p1=f"{item['label']}", p2=f"{moderation_action_label(str(item.get('action', 'report')))}", p3=f"{item.get('threshold', 1)}", p4=f"{(format_duration(int(duration)) if duration else '—')}", p5=f"{(format_duration(int(purge)) if purge else '—')}")
                )
                if action in {"kick", "ban", "condemn", "timeout"} and count == 1:
                    selected += (_t('text.56ee47204bd8bb'))
                if action == "report":
                    selected += _t('text.6656b0ec84cd62')
                if action == "warn":
                    selected += _t('text.31356e07a872d3')
                if action != "report" and not moderation_report_punishment_enabled(self.guild_id, action):
                    selected += _t('text.5a539c121a985b')
        intro = (
            _t('text.faed972736a746')
        )
        mappings = self._working_reactions()
        missing_warn = not any(
            _moderation_emoji_key(str(item["emoji"])) == _moderation_emoji_key("❗")
            for item in mappings
        )
        summary = (
            _t('text.0e5542a9e970ee', p0=f"{(guild.get_channel(self.pending_channel_id or moderation_report_channel_id(self.guild_id)).mention if guild.get_channel(self.pending_channel_id or moderation_report_channel_id(self.guild_id)) else _t('text.8cc0006879d214'))}", p1=f'{len(mappings)}', p2=f'{MODERATION_REPORT_MAX_REACTIONS}', p3=f'{self.pending_condemn_emoji or get_condemnation_emoji(self.guild_id)}')
        )
        summary += _t('text.e42323779714b5')
        for rule in mappings:
            rule_action = str(rule.get("action", "report"))
            rule_threshold = int(rule.get("threshold", 1))
            detail = (_t('text.674b76beacb483') if rule_action == "warn" else
                      _t('text.b8ef40b5f3af4b', p0=f'{rule_threshold}'))
            summary += (
                f"\n• {rule['emoji']} {discord.utils.escape_markdown(str(rule['label'])[:65])}"
                f" — {moderation_action_label(rule_action)}{detail}"
            )
        if missing_warn:
            summary += (
                _t('text.cb80a3d3306241')
            )
        action = moderation_warn_escalation_action(self.guild_id)
        current_action = moderation_action_label(action) if action != "none" else _t('text.716ff07341bc5e')
        self._update_change_buttons()
        status = (_t('text.4abebc9d84559b')
                  if self._has_pending_changes() else
                  _t('text.1d80f366987dbc'))
        result = (
            intro + status + "\n\n" + summary +
            _t('text.08a77fc07f1356', p0=f'{moderation_warning_limit(self.guild_id)}', p1=f'{current_action}') + selected +
            _pending_config_text(lines)
        )
        return result if len(result) <= 1900 else result[:1870] + "…"

    @_i18n_context
    async def select_channel(self, interaction: discord.Interaction) -> None:
        values = interaction.data.get("values") if interaction.data else []
        channel = interaction.guild.get_channel(int(values[0])) if interaction.guild and values else None
        if not isinstance(channel, discord.TextChannel):
            await interaction.response.send_message(_t('text.ebf7fffd23a15f'), ephemeral=True)
            return
        perms = channel.permissions_for(interaction.guild.me)
        if not perms.view_channel or not perms.send_messages or not perms.embed_links:
            await interaction.response.send_message(_t('text.4c7df17845a6e4'), ephemeral=True)
            return
        self.pending_channel_id = channel.id if channel.id != moderation_report_channel_id(self.guild_id) else None
        await interaction.response.edit_message(content=self._content(interaction.guild), view=self)

    @_i18n_context
    async def select_reaction(self, interaction: discord.Interaction) -> None:
        values = interaction.data.get("values") if interaction.data else []
        if not values:
            return
        index = int(values[0])
        if index < 0 or index >= len(self._working_reactions()):
            await interaction.response.send_message(_t('text.0f4386bd84f4de'), ephemeral=True)
            return
        self.selected_reaction_index = index
        self._rebuild_reaction_select()
        await interaction.response.edit_message(content=self._content(interaction.guild), view=self)

    @discord.ui.button(label=_t('text.7542a5e800f928'), style=discord.ButtonStyle.primary, row=3)
    @_i18n_context
    async def add_reaction(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        if len(self._working_reactions()) >= MODERATION_REPORT_MAX_REACTIONS:
            await interaction.response.send_message(_t('text.54fff582eb3560'), ephemeral=True)
            return
        await interaction.response.send_modal(ModerationReactionEditModal(self))

    @discord.ui.button(label=_t('text.2eba946b2e1ee4'), style=discord.ButtonStyle.primary, row=3)
    @_i18n_context
    async def edit_reaction(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        if self.selected_reaction_index is None:
            await interaction.response.send_message(_t('text.fefdd091b33688'), ephemeral=True)
            return
        await interaction.response.send_modal(ModerationReactionEditModal(self, self.selected_reaction_index))

    @discord.ui.button(label=_t('text.668c44cf8ac64a'), style=discord.ButtonStyle.primary, row=3)
    @_i18n_context
    async def edit_rule(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        if self.selected_reaction_index is None:
            await interaction.response.send_message(_t('text.fefdd091b33688'), ephemeral=True)
            return
        if self._working_reactions()[self.selected_reaction_index].get("action") == "warn":
            await interaction.response.send_message(
                _t('text.95823f94c892b9'), ephemeral=True,
            )
            return
        await interaction.response.send_modal(ModerationReactionRuleModal(self, self.selected_reaction_index))

    @discord.ui.button(label=_t('text.c9894cf002f90b'), style=discord.ButtonStyle.danger, row=3)
    @_i18n_context
    async def delete_reaction(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        if self.selected_reaction_index is None:
            await interaction.response.send_message(_t('text.fefdd091b33688'), ephemeral=True)
            return
        reactions = [dict(item) for item in self._working_reactions()]
        reactions.pop(self.selected_reaction_index)
        self.pending_reactions = reactions
        self.selected_reaction_index = None
        self._rebuild_reaction_select()
        await interaction.response.edit_message(content=self._content(interaction.guild), view=self)

    @discord.ui.button(label=_t('text.711046588fb778'), style=discord.ButtonStyle.primary, row=3)
    @_i18n_context
    async def edit_condemn_emoji(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        await interaction.response.send_modal(ModerationCondemnEmojiModal(self))

    @discord.ui.button(label=_t('text.19bd5bd18edc40'), style=discord.ButtonStyle.primary, row=4)
    @_i18n_context
    async def configure_warn_limit(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        warn_view = HeraldoWarningLimitSelectView(self.guild_id, self.owner_id)
        await interaction.response.send_message(
            content=warn_view._content(), view=warn_view, ephemeral=True,
        )

    @discord.ui.button(label=_t('text.471b155a597e21'), style=discord.ButtonStyle.primary, row=4)
    @_i18n_context
    async def reminders(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        view = ReportReminderSetupView(self.guild_id, self.owner_id)
        await interaction.response.send_message(content=view.summary(), view=view, ephemeral=True)

    @discord.ui.button(label=_t('text.14bdfaf2face3a'), style=discord.ButtonStyle.success, row=4)
    @_i18n_context
    async def save_changes(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        if not self._has_pending_changes():
            await interaction.response.send_message(_t('text.ed5c91affb2e42'), ephemeral=True)
            return
        if ((self.pending_channel_id is not None
             and moderation_report_channel_id(self.guild_id) != self.original_channel_id)
            or (self.pending_reactions is not None
                and moderation_report_reactions(self.guild_id) != self.original_reactions)
            or (self.pending_condemn_emoji is not None
                and get_condemnation_emoji(self.guild_id) != self.original_condemn_emoji)):
            await interaction.response.send_message(
                _t('text.66b012815db79e'),
                ephemeral=True,
            )
            return
        if self.pending_reactions is not None:
            condemn_key = _moderation_emoji_key(self.pending_condemn_emoji or get_condemnation_emoji(self.guild_id))
            if any(_moderation_emoji_key(str(item["emoji"])) == condemn_key for item in self.pending_reactions):
                await interaction.response.send_message(_t('text.185bf7c31329e9'), ephemeral=True)
                return
        if self.pending_reactions is not None:
            for item in self.pending_reactions:
                action = str(item.get("action", "report"))
                if action not in MODERATION_REPORT_ACTIONS:
                    await interaction.response.send_message(
                        _t('text.6e0cdcfd9a78ab'), ephemeral=True
                    )
                    return
                if action == "timeout" and not item.get("duration_minutes"):
                    await interaction.response.send_message(
                        _t('text.2329182331a344'),
                        ephemeral=True,
                    )
                    return
                if action in {"report", "warn"} and item.get("purge_minutes"):
                    await interaction.response.send_message(
                        _t('text.e344fdb22ad7c4'), ephemeral=True
                    )
                    return
                if action == "warn" and (item.get("duration_minutes") or int(item.get("threshold", 1)) != 1):
                    await interaction.response.send_message(
                        _t('text.ad36a2ab9b2b8d'), ephemeral=True
                    )
                    return
                required = {"timeout": "moderate_members", "kick": "kick_members",
                            "ban": "ban_members", "condemn": "manage_roles"}.get(action)
                bot_member = interaction.guild.me
                if required and (
                    bot_member is None or
                    not getattr(bot_member.guild_permissions, required, False)
                ):
                    await interaction.response.send_message(
                        _t('text.61080b9bcd7ec2', p0=f'{moderation_action_label(action)}'), ephemeral=True,
                    )
                    return
        if self.pending_channel_id is not None:
            channel = interaction.guild.get_channel(self.pending_channel_id)
            me = interaction.guild.me
            perms = channel.permissions_for(me) if channel and me else None
            if not isinstance(channel, discord.TextChannel) or perms is None or not (
                perms.view_channel and perms.send_messages and perms.embed_links
            ):
                await interaction.response.send_message(
                    _t('text.d3f18b1206cc71'),
                    ephemeral=True,
                )
                return
            set_moderation_report_channel_id(self.guild_id, self.pending_channel_id)
        if self.pending_reactions is not None:
            set_moderation_report_reactions(self.guild_id, self.pending_reactions)
        if self.pending_condemn_emoji is not None:
            guild_config_set(self.guild_id, "condemnation_emoji", self.pending_condemn_emoji)
        self.original_channel_id = moderation_report_channel_id(self.guild_id)
        self.original_reactions = copy.deepcopy(moderation_report_reactions(self.guild_id))
        self.original_condemn_emoji = get_condemnation_emoji(self.guild_id)
        self.pending_channel_id = None
        self.pending_reactions = None
        self.pending_condemn_emoji = None
        self._rebuild_reaction_select()
        await interaction.response.edit_message(content=self._content(interaction.guild) + _t('text.f1c5938f74bc84'), view=self)

    @discord.ui.button(label=_t('text.80ca383e9c8d3e'), style=discord.ButtonStyle.danger, row=4)
    @_i18n_context
    async def discard_changes(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        if not self._has_pending_changes():
            await interaction.response.send_message(_t('text.ed5c91affb2e42'), ephemeral=True)
            return
        self.original_channel_id = moderation_report_channel_id(self.guild_id)
        self.original_reactions = copy.deepcopy(moderation_report_reactions(self.guild_id))
        self.original_condemn_emoji = get_condemnation_emoji(self.guild_id)
        self.pending_channel_id = None
        self.pending_reactions = None
        self.pending_condemn_emoji = None
        self.selected_reaction_index = None
        self._rebuild_reaction_select()
        await interaction.response.edit_message(content=self._content(interaction.guild), view=self)

    @discord.ui.button(label=_t('text.ab26ae7bca3621'), style=discord.ButtonStyle.secondary, row=4)
    @_i18n_context
    async def back(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        await interaction.response.edit_message(
            content=_t('text.da10e9d8927c80'),
            view=HeraldoModerationSetupView(self.guild_id, self.owner_id),
        )

