class HeraldoLoggingSetupView(_SetupDirtySaveView):
    @_i18n_context
    def __init__(self, guild_id: int, owner_id: int) -> None:
        super().__init__(timeout=900)
        self.guild_id = guild_id
        self.owner_id = owner_id
        self.pending_channel_id: int | None = None
        channel_select = discord.ui.ChannelSelect(
            placeholder=_t('text.81556d95932396'),
            channel_types=[discord.ChannelType.text],
            min_values=1,
            max_values=1,
            row=0,
        )
        channel_select.callback = self.select_channel
        self.add_item(channel_select)

    @_i18n_context
    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if not await configuration_access(interaction, getattr(self, "guild_id", None), getattr(self, "owner_id", None)):
            return False
        if interaction.user.id != self.owner_id:
            await interaction.response.send_message(_t('text.62876186654ca2'), ephemeral=True)
            return False
        return True

    @_i18n_context
    def _content(self, guild: discord.Guild) -> str:
        current_id = get_log_channel_id(guild.id)
        current = guild.get_channel(current_id) if current_id else None
        pending = ""
        if self.pending_channel_id is not None:
            channel = guild.get_channel(self.pending_channel_id)
            pending = _pending_config_text([_t('text.e4f392810a0a15', p0=f'{(channel.mention if channel else self.pending_channel_id)}')])
        return (
            _t('text.382de606e84361', p0=f"{(current.mention if isinstance(current, discord.TextChannel) else _t('text.1372367d605704'))}")
            + pending
        )

    @_i18n_context
    async def select_channel(self, interaction: discord.Interaction) -> None:
        values = interaction.data.get("values") if interaction.data else []
        channel = interaction.guild.get_channel(int(values[0])) if interaction.guild and values else None
        if not isinstance(channel, discord.TextChannel):
            await interaction.response.send_message(_t('text.ebf7fffd23a15f'), ephemeral=True)
            return
        perms = channel.permissions_for(interaction.guild.me)
        if not perms.view_channel or not perms.send_messages or not perms.embed_links:
            await interaction.response.send_message(
                _t('text.4c7df17845a6e4'),
                ephemeral=True,
            )
            return
        self.pending_channel_id = channel.id
        await interaction.response.edit_message(content=self._content(interaction.guild), view=self)

    @discord.ui.button(label=_t('text.591ad46e52c514'), style=discord.ButtonStyle.success, row=1)
    @_i18n_context
    async def create_channel(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        guild = interaction.guild
        existing_id = get_guild_channel_id(self.guild_id, "logs")
        channel = guild.get_channel(existing_id) if existing_id else None
        created_now = False
        if not isinstance(channel, discord.TextChannel):
            channel = next((c for c in guild.text_channels if c.name.casefold() == "el heraldo"), None)
        if not isinstance(channel, discord.TextChannel):
            me = guild.me
            if me is None or not me.guild_permissions.manage_channels:
                await interaction.response.send_message(
                    _t('text.bd94a0fe68e159'),
                    ephemeral=True,
                )
                return
            await interaction.response.defer(ephemeral=True)
            try:
                channel = await guild.create_text_channel(
                    "El Heraldo",
                    reason=_t('text.cec6595513cd39'),
                )
                created_now = True
            except discord.HTTPException as exc:
                await interaction.followup.send(_t('text.87fdaf1cf9fb80', p0=f'{exc}'), ephemeral=True)
                return
        else:
            await interaction.response.defer(ephemeral=True)

        note = await _setup_apply_system_channel(guild, "logs", channel, publish_messages=True)
        self.pending_channel_id = None
        action = _t('text.ff1122df900644') if created_now else _t('text.b97b60aadab055')
        await interaction.edit_original_response(
            content=self._content(guild) + f"\n\n{action} {channel.mention}. {note}",
            view=self,
        )

    @discord.ui.button(label=_t('text.e336ec4a16522a'), style=discord.ButtonStyle.primary, row=1)
    @_i18n_context
    async def member_events(self, interaction, button):
        view = HeraldoMemberLogSetupView(self.guild_id, self.owner_id)
        await interaction.response.edit_message(content=view.content(interaction.guild), view=view)

    @discord.ui.button(label=_t('text.14bdfaf2face3a'), style=discord.ButtonStyle.success, row=2)
    @_i18n_context
    async def save(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        if self.pending_channel_id is None:
            await interaction.response.send_message(_t('text.ed5c91affb2e42'), ephemeral=True)
            return
        channel = interaction.guild.get_channel(self.pending_channel_id)
        if not isinstance(channel, discord.TextChannel):
            await interaction.response.send_message(_t('text.9d15f25e1ef27d'), ephemeral=True)
            return
        await interaction.response.defer(ephemeral=True)
        note = await _setup_apply_system_channel(interaction.guild, "logs", channel, publish_messages=True)
        self.pending_channel_id = None
        await interaction.edit_original_response(content=self._content(interaction.guild) + _t('text.2dd2e8b6b55d3e', p0=f'{note}'), view=self)

    @discord.ui.button(label=_t('text.80ca383e9c8d3e'), style=discord.ButtonStyle.danger, row=2)
    @_i18n_context
    async def discard(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        self.pending_channel_id = None
        await interaction.response.edit_message(content=self._content(interaction.guild), view=self)

    @discord.ui.button(label=_t('text.ab26ae7bca3621'), style=discord.ButtonStyle.secondary, row=2)
    @_i18n_context
    async def back(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        await heraldo_setup_go_home(interaction, self.guild_id, self.owner_id)



MEMBER_LOG_EVENTS = ("member_leave", "member_kick", "member_ban", "member_warn")


@_i18n_context
def log_member_event_enabled(guild_id: int, event_key: str) -> bool:
    return event_key in MEMBER_LOG_EVENTS and guild_config_get(guild_id, f"log_member.enabled.{event_key}") == "1"


@_i18n_context
def log_member_channel_id(guild_id: int, event_key: str) -> int:
    value = guild_config_get(guild_id, f"log_member.channel.{event_key}")
    return int(value) if value and value.isdecimal() else get_log_channel_id(guild_id)



class ExitCommentSetupView(_SetupDirtySaveView):
    @_i18n_context
    def __init__(self, guild_id: int, owner_id: int):
        super().__init__(timeout=900)
        self.guild_id, self.owner_id = guild_id, owner_id
        self.pending: bool | None = None

    @_i18n_context
    async def interaction_check(self, interaction):
        if not await configuration_access(interaction, self.guild_id, self.owner_id):
            return False
        if interaction.guild_id != self.guild_id or interaction.user.id != self.owner_id:
            await interaction.response.send_message(_t('text.321291a0c8ce78'), ephemeral=True)
            return False
        return True

    @_i18n_context
    def content(self, guild):
        enabled = self.pending if self.pending is not None else exit_comments_enabled(self.guild_id)
        channel = guild.get_channel(log_member_channel_id(self.guild_id, "member_leave"))
        private = isinstance(channel, discord.TextChannel) and exit_comment_private(channel)
        return (_t('text.5bdf2e75e1c129', p0=f"{(_t('text.14c93a0dfe8ec6') if enabled else _t('text.5a9c65149cd523'))}", p1=f"{(_t('common.yes') if private else _t('common.no'))}"))

    @discord.ui.button(label=_t('text.0cfccadccb64bc'), style=discord.ButtonStyle.primary, row=0)
    @_i18n_context
    async def toggle(self, interaction, button):
        self.pending = not (self.pending if self.pending is not None
                            else exit_comments_enabled(self.guild_id))
        await interaction.response.edit_message(content=self.content(interaction.guild), view=self)

    @discord.ui.button(label=_t('text.14bdfaf2face3a'), style=discord.ButtonStyle.success, row=1)
    @_i18n_context
    async def save(self, interaction, button):
        if self.pending is None:
            await interaction.response.send_message(_t('text.ed5c91affb2e42'), ephemeral=True)
            return
        guild = interaction.guild
        channel = guild.get_channel(log_member_channel_id(self.guild_id, "member_leave"))
        if self.pending and (not log_member_event_enabled(self.guild_id, "member_leave")
                             or not isinstance(channel, discord.TextChannel)
                             or not exit_comment_private(channel)
                             or not guild.me.guild_permissions.view_audit_log):
            await interaction.response.send_message(
                _t('text.9a064584b48c48'),
                ephemeral=True)
            return
        guild_config_set(self.guild_id, "exit_comments_enabled", "1" if self.pending else "0")
        self.pending = None
        await interaction.response.edit_message(content=self.content(guild)+_t('text.f1c5938f74bc84'), view=self)

    @discord.ui.button(label=_t('text.80ca383e9c8d3e'), style=discord.ButtonStyle.danger, row=1)
    @_i18n_context
    async def discard(self, interaction, button):
        self.pending = None
        await interaction.response.edit_message(content=self.content(interaction.guild), view=self)

    @discord.ui.button(label=_t('text.ab26ae7bca3621'), style=discord.ButtonStyle.secondary, row=1)
    @_i18n_context
    async def back(self, interaction, button):
        back_view = HeraldoMemberLogSetupView(self.guild_id, self.owner_id)
        await interaction.response.edit_message(content=back_view.content(interaction.guild),
                                                view=back_view)


class HeraldoMemberLogSetupView(_SetupDirtySaveView):
    @_i18n_context
    def __init__(self, guild_id: int, owner_id: int):
        super().__init__(timeout=900)
        self.guild_id, self.owner_id = guild_id, owner_id
        self.event_key = "member_leave"
        self.pending_enabled = None
        self.pending_channel_id = None
        self.event_select = discord.ui.Select(placeholder=_t('text.a8d498c452b340'), row=0, options=[
            discord.SelectOption(label=label, value=key,
                description=(_t('text.cb5a761240123d') if key == "member_leave"
                             else _t('text.e88756a2ea549c')),
                default=False)
            for key, label in LOG_EVENT_CATALOG["members"]
        ])
        self.event_select.callback = self.select_event
        self.add_item(self.event_select)
        channel = discord.ui.ChannelSelect(placeholder=_t('text.3ce38675df574f'), row=1,
            channel_types=[discord.ChannelType.text], min_values=1, max_values=1)
        channel.callback = self.select_channel
        self.add_item(channel)
        self.exit_comments_button = discord.ui.Button(
            label=_t('text.f6d509bc854508'), style=discord.ButtonStyle.secondary, row=3)
        self.exit_comments_button.callback = self.open_exit_comments
        self.add_item(self.exit_comments_button)

    @_i18n_context
    async def open_exit_comments(self, interaction):
        if self.event_key != "member_leave":
            await interaction.response.send_message(
                _t('text.31e85c652ac7b2'),
                ephemeral=True)
            return
        view = ExitCommentSetupView(self.guild_id, self.owner_id)
        await interaction.response.edit_message(content=view.content(interaction.guild),
                                                view=view)

    @_i18n_context
    async def interaction_check(self, interaction):
        if not await configuration_access(interaction, getattr(self, "guild_id", None), getattr(self, "owner_id", None)):
            return False
        if interaction.guild_id != self.guild_id or interaction.user.id != self.owner_id:
            await interaction.response.send_message(_t('text.be3da0eec9647b'), ephemeral=True)
            return False
        if not interaction.user.guild_permissions.manage_guild:
            await interaction.response.send_message(_t('text.8f4af6d0e301ae'), ephemeral=True)
            return False
        return True

    @_i18n_context
    def content(self, guild):
        name = dict(LOG_EVENT_CATALOG["members"])[self.event_key]
        enabled = self.pending_enabled if self.pending_enabled is not None else log_member_event_enabled(self.guild_id, self.event_key)
        channel_id = self.pending_channel_id if self.pending_channel_id is not None else log_member_channel_id(self.guild_id, self.event_key)
        channel = guild.get_channel(channel_id)
        destination = channel.mention if isinstance(channel, discord.TextChannel) else _t('text.5a28de985686c2')
        return (_t('text.24c5574feda7ed', p0=f'{name}', p1=f"{(_t('text.723858144bd548') if enabled else _t('text.06423d1ac3a6ee'))}", p2=f'{destination}'))

    @_i18n_context
    async def select_event(self, interaction):
        values = (interaction.data or {}).get("values", [])
        if values and values[0] in MEMBER_LOG_EVENTS:
            self.event_key = values[0]
            self.pending_enabled = None
            self.pending_channel_id = None
            self.exit_comments_button.disabled = self.event_key != "member_leave"
            for option in self.event_select.options:
                option.default = option.value == self.event_key
        await interaction.response.edit_message(content=self.content(interaction.guild), view=self)

    @_i18n_context
    async def select_channel(self, interaction):
        values = (interaction.data or {}).get("values", [])
        channel = interaction.guild.get_channel(int(values[0])) if values else None
        if not isinstance(channel, discord.TextChannel):
            await interaction.response.send_message(_t('text.08c9773db74b9f'), ephemeral=True)
            return
        perms = channel.permissions_for(interaction.guild.me)
        if not all((perms.view_channel, perms.send_messages, perms.embed_links)):
            await interaction.response.send_message(_t('text.4773cb41ed50f5'), ephemeral=True)
            return
        self.pending_channel_id = channel.id
        await interaction.response.edit_message(content=self.content(interaction.guild), view=self)

    @discord.ui.button(label=_t('text.0cfccadccb64bc'), style=discord.ButtonStyle.primary, row=2)
    @_i18n_context
    async def toggle(self, interaction, button):
        enabled = self.pending_enabled if self.pending_enabled is not None else log_member_event_enabled(self.guild_id, self.event_key)
        self.pending_enabled = not enabled
        await interaction.response.edit_message(content=self.content(interaction.guild), view=self)

    @discord.ui.button(label=_t('text.14bdfaf2face3a'), style=discord.ButtonStyle.success, row=2)
    @_i18n_context
    async def save(self, interaction, button):
        if self.pending_channel_id is None and self.pending_enabled is None:
            await interaction.response.send_message(_t('text.ed5c91affb2e42'), ephemeral=True)
            return
        channel_id = self.pending_channel_id if self.pending_channel_id is not None else log_member_channel_id(self.guild_id, self.event_key)
        channel = interaction.guild.get_channel(channel_id)
        if self.pending_enabled and not isinstance(channel, discord.TextChannel):
            await interaction.response.send_message(_t('text.c4b3da831fc1fa'), ephemeral=True)
            return
        if isinstance(channel, discord.TextChannel):
            perms = channel.permissions_for(interaction.guild.me)
            if not all((perms.view_channel, perms.send_messages, perms.embed_links)):
                await interaction.response.send_message(_t('text.a82c121f0f4ac5'), ephemeral=True)
                return
        if self.pending_channel_id is not None:
            guild_config_set(self.guild_id, f"log_member.channel.{self.event_key}", str(self.pending_channel_id))
        if self.pending_enabled is not None:
            guild_config_set(self.guild_id, f"log_member.enabled.{self.event_key}", "1" if self.pending_enabled else "0")
        self.pending_enabled, self.pending_channel_id = None, None
        for option in self.event_select.options:
            option.default = False
        await interaction.response.edit_message(content=self.content(interaction.guild) + _t('text.f1c5938f74bc84'), view=self)

    @discord.ui.button(label=_t('text.1a878a55c594b0'), style=discord.ButtonStyle.danger, row=3)
    @_i18n_context
    async def discard(self, interaction, button):
        self.pending_enabled, self.pending_channel_id = None, None
        for option in self.event_select.options:
            option.default = False
        await interaction.response.edit_message(content=self.content(interaction.guild), view=self)

    @discord.ui.button(label=_t('text.ab26ae7bca3621'), style=discord.ButtonStyle.secondary, row=3)
    @_i18n_context
    async def back(self, interaction, button):
        view = HeraldoLoggingSetupView(self.guild_id, self.owner_id)
        await interaction.response.edit_message(content=view._content(interaction.guild), view=view)


# Reaction Roles general: independiente del panel obligatorio de personalidad.
@_i18n_context
def reaction_role_panels(guild_id: int) -> list[dict]:
    try:
        raw = json.loads(guild_config_get(guild_id, "reaction_role_panels") or "[]")
        return raw if isinstance(raw, list) else []
    except (TypeError, ValueError, json.JSONDecodeError):
        return []


@_i18n_context
def reaction_role_panel_find(guild_id: int, message_id: int) -> dict | None:
    return next((p for p in reaction_role_panels(guild_id) if int(p.get("message_id", 0)) == message_id), None)


@_i18n_context
def reaction_role_panels_save(guild_id: int, panels: list[dict]) -> None:
    guild_config_set(guild_id, "reaction_role_panels", json.dumps(panels, ensure_ascii=False))



def rr_bindings(panel: dict) -> list[dict]:
    """Read both Sapphire-style bindings and legacy one-role panels."""
    return [{"emoji": str(x["emoji"]),
             "add": [int(v) for v in x.get("add", [x["role_id"]] if "role_id" in x else [])],
             "remove": [int(v) for v in x.get("remove", [])]}
            for x in panel.get("roles", []) if x.get("emoji")]


@_i18n_context
def rr_summary(guild: discord.Guild, panel: dict) -> str:
    result = [_t('text.0ebcd5deccd8af'),
              _t('text.10c1aeee46e43b', p0=f"{panel.get('message_id') or _t('text.328bc5dfae45bf')}"),
              _t('text.d98e6fefdf52d8', p0=f"{panel['channel_id']}"),
              _t('text.f691a9aa49d3f5', p0=f"{(_t('text.76feb26017a785') if panel.get('reversed') else _t('text.a7248eeb45eb1c'))}"),
              _t('text.38d6afa05aee67', p0=f"{panel.get('max_reactions') or _t('text.553f5b2ff5d004')}"),
              _t('text.485077e3658ded', p0=f"{i18n.fixed_label(panel.get('list_mode', 'Todos'))}")]
    if panel.get("allowed_roles"):
        result.append(_t('text.4efc4db0c1b16e') + _i18n_join(", ", (f"<@&{r}>" for r in panel["allowed_roles"])))
    result.append(_t('text.2c0288a39361ff'))
    for binding in rr_bindings(panel):
        adds = _i18n_join(", ", (f"<@&{r}>" for r in binding["add"])) or _t('text.9e3fc69d0d9cdc')
        removes = _i18n_join(", ", (f"<@&{r}>" for r in binding["remove"])) or _t('text.9e3fc69d0d9cdc')
        result.append(_t('text.3f0ed7d099331a', p0=f"{binding['emoji']}", p1=f'{adds}', p2=f'{removes}'))
    if not rr_bindings(panel):
        result.append(_t('text.ef6ff65865ae0f'))
    return _i18n_join("\n", result)


@_i18n_context
def rr_valid_role(guild: discord.Guild, role_id: int) -> bool:
    role = guild.get_role(role_id)
    return bool(role and role.is_assignable() and not role.managed and not role.is_default()
                and self_service_role_safe(role))


@_i18n_context
def rr_can_use(member: discord.Member, panel: dict) -> bool:
    mode = panel.get("list_mode", "Todos")
    allowed = set(int(x) for x in panel.get("allowed_roles", []))
    present = bool(allowed.intersection(r.id for r in member.roles))
    return (mode != "Lista blanca" or present) and (mode != "Lista negra" or not present)


@_i18n_context
def rr_panel_upsert(guild_id: int, panel: dict) -> None:
    panels = reaction_role_panels(guild_id)
    panels = [p for p in panels if int(p.get("message_id", 0)) != int(panel["message_id"])]
    panels.append(panel)
    reaction_role_panels_save(guild_id, panels)


class HeraldoReactionEmojiModal(discord.ui.Modal, title=_t('text.51ced4ce20b298')):
    emoji = discord.ui.TextInput(label=_t('text.61ad8976e650e1'), placeholder=_t('text.96f6f8b12ecf65'), max_length=100)

    @_i18n_context
    def __init__(self, editor: "HeraldoReactionRolesEditorView"):
        super().__init__()
        self.editor = editor

    @_i18n_context
    async def on_submit(self, interaction: discord.Interaction) -> None:
        value = str(self.emoji.value).strip()
        try:
            parsed = discord.PartialEmoji.from_str(value)
            if not value or (parsed.id and not interaction.guild.get_emoji(parsed.id)):
                raise ValueError()
        except (ValueError, TypeError):
            await interaction.response.send_message(_t('text.3521548bc781af'), ephemeral=True)
            return
        key = _orientation_emoji_key(value)
        bindings = rr_bindings(self.editor.panel)
        if any(_orientation_emoji_key(x["emoji"]) == key for x in bindings):
            await interaction.response.send_message(_t('text.a89368b34ddb66'), ephemeral=True)
            return
        if len(bindings) >= 20:
            await interaction.response.send_message(_t('text.6ad0421dcd6309'), ephemeral=True)
            return
        bindings.append({"emoji": value, "add": [], "remove": []})
        self.editor.panel["roles"] = bindings
        self.editor.selected = len(bindings) - 1
        await interaction.response.edit_message(
            content=self.editor.content(interaction.guild),
            view=HeraldoReactionRolesEditorView(self.editor.guild_id, self.editor.owner_id, self.editor.panel,
                                                selected=self.editor.selected))


class HeraldoReactionOptionsModal(discord.ui.Modal, title=_t('text.2046b60ec4f504')):
    maximum = discord.ui.TextInput(label=_t('text.a8f312a08f77fe'), default="0", max_length=2)
    mode = discord.ui.TextInput(label=_t('reaction.access_mode'), placeholder=_t('text.ee2bc5a98b39d8'), default=_t('access.all'), max_length=20)
    reverse_mode = discord.ui.TextInput(label=_t('text.728733b87fc656'), default=_t("common.no"), max_length=3)

    @_i18n_context
    def __init__(self, editor: "HeraldoReactionRolesEditorView"):
        super().__init__()
        self.editor = editor
        self.maximum.default = str(editor.panel.get("max_reactions", 0))
        self.mode.default = i18n.fixed_label(editor.panel.get("list_mode", "Todos"))
        self.reverse_mode.default = _t('common.yes') if editor.panel.get("reversed") else _t('common.no')

    @_i18n_context
    async def on_submit(self, interaction: discord.Interaction) -> None:
        mode = i18n.canonical_fixed(str(self.mode.value).strip()).casefold()
        normalized = {"todos": "Todos", "lista blanca": "Lista blanca",
                      "lista negra": "Lista negra"}.get(mode)
        reverse_value = str(self.reverse_mode.value).strip().casefold()
        if reverse_value not in ('sí', 'si', 'no', 'nao', 'não', 'sim', 'yes'):
            await interaction.response.send_message(_t('text.a6de10190c40ba'), ephemeral=True)
            return
        if not str(self.maximum.value).strip().isdigit() or int(self.maximum.value) > 20 or not normalized:
            await interaction.response.send_message(_t('text.1eea586c811b57'), ephemeral=True)
            return
        self.editor.panel["max_reactions"] = int(self.maximum.value)
        self.editor.panel["list_mode"] = normalized
        self.editor.panel["reversed"] = reverse_value in ('sí', 'si', 'sim', 'yes')
        await interaction.response.edit_message(
            content=self.editor.content(interaction.guild),
            view=HeraldoReactionRolesEditorView(self.editor.guild_id, self.editor.owner_id, self.editor.panel,
                                                selected=self.editor.selected))


class HeraldoReactionOptionsSelectView(discord.ui.View):
    """Editor de opciones cerradas sin solicitar valores que ya conoce El Heraldo."""
    @_i18n_context
    def __init__(self, editor: "HeraldoReactionRolesEditorView",
                 original_panel: dict | None = None) -> None:
        super().__init__(timeout=900)
        self.guild_id = editor.guild_id
        self.owner_id = editor.owner_id
        self.selected = editor.selected
        self.original_panel = copy.deepcopy(original_panel if original_panel is not None else editor.panel)
        self.panel = copy.deepcopy(editor.panel)

        access_mode = discord.ui.Select(
            placeholder=_t('text.1fd1f4c1ddad94'),
            options=[
                discord.SelectOption(label=i18n.fixed_label(mode), value=mode,
                    default=self.panel.get("list_mode", "Todos") == mode)
                for mode in ("Todos", "Lista blanca", "Lista negra")
            ], row=0,
        )
        access_mode.callback = self.select_access_mode
        self.add_item(access_mode)

        reversed_select = discord.ui.Select(
            placeholder=_t('text.76feb26017a785'),
            options=[
                discord.SelectOption(label=_t("common.yes"), value="true",
                                     default=bool(self.panel.get("reversed"))),
                discord.SelectOption(label=_t("common.no"), value="false",
                                     default=not bool(self.panel.get("reversed"))),
            ], row=1,
        )
        reversed_select.callback = self.select_reversed
        self.add_item(reversed_select)

        maximum = discord.ui.Select(
            placeholder=_t('text.5ff97ea363a0d4'),
            options=[
                discord.SelectOption(
                    label=_t('text.553f5b2ff5d004') if count == 0 else _t('text.b8c78e2c8b0584', p0=f'{count}'),
                    value=str(count),
                    default=int(self.panel.get("max_reactions", 0)) == count,
                )
                for count in range(21)
            ], row=2,
        )
        maximum.callback = self.select_maximum
        self.add_item(maximum)

    @_i18n_context
    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        return await configuration_access(interaction, self.guild_id, self.owner_id)

    @_i18n_context
    def content(self) -> str:
        return (
            _t('text.e67153314b9596', p0=f"{i18n.fixed_label(self.panel.get('list_mode', 'Todos'))}", p1=f"{(_t('common.yes') if self.panel.get('reversed') else _t('common.no'))}", p2=f"{self.panel.get('max_reactions', 0) or _t('text.553f5b2ff5d004')}")
        )

    @_i18n_context
    async def _change(self, interaction: discord.Interaction, key: str, value) -> None:
        self.panel[key] = value
        updated = HeraldoReactionOptionsSelectView(
            HeraldoReactionRolesEditorView(
                self.guild_id, self.owner_id, self.panel, selected=self.selected
            ),
            original_panel=self.original_panel,
        )
        await interaction.response.edit_message(content=updated.content(), view=updated)

    @_i18n_context
    async def select_access_mode(self, interaction: discord.Interaction) -> None:
        value = str((interaction.data or {}).get("values", [""])[0])
        if value not in {"Todos", "Lista blanca", "Lista negra"}:
            await interaction.response.send_message(_t('text.dde11711f6ef33'), ephemeral=True)
            return
        await self._change(interaction, "list_mode", value)

    @_i18n_context
    async def select_reversed(self, interaction: discord.Interaction) -> None:
        value = str((interaction.data or {}).get("values", [""])[0])
        if value not in {"true", "false"}:
            await interaction.response.send_message(_t('text.890b5b7f1b1a84'), ephemeral=True)
            return
        await self._change(interaction, "reversed", value == "true")

    @_i18n_context
    async def select_maximum(self, interaction: discord.Interaction) -> None:
        value = str((interaction.data or {}).get("values", [""])[0])
        if not value.isdecimal() or not 0 <= int(value) <= 20:
            await interaction.response.send_message(_t('text.bec33c8b9b8402'), ephemeral=True)
            return
        await self._change(interaction, "max_reactions", int(value))

    @discord.ui.button(label=_t('text.3cef74bb7a9f35'), style=discord.ButtonStyle.primary, row=3)
    @_i18n_context
    async def apply(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        editor = HeraldoReactionRolesEditorView(
            self.guild_id, self.owner_id, self.panel, selected=self.selected
        )
        await interaction.response.edit_message(
            content=editor.content(interaction.guild), view=editor
        )

    @discord.ui.button(label=_t('text.1a878a55c594b0'), style=discord.ButtonStyle.danger, row=3)
    @_i18n_context
    async def cancel(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        editor = HeraldoReactionRolesEditorView(
            self.guild_id, self.owner_id, self.original_panel, selected=self.selected
        )
        await interaction.response.edit_message(
            content=editor.content(interaction.guild), view=editor
        )


