class HeraldoReactionRoleCreateModal(discord.ui.Modal, title=_t('text.c5522072295cc8')):
    role_name = discord.ui.TextInput(label=_t('text.26aee0d02ad63c'), max_length=100)

    @_i18n_context
    def __init__(self, editor: "HeraldoReactionRolesEditorView", action: str):
        super().__init__()
        if action not in ("add", "remove"):
            raise ValueError(_t('text.423e87d55fe64d'))
        self.editor = editor
        self.action = action
        self.submitting = False

    @_i18n_context
    async def on_submit(self, interaction: discord.Interaction) -> None:
        guild = interaction.guild
        if (guild is None or guild.id != self.editor.guild_id
                or interaction.user.id != self.editor.owner_id):
            await interaction.response.send_message(_t('text.be0580569b16d5'), ephemeral=True)
            return
        user_perms = getattr(interaction.user, "guild_permissions", discord.Permissions.none())
        if not user_perms.manage_roles or guild.me is None or not guild.me.guild_permissions.manage_roles:
            await interaction.response.send_message(
                _t('text.297068b7d1864d'), ephemeral=True)
            return
        name = str(self.role_name.value).strip()
        bindings = rr_bindings(self.editor.panel)
        if not name:
            await interaction.response.send_message(_t('text.abf9898b5a3b9e'), ephemeral=True)
            return
        if not bindings or self.editor.selected >= len(bindings):
            await interaction.response.send_message(_t('text.9f534727bc1946'), ephemeral=True)
            return
        if len(bindings[self.editor.selected][self.action]) >= 10:
            await interaction.response.send_message(
                _t('text.71536beee42f5f'), ephemeral=True)
            return
        if self.submitting:
            await interaction.response.send_message(_t('text.683cee4de8151c'), ephemeral=True)
            return
        self.submitting = True
        await interaction.response.defer()
        try:
            role = await guild.create_role(
                name=name, permissions=discord.Permissions.none(), mentionable=False, hoist=False,
                reason=_t('text.e1bbe06a1ae0e8', p0=f'{interaction.user.id}'),
            )
        except discord.HTTPException:
            self.submitting = False
            await interaction.followup.send(
                _t('text.df86660f9899d1'),
                ephemeral=True,
            )
            return
        bindings[self.editor.selected][self.action].append(role.id)
        self.editor.panel["roles"] = bindings
        updated = HeraldoReactionRolesEditorView(
            self.editor.guild_id, self.editor.owner_id, self.editor.panel,
            selected=self.editor.selected, created_role=role,
        )
        await interaction.edit_original_response(
            content=updated.content(guild) + (
                _t('text.fff331093852fa', p0=f'{role.mention}', p1=f"{(_t('text.c111b23eebb712') if self.action == 'add' else _t('text.8b3e56fd0b7a21'))}")
            ),
            view=updated,
        )


class HeraldoReactionRolesEditorView(_SetupDirtySaveView):
    @_i18n_context
    def __init__(self, guild_id: int, owner_id: int, panel: dict, selected: int = 0,
                 created_role: discord.Role | None = None):
        super().__init__(timeout=900)
        self.guild_id, self.owner_id, self.panel = guild_id, owner_id, copy.deepcopy(panel)
        bindings = rr_bindings(panel)
        self.selected = max(0, min(selected, len(bindings) - 1)) if bindings else 0
        active = bindings[self.selected] if bindings else None
        guild = bot.get_guild(guild_id)

        def role_defaults(role_ids: list[int]) -> list[discord.Role]:
            if guild is None:
                return []
            return [
                role for role_id in role_ids[:10]
                if (role := guild.get_role(int(role_id)) or (
                    created_role if created_role and created_role.id == int(role_id) else None
                )) is not None
            ]

        if bindings:
            picker = discord.ui.Select(
                placeholder=_t('text.ab0ff7a1f030e6', p0=f"{active['emoji']}"),
                options=[
                    discord.SelectOption(
                        label=str(x["emoji"])[:80],
                        value=str(i),
                        description=_t('text.34466a782ab2a8', p0=f"{len(x['add'])}", p1=f"{len(x['remove'])}"),
                        default=i == self.selected,
                    )
                    for i, x in enumerate(bindings[:20])
                ] + [
                    discord.SelectOption(
                        label=_t('text.d963a81d9520f9'),
                        value="create_add",
                        description=_t('text.3266b21dafbef0'),
                    ),
                    discord.SelectOption(
                        label=_t('text.5b87a7b52e36f1'),
                        value="create_remove",
                        description=_t('text.3266b21dafbef0'),
                    ),
                    discord.SelectOption(
                        label=_t('text.88b70f19f25cb6'),
                        value="remove_selected",
                        description=_t('text.580cfc4d2e643f', p0=f"{active['emoji']}"),
                    )
                ],
                row=0,
            )
            picker.callback = self.select_emoji
            self.add_item(picker)

        active_emoji = active["emoji"] if active else _t('text.06e8595ce10864')
        role_add = discord.ui.RoleSelect(
            placeholder=_t('text.5111df02e6b508', p0=f'{active_emoji}'),
            min_values=0,
            max_values=10,
            default_values=role_defaults(active["add"] if active else []),
            row=1,
        )
        role_add.callback = self.set_add
        self.add_item(role_add)

        role_remove = discord.ui.RoleSelect(
            placeholder=_t('text.c7d8db62f634df', p0=f'{active_emoji}'),
            min_values=0,
            max_values=10,
            default_values=role_defaults(active["remove"] if active else []),
            row=2,
        )
        role_remove.callback = self.set_remove
        self.add_item(role_remove)

        access = discord.ui.RoleSelect(
            placeholder=_t('text.69ac4a95cf9b26'),
            min_values=0,
            max_values=10,
            default_values=role_defaults([int(x) for x in panel.get("allowed_roles", [])]),
            row=3,
        )
        access.callback = self.set_access
        self.add_item(access)

    @_i18n_context
    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if not await configuration_access(interaction, getattr(self, "guild_id", None), getattr(self, "owner_id", None)):
            return False
        if interaction.user.id != self.owner_id:
            await interaction.response.send_message(_t('text.be0580569b16d5'), ephemeral=True)
            return False
        return True

    @_i18n_context
    def content(self, guild: discord.Guild) -> str:
        bindings = rr_bindings(self.panel)
        if not bindings:
            selected_text = _t('text.265a0222634a7a')
        else:
            active = bindings[self.selected]
            selected_text = f"{active['emoji']} ({self.selected + 1}/{len(bindings)})"
        return rr_summary(guild, self.panel) + (
            _t('text.a0ddda0a56485d', p0=f'{selected_text}')
        )

    @_i18n_context
    async def select_emoji(self, interaction: discord.Interaction) -> None:
        value = interaction.data["values"][0]
        bindings = rr_bindings(self.panel)
        if value in ("create_add", "create_remove"):
            if not bindings or self.selected >= len(bindings):
                await interaction.response.send_message(_t('text.9f534727bc1946'), ephemeral=True)
                return
            await interaction.response.send_modal(
                HeraldoReactionRoleCreateModal(self, "add" if value == "create_add" else "remove")
            )
            return
        if value == "remove_selected":
            if bindings and self.selected < len(bindings):
                bindings.pop(self.selected)
                self.panel["roles"] = bindings
            next_selected = min(self.selected, len(bindings) - 1) if bindings else 0
            updated = HeraldoReactionRolesEditorView(
                self.guild_id, self.owner_id, self.panel, selected=next_selected
            )
            await interaction.response.edit_message(
                content=updated.content(interaction.guild),
                view=updated,
            )
            return

        selected = int(value)
        updated = HeraldoReactionRolesEditorView(
            self.guild_id, self.owner_id, self.panel, selected=selected
        )
        await interaction.response.edit_message(
            content=updated.content(interaction.guild),
            view=updated,
        )

    @_i18n_context
    async def _set_roles(self, interaction: discord.Interaction, key: str) -> None:
        bindings = rr_bindings(self.panel)
        if not bindings or self.selected >= len(bindings):
            await interaction.response.send_message(_t('text.7ee6a9962c7206'), ephemeral=True)
            return
        selected = [int(x) for x in interaction.data.get("values", [])]
        if any(not rr_valid_role(interaction.guild, r) for r in selected):
            await interaction.response.send_message(_t('text.b9167eac8be7ba'), ephemeral=True)
            return
        other_key = "remove" if key == "add" else "add"
        if set(selected).intersection(bindings[self.selected][other_key]):
            await interaction.response.send_message(
                _t('text.9abd45ac1eb4b1'), ephemeral=True
            )
            return
        bindings[self.selected][key] = selected
        self.panel["roles"] = bindings
        updated = HeraldoReactionRolesEditorView(
            self.guild_id, self.owner_id, self.panel, selected=self.selected
        )
        await interaction.response.edit_message(
            content=updated.content(interaction.guild),
            view=updated,
        )

    @_i18n_context
    async def set_add(self, interaction: discord.Interaction) -> None:
        await self._set_roles(interaction, "add")

    @_i18n_context
    async def set_remove(self, interaction: discord.Interaction) -> None:
        await self._set_roles(interaction, "remove")

    @_i18n_context
    async def set_access(self, interaction: discord.Interaction) -> None:
        self.panel["allowed_roles"] = [int(x) for x in interaction.data.get("values", [])]
        updated = HeraldoReactionRolesEditorView(
            self.guild_id, self.owner_id, self.panel, selected=self.selected
        )
        await interaction.response.edit_message(
            content=updated.content(interaction.guild),
            view=updated,
        )

