_rr_rejected_removals: dict[tuple[int, int, int, str], float] = {}


@_i18n_context
async def rr_reject_reaction(message: discord.Message, emoji: str, member: discord.Member) -> None:
    # Discord emite un evento remove también al retirar nosotros una elección rechazada.
    # Ese evento no debe invertir acciones de roles que nunca se aplicaron.
    now = time.monotonic()
    for key, expiry in list(_rr_rejected_removals.items()):
        if expiry <= now:
            _rr_rejected_removals.pop(key, None)
    key = (message.guild.id, message.id, member.id, _orientation_emoji_key(emoji))
    _rr_rejected_removals[key] = now + 60
    try:
        await message.remove_reaction(emoji, member)
    except discord.HTTPException:
        _rr_rejected_removals.pop(key, None)
        raise


_rr_event_locks: dict[tuple, tuple[asyncio.Lock, int]] = {}


async def rr_handle_reaction(payload: discord.RawReactionActionEvent, added: bool) -> None:
    key = (payload.guild_id, payload.message_id, payload.user_id)
    lock, users = _rr_event_locks.get(key, (asyncio.Lock(), 0))
    _rr_event_locks[key] = (lock, users + 1)
    try:
        async with lock:
            await _rr_handle_reaction_serial(payload, added)
    finally:
        _, users = _rr_event_locks[key]
        if users == 1:
            del _rr_event_locks[key]
        else:
            _rr_event_locks[key] = (lock, users - 1)


async def _rr_handle_reaction_serial(payload: discord.RawReactionActionEvent, added: bool) -> None:
    if payload.guild_id is None or payload.user_id == getattr(bot.user, "id", None):
        return
    if not added:
        key = (payload.guild_id, payload.message_id, payload.user_id,
               _orientation_emoji_key(str(payload.emoji)))
        expiry = _rr_rejected_removals.pop(key, 0)
        if expiry > time.monotonic():
            return
    panel = reaction_role_panel_find(payload.guild_id, payload.message_id)
    if not panel or int(panel["channel_id"]) != payload.channel_id:
        return
    guild = bot.get_guild(payload.guild_id)
    if guild is None:
        return
    member = payload.member or guild.get_member(payload.user_id)
    if member is None:
        try:
            member = await guild.fetch_member(payload.user_id)
        except discord.HTTPException:
            return
    if member.bot:
        return
    if condemnation_get(guild.id, member.id):
        return
    emoji = _orientation_emoji_key(str(payload.emoji))
    binding = next((x for x in rr_bindings(panel) if _orientation_emoji_key(x["emoji"]) == emoji), None)
    if not binding:
        return
    channel = guild.get_channel(payload.channel_id)
    if not rr_can_use(member, panel):
        if added and isinstance(channel, discord.TextChannel):
            try:
                message = await channel.fetch_message(payload.message_id)
                await rr_reject_reaction(message, str(payload.emoji), member)
            except discord.HTTPException:
                pass
        return
    if added and panel.get("max_reactions") and isinstance(channel, discord.TextChannel):
        try:
            message = await channel.fetch_message(payload.message_id)
            active = 0
            for reaction in message.reactions:
                rejection_key = (payload.guild_id, payload.message_id, payload.user_id, _orientation_emoji_key(str(reaction.emoji)))
                if _rr_rejected_removals.get(rejection_key, 0) > time.monotonic():
                    continue
                if any(_orientation_emoji_key(x["emoji"]) == _orientation_emoji_key(str(reaction.emoji))
                       for x in rr_bindings(panel)):
                    async for user in reaction.users():
                        if user.id == member.id:
                            active += 1
                            break
            if active > int(panel["max_reactions"]):
                await rr_reject_reaction(message, str(payload.emoji), member)
                return
        except discord.HTTPException:
            return
    reverse = bool(panel.get("reversed"))
    do_add = (added != reverse)
    to_add = binding["add"] if do_add else binding["remove"]
    to_remove = binding["remove"] if do_add else binding["add"]
    # Reverse mode inverts the meaning of the two configured actions.
    additions = [guild.get_role(int(r)) for r in to_add]
    removals = [guild.get_role(int(r)) for r in to_remove]
    additions = [r for r in additions if r and rr_valid_role(guild, r.id) and r not in member.roles]
    removals = [r for r in removals if r and rr_valid_role(guild, r.id) and r in member.roles]
    try:
        if removals:
            await member.remove_roles(*removals, reason=_t('text.7c14aaff80501f'))
        if additions:
            await member.add_roles(*additions, reason=_t('text.7c14aaff80501f'))
    except discord.HTTPException:
        pass


@bot.listen("on_raw_reaction_add")
async def general_reaction_role_add(payload: discord.RawReactionActionEvent) -> None:
    await rr_handle_reaction(payload, True)


@bot.listen("on_raw_reaction_remove")
async def general_reaction_role_remove(payload: discord.RawReactionActionEvent) -> None:
    await rr_handle_reaction(payload, False)


