DATE_FORMAT_CHOICES = {
    "discord": _t('text.cf6c89a52e3d06'),
    "dmy24": _t('text.aa86f17b17c1fe'),
    "mdy12": _t('text.08e4776f8d8109'),
    "iso": _t('text.90c23d2f884609'),
}


@_i18n_context
def date_format_setup_summary(guild_id: int) -> str:
    choice = guild_config_get(guild_id, "display_date_format") or "discord"
    if choice not in DATE_FORMAT_CHOICES:
        choice = "discord"
    examples = {
        "discord": _t('text.0b1839cfeef7f8'),
        "dmy24": "15/10/2026 16:00",
        "mdy12": "10/15/2026 4:00 PM",
        "iso": "2026-10-15 16:00",
    }
    return (
        _t('text.8542250eb9bab2', p0=f'{DATE_FORMAT_CHOICES[choice]}', p1=f'{examples[choice]}')
    )


@_i18n_context
def format_configured_datetime(guild_id: int, dt: datetime) -> str:
    """Representar una fecha sin alterar el instante original."""
    mode = guild_config_get(guild_id, "display_date_format") or "discord"
    moment = dt if dt.tzinfo else dt.replace(tzinfo=timezone.utc)
    if mode == "discord" or mode not in DATE_FORMAT_CHOICES:
        return discord.utils.format_dt(moment, "f")
    from zoneinfo import ZoneInfo
    local = moment.astimezone(ZoneInfo("America/Santo_Domingo"))
    if mode == "dmy24":
        return local.strftime("%d/%m/%Y %H:%M")
    if mode == "mdy12":
        return local.strftime("%m/%d/%Y %I:%M %p").replace(" 0", " ")
    return local.strftime("%Y-%m-%d %H:%M")


class HeraldoDateFormatSetupView(_SetupDirtySaveView):
    @_i18n_context
    def __init__(self, guild_id: int, owner_id: int):
        super().__init__(timeout=900)
        self.guild_id, self.owner_id = guild_id, owner_id
        self.original = guild_config_get(guild_id, "display_date_format") or "discord"
        self.pending = self.original
        selection = discord.ui.Select(
            placeholder=_t('text.a2d518f29c1efe'),
            options=[discord.SelectOption(label=label, value=value,
                                          default=value == self.pending)
                     for value, label in DATE_FORMAT_CHOICES.items()],
            row=0,
        )
        selection.callback = self.select_format
        self.add_item(selection)

    @_i18n_context
    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        return await configuration_access(interaction, self.guild_id, self.owner_id)

    @_i18n_context
    async def select_format(self, interaction: discord.Interaction) -> None:
        value = (interaction.data or {}).get("values", [None])[0]
        if value not in DATE_FORMAT_CHOICES:
            await interaction.response.send_message(_t('text.3a72704453002e'), ephemeral=True)
            return
        self.pending = value
        for item in self.children:
            if isinstance(item, discord.ui.Select):
                for option in item.options:
                    option.default = option.value == value
        await interaction.response.edit_message(
            content=date_format_setup_summary(self.guild_id)
                    + _t('text.88210e50a12a22', p0=f'{DATE_FORMAT_CHOICES[self.pending]}'),
            view=self,
        )

    @discord.ui.button(label=_t('text.bc60796c79da12'), style=discord.ButtonStyle.primary, row=1)
    @_i18n_context
    async def confirm(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        if (guild_config_get(self.guild_id, "display_date_format") or "discord") != self.original:
            await interaction.response.send_message(
                _t('text.98393c0f6986bc'), ephemeral=True)
            return
        if self.pending == self.original:
            await interaction.response.send_message(_t('text.ed5c91affb2e42'), ephemeral=True)
            return
        await confirm_configuration(interaction, self.guild_id, {"display_date_format": self.pending})

    @discord.ui.button(label=_t('text.bb9dbb406dcbd5'), style=discord.ButtonStyle.danger, row=1)
    @_i18n_context
    async def cancel(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        self.stop()
        await interaction.response.edit_message(content=_t('text.40bb00b053beae'), view=None)



import heraldo_i18n as i18n

LANGUAGE_CHOICES = {"es-419": "Español (Latinoamérica)", "en-US": "English (US)", "pt-BR": "Português (Brasil)"}
# El administrador puede seleccionar idiomas parciales; mostrar siempre su estado.
LANGUAGE_READY = i18n.SUPPORTED_LOCALES


def guild_language(guild_id: int) -> str:
    configured = guild_config_get(guild_id, "language") or "es-419"
    return configured if configured in LANGUAGE_READY else "es-419"


i18n.set_locale_resolver(guild_language)

import heraldo_command_i18n
heraldo_command_i18n.install(bot.http, guild_language)


@_i18n_context
def language_panel_text(guild_id: int, selected: str | None = None) -> str:
    language = guild_language(guild_id)
    text = (
        "**" + i18n.translate(language, "language.title") + "**\n\n"
        + i18n.translate(language, "language.description") + "\n\n"
        + "**" + i18n.translate(
            language, "language.current", language=LANGUAGE_CHOICES[language]
        ) + "**\n"
    )
    if selected is not None and selected != language:
        text += "**" + i18n.translate(
            language, "language.pending", language=LANGUAGE_CHOICES[selected]
        ) + "**\n"
    return text


class HeraldoLanguageView(_SetupDirtySaveView):
    @_i18n_context
    def __init__(self, guild_id: int, owner_id: int, *, from_setup: bool = False):
        super().__init__(timeout=900)
        self.guild_id, self.owner_id = guild_id, owner_id
        self.from_setup = from_setup
        self.original = guild_language(guild_id)
        self.pending = self.original
        self.save.label = i18n.translate(self.original, "language.save")
        self.discard.label = i18n.translate(self.original, "language.discard")
        self.back.label = i18n.translate(self.original, "language.back")
        selector = discord.ui.Select(
            placeholder=i18n.translate(self.original, "language.select"),
            options=[discord.SelectOption(label=LANGUAGE_CHOICES[key], value=key,
                                          description=(i18n.translate(key, "language.help")
                                                       if key in i18n.PARTIAL_LOCALES else None),
                                          default=key == self.pending)
                     for key in sorted(LANGUAGE_READY)],
            row=0,
        )
        selector.callback = self.select_language
        self.add_item(selector)

    @_i18n_context
    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        return await configuration_access(interaction, self.guild_id, self.owner_id)

    @_i18n_context
    async def select_language(self, interaction: discord.Interaction) -> None:
        current = guild_language(self.guild_id)
        if current != self.original:
            await interaction.response.edit_message(
                content=i18n.translate(current, "language.concurrent_change"), view=None)
            return
        data = (interaction.data or {}).get("values") or []
        value = str(data[0]) if data else ""
        if value not in LANGUAGE_READY:
            await interaction.response.send_message(
                i18n.translate(self.original, "language.not_available"), ephemeral=True)
            return
        self.pending = value
        for item in self.children:
            if isinstance(item, discord.ui.Select):
                for option in item.options:
                    option.default = option.value == value
        await interaction.response.edit_message(
            content=language_panel_text(self.guild_id, value), view=self)

    @discord.ui.button(label=_t('text.14bdfaf2face3a'), style=discord.ButtonStyle.success, row=1)
    @_i18n_context
    async def save(self, interaction: discord.Interaction, button: discord.ui.Button):
        if guild_language(self.guild_id) != self.original:
            await interaction.response.edit_message(
                content=i18n.translate(guild_language(self.guild_id), "language.concurrent_change"), view=None)
            return
        if self.pending not in LANGUAGE_READY:
            await interaction.response.send_message(
                i18n.translate(self.original, "language.not_available"), ephemeral=True)
            return
        if self.pending != self.original:
            guild_config_set(self.guild_id, "language", self.pending)
        await interaction.response.edit_message(
            content=language_panel_text(self.guild_id) + "\n\n**" + i18n.translate(self.pending, "language.saved") + "**",
            view=HeraldoLanguageView(self.guild_id, self.owner_id,
                                     from_setup=self.from_setup))
        if interaction.guild is not None and bot.is_ready():
            try:
                await bot.tree.sync(guild=interaction.guild)
            except Exception as exc:
                print(f"LANGUAGE_COMMAND_SYNC status=FAILED exception={type(exc).__name__}")
                await interaction.edit_original_response(
                    content=language_panel_text(self.guild_id) + "\n\n"
                            + i18n.translate(guild_language(self.guild_id), 'language.command_sync_pending'))

    @discord.ui.button(label=_t('text.80ca383e9c8d3e'), style=discord.ButtonStyle.danger, row=1)
    @_i18n_context
    async def discard(self, interaction: discord.Interaction, button: discord.ui.Button):
        await interaction.response.edit_message(
            content=language_panel_text(self.guild_id),
            view=HeraldoLanguageView(self.guild_id, self.owner_id,
                                     from_setup=self.from_setup))

    @discord.ui.button(label=_t('text.ab26ae7bca3621'), style=discord.ButtonStyle.secondary, row=2)
    @_i18n_context
    async def back(self, interaction: discord.Interaction, button: discord.ui.Button):
        if self.from_setup:
            await interaction.response.edit_message(
                content=heraldo_setup_home_content(self.guild_id),
                view=HeraldoSetupView(self.guild_id, self.owner_id))
        else:
            await interaction.response.edit_message(
                content=i18n.translate(guild_language(self.guild_id), "language.closed"), view=None)


class HeraldoSetupView(discord.ui.View):
    """Navegación directa: abrir un módulo al elegirlo, sin pasos redundantes."""

    MODULES = (
        ("automod", "setup.module.automod.label", "setup.module.automod.description"),
        ("moderation", "setup.module.moderation.label", "setup.module.moderation.description"),
        ("join_roles", "setup.module.join_roles.label", "setup.module.join_roles.description"),
        ("reaction_roles", "setup.module.reaction_roles.label", "setup.module.reaction_roles.description"),
        ("role_connections", "setup.module.role_connections.label", "setup.module.role_connections.description"),
        ("logging", "setup.module.logging.label", "setup.module.logging.description"),
        ("messages", "setup.module.messages.label", "setup.module.messages.description"),
        ("autofeeds", "setup.module.autofeeds.label", "setup.module.autofeeds.description"),
        ("verification", "setup.module.verification.label", "setup.module.verification.description"),
        ("language", "setup.module.language.label", "setup.module.language.description"),
        ("date_format", "setup.module.date_format.label", "setup.module.date_format.description"),
    )

    @_i18n_context
    def __init__(self, guild_id: int, owner_id: int) -> None:
        super().__init__(timeout=900)
        self.guild_id = guild_id
        self.owner_id = owner_id
        self.selected_module: str | None = None

        select = discord.ui.Select(
            placeholder=i18n.translate(guild_language(guild_id), "setup.select_module"),
            min_values=1,
            max_values=1,
            row=0,
            options=[
                discord.SelectOption(
                    label=i18n.translate(guild_language(guild_id), label),
                    value=key,
                    description=i18n.translate(guild_language(guild_id), description),
                )
                for key, label, description in self.MODULES
                if key not in {"role_connections"}
            ],
        )
        select.callback = self.select_module
        self.module_select = select
        self.add_item(select)

    @_i18n_context
    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if not await configuration_access(interaction, getattr(self, "guild_id", None), getattr(self, "owner_id", None)):
            return False
        if interaction.user.id != self.owner_id:
            await interaction.response.send_message(_t('text.62876186654ca2'), ephemeral=True)
            return False
        return True

    @_i18n_context
    async def select_module(self, interaction: discord.Interaction) -> None:
        # Confirmar inmediatamente la interacción. No necesitamos editar el embed
        # cada vez que se cambia el desplegable.
        # Leer el valor enviado por Discord en esta interacción, sin depender
        # de estado cacheado de la instancia de la vista.
        values = (interaction.data or {}).get("values", [])
        if not values:
            await interaction.response.send_message(_t('text.217354ff4b1e64'), ephemeral=True)
            return
        selected = str(values[0])
        if selected not in {item[0] for item in self.MODULES}:
            await interaction.response.send_message(_t('text.53b5aede865212'), ephemeral=True)
            return
        self.selected_module = selected
        await self.configure(interaction, None)

    @_i18n_context
    async def configure(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        selected = self.selected_module
        if selected is None:
            await interaction.response.send_message(
                _t('text.fec0683ce17f89'),
                ephemeral=True,
            )
            return

        if selected == "date_format":
            content = date_format_setup_summary(self.guild_id)
            view = HeraldoDateFormatSetupView(self.guild_id, self.owner_id)
        elif selected == "automod":
            content = _t('text.fb957b65618b1a')
            view = HeraldoAutomodSetupView(self.guild_id, self.owner_id)
        elif selected == "moderation":
            content = _t('text.da10e9d8927c80')
            view = HeraldoModerationSetupView(self.guild_id, self.owner_id)
        elif selected == "join_roles":
            content = _t('text.a0271ef7d3c115') + join_roles_summary(interaction.guild)
            view = HeraldoJoinRolesSetupView(self.guild_id, self.owner_id)
        elif selected == "reaction_roles":
            view = HeraldoReactionRolesSetupView(self.guild_id, self.owner_id)
            content = view.summary(interaction.guild)
        elif selected == "role_connections":
            content = (
                _t('text.945ced8381d4c3')
            )
            view = HeraldoPendingSetupModuleView(self.guild_id, self.owner_id, "Role Connections")
        elif selected == "logging":
            view = HeraldoLoggingSetupView(self.guild_id, self.owner_id)
            content = view._content(interaction.guild)
        elif selected == "messages":
            content = heraldo_messages_setup_content()
            view = HeraldoMessagesSetupView(self.guild_id, self.owner_id)
        elif selected == "autofeeds":
            from autofeed_setup import setup_panel as autofeeds_setup_panel
            content, view = autofeeds_setup_panel(globals(), self.guild_id, self.owner_id)
        elif selected == "verification":
            content = verification_hub_content(self.guild_id)
            view = HeraldoVerificationHubView(self.guild_id, self.owner_id)
        elif selected == "language":
            content = language_panel_text(self.guild_id)
            view = HeraldoLanguageView(self.guild_id, self.owner_id, from_setup=True)
        else:
            await interaction.response.send_message(_t('text.53b5aede865212'), ephemeral=True)
            return

        # Una sola respuesta de actualización, sin defer + segunda llamada HTTP.
        await interaction.response.edit_message(content=content, embed=None, view=view)

    @_i18n_context
    async def on_error(
        self, interaction: discord.Interaction, error: Exception, item: discord.ui.Item,
    ) -> None:
        # No dejar interacciones silenciosas si falla la navegación.
        print(
            f"Error: /setup: error en {type(item).__name__} "
            f"(guild={self.guild_id}, module={self.selected_module}): {error!r}"
        )
        traceback.print_exception(type(error), error, error.__traceback__)
        try:
            if interaction.response.is_done():
                await interaction.followup.send(
                    _t('text.3ca3341af0f14e'),
                    ephemeral=True,
                )
            else:
                await interaction.response.send_message(
                    _t('text.3ca3341af0f14e'),
                    ephemeral=True,
                )
        except discord.HTTPException:
            pass

    @discord.ui.button(label=_t('text.aeccae342e4bd0'), style=discord.ButtonStyle.danger, row=1)
    @_i18n_context
    async def close(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        self.stop()
        await interaction.response.edit_message(content=_t('text.83e4a94cefc9df'), view=None)




