@bot.tree.command(name="heraldo_check_all", description="Fuerza la evaluación inmediata de TODOS los miembros que tengan Tentad@.")
@discord.app_commands.checks.has_permissions(kick_members=True)
@discord.app_commands.guild_only()
@_i18n_context
async def heraldo_check_all(interaction: discord.Interaction) -> None:
    guild = interaction.guild
    await interaction.response.send_message(_t('text.e95a42b428fdad'), ephemeral=True)
    await log_embed(guild, _t('text.2d424960a80787'), _t('text.97f96d90d7f442', p0=f'{interaction.user.mention}'), discord.Color.blurple())

    verified = 0
    expelled: list[discord.Member] = []
    expelled_sin_verificar: list[discord.Member] = []

    async for member in guild.fetch_members(limit=None):
        if (member.bot or member.id == getattr(guild, 'owner_id', None)
                or condemnation_get(member.guild.id, member.id) is not None):
            continue  # propietario y condenados exentos de esta evaluación
        role_ids = {r.id for r in member.roles}
        if get_tentado_role_id(guild.id) in role_ids:
            status = await evaluate_member(guild.id, member.id, report=False)
            if status == "verificado":
                verified += 1
            elif status == "expulsado":
                expelled.append(member)
            await asyncio.sleep(1)  # evitar ráfagas contra el rate limit de Discord
        elif get_sin_verificado_role_id(guild.id) in role_ids:
            # NH: «Sin Verificar» nunca crea una segunda sanción directa.
            # Solo el evaluador principal consulta el plazo y la acción vigente.
            await evaluate_verify_timeout(guild.id, member.id)
            await asyncio.sleep(1)

    embed = discord.Embed(
        title=_t('text.72b864e711b9bc'),
        description=(
            _t('text.e1a91c76fcb0e2', p0=f'{verified}', p1=f'{len(expelled)}', p2=f'{len(expelled_sin_verificar)}')
        ),
        color=discord.Color.blurple(),
        timestamp=datetime.now(timezone.utc),
    )

    def add_mention_fields(embed: discord.Embed, members: list[discord.Member], label: str) -> None:
        if not members:
            return
        chunk, blocks = "", []
        for m in members:
            line = f"{m.mention} (`{m.id}`)\n"
            if len(chunk) + len(line) > 1000:
                blocks.append(chunk)
                chunk = ""
            chunk += line
        if chunk:
            blocks.append(chunk)
        for i, block in enumerate(blocks, start=1):
            name = label if len(blocks) == 1 else f"{label} ({i}/{len(blocks)})"
            embed.add_field(name=name, value=block, inline=False)

    add_mention_fields(embed, expelled, _t('text.edf2dcee197847'))
    add_mention_fields(embed, expelled_sin_verificar, _t('text.5f168423408d63'))

    channel = guild.get_channel(get_log_channel_id(guild.id))
    if channel is not None:
        try:
            await channel.send(embed=embed)
        except discord.Forbidden:
            print("Sin permisos para escribir en el canal de logs")

    await interaction.followup.send(
        _t('text.6c47b9a839572f', p0=f'{verified}', p1=f'{len(expelled)}', p2=f'{len(expelled_sin_verificar)}'),
        ephemeral=True,
    )


@heraldo_check_all.error
@_i18n_context
async def heraldo_check_all_error(interaction: discord.Interaction, error: discord.app_commands.AppCommandError) -> None:
    if isinstance(error, discord.app_commands.MissingPermissions):
        await interaction.response.send_message(_t('text.04ca1828a4d8b5'), ephemeral=True)
    else:
        await interaction.response.send_message(_t('text.8904a29c5dcf0c', p0=f'{error}'), ephemeral=True)


class HeraldoLogChannelConfirmView(discord.ui.View):
    """Confirmación de cambios en el canal de logs, con revalidación al pulsar."""
    @_i18n_context
    def __init__(self, guild_id: int, owner_id: int, channel_id: int, previous_id: int):
        super().__init__(timeout=300)
        self.guild_id = guild_id
        self.owner_id = owner_id
        self.channel_id = channel_id
        self.previous_id = previous_id
        self.finished = False

    @_i18n_context
    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        return await configuration_access(interaction, self.guild_id, self.owner_id)

    @discord.ui.button(label=_t('text.14bdfaf2face3a'), style=discord.ButtonStyle.success)
    @_i18n_context
    async def confirm(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        if not await self.interaction_check(interaction):
            return
        if self.finished:
            await interaction.response.send_message(_t('text.6f5c8804bdb7ae'), ephemeral=True)
            return
        channel = interaction.guild.get_channel(self.channel_id)
        me = interaction.guild.me
        if not isinstance(channel, discord.TextChannel) or me is None:
            await interaction.response.send_message(_t('text.7a3072bf51b38b'), ephemeral=True)
            return
        permissions = channel.permissions_for(me)
        if not (permissions.view_channel and permissions.send_messages and permissions.embed_links):
            await interaction.response.send_message(_t('text.1751480f598599'), ephemeral=True)
            return
        if get_log_channel_id(self.guild_id) != self.previous_id:
            await interaction.response.send_message(
                _t('text.30c7d73591d62c'),
                ephemeral=True,
            )
            return
        set_log_channel_id(channel.id, self.guild_id)
        self.finished = True
        self.stop()
        await interaction.response.edit_message(
            content=_t('text.1f3248a6a901cd', p0=f'{channel.mention}'), view=None
        )
        await log_embed(
            interaction.guild, _t('text.fa034910e1b026'),
            _t('text.92d5315ad926ae', p0=f'{interaction.user.mention}', p1=f'{channel.mention}'),
            discord.Color.blurple(),
        )

    @discord.ui.button(label=_t('text.bb9dbb406dcbd5'), style=discord.ButtonStyle.danger)
    @_i18n_context
    async def cancel(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        if not await self.interaction_check(interaction):
            return
        if self.finished:
            await interaction.response.send_message(_t('text.6f5c8804bdb7ae'), ephemeral=True)
            return
        self.finished = True
        self.stop()
        await interaction.response.edit_message(content=_t('text.38f8449200ecb6'), view=None)


@bot.tree.command(name="heraldo_log_channel", description="Cambiar el canal donde El Heraldo reporta su actividad (logs).")
@discord.app_commands.describe(canal=_t('text.56ab7c45f6f2f6'))
@discord.app_commands.checks.has_permissions(kick_members=True)
@discord.app_commands.guild_only()
@_i18n_context
async def heraldo_log_channel(interaction: discord.Interaction, canal: discord.TextChannel) -> None:
    if not await configuration_access(interaction):
        return
    me = interaction.guild.me
    if me is None:
        await interaction.response.send_message(_t('text.cefc85649f1ed9'), ephemeral=True)
        return
    perms = canal.permissions_for(me)
    if not (perms.view_channel and perms.send_messages and perms.embed_links):
        await interaction.response.send_message(
            _t('text.56ff206478527c'), ephemeral=True
        )
        return
    view = HeraldoLogChannelConfirmView(
        interaction.guild.id, interaction.user.id, canal.id, get_log_channel_id(interaction.guild.id)
    )
    await interaction.response.send_message(
        _t('text.227322482f868f', p0=f'{canal.mention}'),
        view=view, ephemeral=True,
    )


@heraldo_log_channel.error
@_i18n_context
async def heraldo_log_channel_error(interaction: discord.Interaction, error: discord.app_commands.AppCommandError) -> None:
    if isinstance(error, discord.app_commands.MissingPermissions):
        await interaction.response.send_message(_t('text.04ca1828a4d8b5'), ephemeral=True)
    else:
        await interaction.response.send_message(_t('text.8904a29c5dcf0c', p0=f'{error}'), ephemeral=True)


# ---------------------------------------------------------------------------
# Verificación por botón (/verify)
# ---------------------------------------------------------------------------

@_i18n_context
def verify_role_problem(role: discord.Role, guild: discord.Guild) -> str | None:
    """Motivo por el que NO conviene usar este rol como rol de verificación, o None
    si está bien. El botón lo puede pulsar cualquiera: el rol no puede dar poderes de
    moderación, y el Heraldo tiene que poder asignarlo."""
    if role.is_default():
        return _t("common.everyone_role")
    if role.managed:
        return _t('text.9d211cfc9f5be0')
    if role >= guild.me.top_role:
        return _t('text.ea68e9bfe68ef1')
    risky = [label for attr, label in VERIFY_DANGEROUS_PERMS if getattr(role.permissions, attr)]
    if risky:
        return _t('text.e378e34dcb8f79') + _i18n_join(", ", risky) + ")"
    return None


class VerifyView(discord.ui.View):
    """Vista persistente: el botón sigue funcionando tras reinicios (se registra en on_ready)."""

    @_i18n_context
    def __init__(self, label: str | None = None) -> None:
        super().__init__(timeout=None)
        button = discord.ui.Button(
            # Esta vista se registra al arrancar sin conocer un guild concreto.
            # El panel real conserva el texto configurado por su propio servidor.
            label=label or VERIFY_BUTTON_LABEL_DEFAULT,
            style=discord.ButtonStyle.success,
            custom_id=VERIFY_BUTTON_ID,
        )
        button.callback = handle_verify_click
        self.add_item(button)


@_i18n_context
async def send_verification_welcome_dm(member: discord.Member) -> bool:
    """Envía el DM de bienvenida una sola vez, cuando el miembro se verifica por primera vez."""
    if db_verification_dm_sent(member.guild.id, member.id):
        return True

    embed = build_verification_welcome_embed(member=member)
    try:
        await member.send(embed=embed)
        db_mark_verification_dm_sent(member.guild.id, member.id)
        return True
    except discord.HTTPException:
        return False


@_i18n_context
async def clear_sin_verificar_after_verification(
    member: discord.Member,
    *,
    reason: str,
) -> bool:
    """Retira Sin Verificar y cancela sus estados pendientes tras verificarse."""
    guild = member.guild
    db_clear_verify_pending(guild.id, member.id)
    db_clear_sin_verificado(guild.id, member.id)

    sin_role = guild.get_role(get_sin_verificado_role_id(guild.id))
    if sin_role is None or sin_role not in member.roles:
        return True
    try:
        await member.remove_roles(sin_role, reason=reason)
        return True
    except discord.HTTPException as exc:
        await log_embed(
            guild,
            _t('text.2ef0cc3f3b5a93'),
            _t('text.a8dee6f41924d7', p0=f'{member.mention}', p1=f'{sin_role.mention}', p2=f'{exc}'),
            discord.Color.dark_red(),
        )
        return False


@_i18n_context
async def handle_verify_click(interaction: discord.Interaction) -> None:
    guild = interaction.guild
    member = interaction.user
    if guild is None or not isinstance(member, discord.Member):
        await interaction.response.send_message(_t('text.20772d848e2af5'), ephemeral=True)
        return
    await interaction.response.defer(ephemeral=True, thinking=True)

    punish_role_id = hp_punish_role_id(guild.id)
    if condemnation_get(member.guild.id, member.id) is not None or (punish_role_id and any(r.id == punish_role_id for r in member.roles)):
        await interaction.followup.send(_t('text.069098e5def30f'), ephemeral=True)
        return

    role = guild.get_role(get_verify_role_id(guild.id))
    if role is None:
        await interaction.followup.send(_t('text.d6c7149f724cbc'), ephemeral=True)
        await log_embed(
            guild, _t('text.9ca3f03ef5f4be'),
            _t('text.c5d60c16427525', p0=f'{member.mention}'),
            discord.Color.dark_red(),
        )
        return

    role_ids = {r.id for r in member.roles}
    if role.id in role_ids:
        await clear_sin_verificar_after_verification(
            member,
            reason=_t('text.b2aef7635149a5'),
        )
        await interaction.followup.send(_t('text.75a6e102bae83e'), ephemeral=True)
        return
    # Tener personalidad no sustituye el botón de verificación de edad.
    problem = verify_role_problem(role, guild)
    if problem:
        await interaction.followup.send(_t('text.8475ea90f6dcdd'), ephemeral=True)
        await log_embed(
            guild, _t('text.5a65e5a8966d22'),
            _t('text.8c199e4bc34259', p0=f'{member.mention}', p1=f'{role.mention}', p2=f'{problem}'),
            discord.Color.dark_red(),
        )
        return

    try:
        await member.add_roles(role, reason=_t('text.ac768e25c3001c'))
    except discord.HTTPException as e:  # incluye Forbidden (jerarquía o permisos)
        await interaction.followup.send(_t('text.0d7b882a32d473'), ephemeral=True)
        await log_embed(
            guild, _t('text.376d4bbe4fd2ff'),
            _t('text.f969aa6e5c08c1', p0=f'{role.mention}', p1=f'{member.mention}', p2=f'{e}'),
            discord.Color.dark_red(),
        )
        return

    db_clear_verify_pending(member.guild.id, member.id)
    # Quien se verifica deja de estar "Sin Verificar" (si no, el respaldo de 300 s lo expulsaría).
    sin_role = guild.get_role(get_sin_verificado_role_id(guild.id))
    if sin_role is not None and sin_role in member.roles:
        try:
            await member.remove_roles(sin_role, reason=_t('text.ac768e25c3001c'))
            db_clear_sin_verificado(member.guild.id, member.id)
        except discord.HTTPException as e:
            await log_embed(
                guild, _t('text.2ef0cc3f3b5a93'),
                _t('text.4b892645b2f1c2', p0=f'{member.mention}', p1=f'{sin_role.mention}', p2=f'{e}'),
                discord.Color.dark_red(),
            )

    await interaction.followup.send(
        render_vars(get_verify_success_text(guild.id), VarContext(guild, member, interaction.channel), 2000),
        ephemeral=True, allowed_mentions=discord.AllowedMentions.none(),
    )

    # Personalidad por personalidads: solo se inicia desde ESTE evento de verificación.
    # Nunca se arma al detectar roles en miembros antiguos. Si el servidor no configuró
    # roles de personalidad, no existe obligación ni expulsión por personalidads.
    orientation_roles = get_eval_role_ids(guild.id)
    if (orientation_enabled(guild.id) and personality_required(guild.id)
            and not verification_is_exempt(member) and orientation_roles
            and not ({r.id for r in member.roles} & orientation_roles)):
        now = datetime.now(timezone.utc)
        db_set_tentado(member.guild.id, member.id, now)
        asyncio.create_task(schedule_check(guild.id, member.id, now))
        # Log de "Personalidad iniciada" desactivado temporalmente.
        # La personalidad y su temporizador siguen funcionando con normalidad.
    else:
        db_clear_tentado(member.guild.id, member.id)

    # DM de bienvenida: solo la primera vez que este usuario obtiene el rol de verificación.
    dm_welcome_ok = await send_verification_welcome_dm(member)
    if not dm_welcome_ok:
        await log_embed(
            guild, _t('text.174051598d2696'),
            _t('text.01c2084aa97902', p0=f'{member.mention}'),
            discord.Color.orange(),
        )

    await log_embed(
        guild, _t('text.ef78590b86919f'),
        _t('text.3e954b22441abe', p0=f'{member.mention}'),
        discord.Color.green(),
    )


@_i18n_context
async def schedule_verify_timeout(guild_id: int, user_id: int, pending_at: datetime) -> None:
    delay = (pending_at + timedelta(seconds=get_verify_timeout(guild_id)) - datetime.now(timezone.utc)).total_seconds()
    if delay > 0:
        await asyncio.sleep(delay)
    await evaluate_verify_timeout(guild_id, user_id)


@_i18n_context
async def evaluate_verify_timeout(guild_id: int, user_id: int) -> None:
    await run_verification_expiry(guild_id, user_id, _evaluate_verify_timeout_inner)


@_i18n_context
async def _evaluate_verify_timeout_inner(guild_id: int, user_id: int) -> None:
    """Aplica la acción configurada si el miembro no se verificó dentro del timeout.
    Lee siempre la configuración actual: si el timeout se alargó mientras esperaba, no
    actúa todavía (check_pending_verifications lo retoma al vencer el nuevo plazo)."""
    if condemnation_get(guild_id, user_id) is not None:
        clear_verification_expiry(guild_id, user_id)
        return
    row = db_get(guild_id, user_id)
    if row is None or row["verify_pending_at"] is None:
        return  # ya verificado, ya evaluado o nunca estuvo pendiente
    guild = bot.get_guild(guild_id)
    if guild is None:
        return
    member = guild.get_member(user_id)
    if member is None or not verify_enabled(guild.id):
        clear_verification_expiry(guild_id, user_id)  # se fue, o la verificación se desactivó
        return

    timeout = get_verify_timeout(guild_id)
    deadline = datetime.fromisoformat(row["verify_pending_at"]) + timedelta(seconds=timeout)
    if datetime.now(timezone.utc) + timedelta(seconds=1) < deadline:
        return

    role_ids = {r.id for r in member.roles}
    if get_verify_role_id(guild.id) in role_ids:
        clear_verification_expiry(guild_id, user_id)
        return  # únicamente el rol de edad satisface esta verificación

    action = get_verify_action(guild.id)
    if action == "none":
        clear_verification_expiry(guild_id, user_id)
        await log_embed(
            guild, _t('text.22965a55631352'),
            _t('text.1893f60caa2f6d', p0=f'{member.mention}', p1=f'{member.id}'),
            discord.Color.orange(),
        )
        return
    try:
        if action == "ban":
            await heraldo_ban(member, reason=_t('text.2287928147e493'), delete_message_seconds=0)
        else:
            await heraldo_kick(member, reason=_t('text.2287928147e493'))
    except discord.HTTPException as e:  # incluye Forbidden (jerarquía de roles)
        await log_embed(
            guild, _t('text.5eedcfa9f1ab6e'),
            _t('text.92aff5e1452cbf', p0=f"{(_t('text.5b0f1790dee350') if action == 'ban' else _t('text.f7345bb5522ba6'))}", p1=f'{member.mention}', p2=f'{e}'),
            discord.Color.dark_red(),
        )
        return
    clear_verification_expiry(guild_id, user_id)
    db_clear_tentado(guild_id, user_id)
    await log_embed(
        guild, _t('text.39a13bd1b27820') if action == "ban" else _t('text.fbf00252ef659d'),
        _t('text.e75b4271c14d5b', p0=f'{member.mention}', p1=f'{member.id}'),
        discord.Color.red(),
    )


@_i18n_context
async def synchronize_published_panels(
    guild: discord.Guild, *, suggestions_already_synced: bool = False
) -> dict[str, str]:
    """Reconciliación no destructiva de paneles publicados y registrados."""
    results: dict[str, str] = {}
    ref = guild_config_get(guild.id, "verify_panel_ref")
    if ref is None and legacy_fallback_allowed(guild.id):
        ref = db_meta_get("verify_panel_ref")
    if ref:
        try:
            results["verificacion"] = await update_verify_panel(guild)
        except (discord.HTTPException, ValueError, TypeError) as exc:
            results["verificacion"] = _t('text.67837899c149ff', p0=f'{type(exc).__name__}')
    # No crear un panel de sugerencias si no existe una referencia publicada:
    # la primera publicación requiere intervención administrativa.
    if (not suggestions_already_synced and suggestion_get_panel_message_id(guild.id)
            and suggestion_get_channel_id(guild.id)):
        try:
            await suggestion_ensure_panel(guild)
            results["sugerencias"] = _t('text.fd3f53f82a74ca')
        except (discord.HTTPException, ValueError, TypeError) as exc:
            results["sugerencias"] = _t('text.67837899c149ff', p0=f'{type(exc).__name__}')
    # Nunca publicar una tarjeta nueva ni borrar una antigua por un arranque:
    # la primera publicación y el traslado de canal requieren acción administrativa.
    if (orientation_enabled(guild.id)
            and get_orientation_message_id(guild.id)
            and get_orientation_message_channel_id(guild.id) == get_orientation_channel_id(guild.id)):
        try:
            ok, note = await ensure_orientation_system(guild)
            results["orientacion"] = _t('text.fd3f53f82a74ca') if ok else note
        except (discord.HTTPException, ValueError, TypeError) as exc:
            results["orientacion"] = _t('text.67837899c149ff', p0=f'{type(exc).__name__}')
    for name, status in results.items():
        if i18n.canonical_text(status).startswith(("No se pudo", "Advertencia:")):
            print(f"Sincronización pendiente: {guild.id} / {name}: {status}")
    return results


@_i18n_context
async def update_verify_panel(guild: discord.Guild) -> str:
    """Edita el panel ya publicado con los textos actuales. Devuelve una nota para el admin."""
    ref = guild_config_get(guild.id, "verify_panel_ref")
    if ref is None and legacy_fallback_allowed(guild.id):
        ref = db_meta_get("verify_panel_ref")
    if not ref:
        return _t('text.ad1b20a4ed9145')
    try:
        channel_id, message_id = (int(x) for x in ref.split(":"))
        channel = guild.get_channel(channel_id)
        if channel is None:
            return _t('text.ad9a36381b7888')
        message = await channel.fetch_message(message_id)
        await message.edit(
            content=render_vars(get_verify_panel_text(guild.id), VarContext(guild, None, channel), 2000),
            view=VerifyView(label=get_verify_button_label(guild.id)),
            allowed_mentions=discord.AllowedMentions.none(),
        )
        return _t('text.7332de9fcf8c1b')
    except discord.NotFound:
        return _t('text.8bdd081a95a692')
    except (discord.HTTPException, ValueError) as e:
        return _t('text.edc8a2252d2019', p0=f'{e}')


@_i18n_context
def verify_config_summary(guild: discord.Guild) -> str:
    role_id = get_verify_role_id(guild.id)
    role = guild.get_role(role_id)
    role_text = role.mention if role else _t('text.e28c9e5333525f', p0=f'{role_id}')
    ref = guild_config_get(guild.id, "verify_panel_ref")
    if ref is None and legacy_fallback_allowed(guild.id):
        ref = db_meta_get("verify_panel_ref")
    if ref and ref.count(":") == 1:
        channel_id, message_id = ref.split(":")
        panel_text = _t('text.af23497887284b', p0=f'{guild.id}', p1=f'{channel_id}', p2=f'{message_id}')
    elif ref:
        panel_text = _t('text.38368cd246f348')
    else:
        panel_text = _t('text.ad8171c7a0ba42')
    return (
        _t('text.04cdf3210e29d4', p0=f"{(_t('text.adfcbfc83b5cc5') if verify_enabled(guild.id) else _t('text.5a2925de7a1a0b'))}", p1=f'{role_text}', p2=f'{format_duration((get_verify_timeout(guild.id) + 59) // 60)}', p3=f'{VERIFY_ACTION_LABELS[get_verify_action(guild.id)]}', p4=f'{panel_text}')
    )


class VerifyTextsModal(discord.ui.Modal):
    """Formulario de textos; se abre con los valores actuales."""

    @_i18n_context
    def __init__(self, guild_id: int) -> None:
        super().__init__(title=_t('text.2ae8f62cbc2032'))
        self.guild_id = guild_id
        self.panel = discord.ui.TextInput(
            label=_t('text.17b3c900671098'),
            style=discord.TextStyle.paragraph,
            default=get_verify_panel_text(guild_id),
            max_length=2000,
        )
        self.button_label = discord.ui.TextInput(
            label=_t('text.0746df8abcc257'),
            default=get_verify_button_label(guild_id),
            max_length=80,
        )
        self.success = discord.ui.TextInput(
            label=_t('text.2ec11b358aff04'),
            style=discord.TextStyle.paragraph,
            default=get_verify_success_text(guild_id),
            max_length=1000,
        )
        self.add_item(self.panel)
        self.add_item(self.button_label)
        self.add_item(self.success)

    @_i18n_context
    async def on_submit(self, interaction: discord.Interaction) -> None:
        panel = self.panel.value.strip()
        label = self.button_label.value.strip()
        success = self.success.value.strip()
        if not (panel and label and success):
            await interaction.response.send_message(_t('text.ca70dd1f25b787'), ephemeral=True)
            return
        await confirm_configuration(interaction, interaction.guild.id, {'verify_panel_text': panel, 'verify_button_label': label, 'verify_success_text': success})


@bot.tree.command(name="verify", description="Publicar el panel de verificación (botón) en un canal.")
@discord.app_commands.describe(canal=_t('text.8c72bff1e087c1'))
@discord.app_commands.checks.has_permissions(manage_guild=True)
@discord.app_commands.guild_only()
@_i18n_context
async def verify(interaction: discord.Interaction, canal: Optional[discord.TextChannel] = None) -> None:
    guild = interaction.guild
    target = canal or interaction.channel
    if not isinstance(target, discord.TextChannel):
        await interaction.response.send_message(_t('text.8ac30e2023d22d'), ephemeral=True)
        return
    role = guild.get_role(get_verify_role_id(guild.id))
    if role is None:
        await interaction.response.send_message(_t('text.79d3c7fdb8017f'), ephemeral=True)
        return
    problem = verify_role_problem(role, guild)
    if problem:
        await interaction.response.send_message(
            _t('text.f4e0be2f55dfa4', p0=f'{role.mention}', p1=f'{problem}'),
            ephemeral=True,
        )
        return
    perms = target.permissions_for(guild.me)
    if not (perms.view_channel and perms.send_messages):
        await interaction.response.send_message(
            _t('text.a62cd7b0f8504e', p0=f'{target.mention}'),
            ephemeral=True,
        )
        return

    await interaction.response.defer(ephemeral=True)
    try:
        message = await target.send(
            content=render_vars(get_verify_panel_text(guild.id), VarContext(guild, None, target), 2000),
            view=VerifyView(label=get_verify_button_label(guild.id)),
            allowed_mentions=discord.AllowedMentions.none(),
        )
    except discord.HTTPException as e:
        await interaction.followup.send(_t('text.6e40da795fc729', p0=f'{e}'), ephemeral=True)
        return
    guild_config_set(guild.id, "verify_panel_ref", f"{target.id}:{message.id}")
    await interaction.followup.send(
        _t('text.d5676d1f7fcbbd', p0=f'{target.mention}'),
        ephemeral=True,
    )
    await log_embed(
        guild, _t('text.ead2d5f05c4780'),
        _t('text.7e1c107ec7c1ec', p0=f'{interaction.user.mention}', p1=f'{target.mention}'),
        discord.Color.blurple(),
    )


@bot.tree.command(
    name="verify_dm_texts",
    description="Editar el DM de bienvenida; el pie identifica automáticamente al servidor.",
)
@app_commands.describe(
    titulo=_t('text.b995eb49bdbb63'),
    campo=_t('text.f0a0a02ddd0218'),
    mensaje=_t('text.5e28cf570913d2'),
    color=_t('text.f8a967df5d0e57'),
    icono_footer=_t('text.981cc03cfb57dc'),
)
@discord.app_commands.checks.has_permissions(manage_guild=True)
@discord.app_commands.guild_only()
@_i18n_context
async def verify_dm_texts(
    interaction: discord.Interaction,
    titulo: str,
    campo: str,
    mensaje: str,
    color: str,
    icono_footer: str,
) -> None:
    """Editor directo: el pie se calcula por servidor; guardar exige confirmación."""
    titulo = titulo.strip()
    campo = campo.strip()
    mensaje = mensaje.strip()
    color = color.strip().lstrip("#")
    icono_footer = icono_footer.strip()
    if not titulo or not campo or not mensaje or not color:
        await interaction.response.send_message(
            _t('text.a1a830c7178b07'),
            ephemeral=True,
        )
        return
    if len(titulo) > 256 or len(campo) > 256 or len(mensaje) > 4000:
        await interaction.response.send_message(
            _t('text.da68ef655c9002'), ephemeral=True,
        )
        return
    if not re.fullmatch(r"[0-9a-fA-F]{6}", color):
        await interaction.response.send_message(
            _t('text.da2e6e3e709229'), ephemeral=True,
        )
        return
    if len(icono_footer) > 500 or (
        icono_footer and not re.match(r"^https?://", icono_footer, re.IGNORECASE)
        and not VAR_PATTERN.search(icono_footer)
    ):
        await interaction.response.send_message(
            _t('text.3fe27e650344df'),
            ephemeral=True,
        )
        return
    values = {
        "verify_dm_title": titulo,
        "verify_dm_field_name": campo,
        "verify_dm_body": mensaje,
        "verify_dm_color": color.upper(),
        "verify_dm_footer_icon": icono_footer,
    }
    await confirm_configuration(interaction, interaction.guild.id, values)


@bot.tree.command(name="verify_dm_preview", description="Mostrar en el canal de logs una vista previa del DM de bienvenida.")
@discord.app_commands.checks.has_permissions(manage_guild=True)
@discord.app_commands.guild_only()
@_i18n_context
async def verify_dm_preview(interaction: discord.Interaction) -> None:
    guild = interaction.guild
    log_channel = guild.get_channel(get_log_channel_id(guild.id))
    if log_channel is None:
        await interaction.response.send_message(
            _t('text.cbb9e94faf2cb2'),
            ephemeral=True,
        )
        return
    perms = log_channel.permissions_for(guild.me)
    if not (perms.view_channel and perms.send_messages and perms.embed_links):
        await interaction.response.send_message(
            _t('text.7b4239b5f9e2fb', p0=f'{log_channel.mention}'),
            ephemeral=True,
        )
        return
    try:
        embed = build_verification_welcome_embed(
            member=interaction.user if isinstance(interaction.user, discord.Member) else None, guild=guild,
        )
        await log_channel.send(
            content=_t('text.300f3e97e06eb4', p0=f'{interaction.user.mention}'),
            embed=embed,
            allowed_mentions=discord.AllowedMentions.none(),
        )
    except discord.HTTPException as e:
        await interaction.response.send_message(_t('text.66d2e6e0ca6747', p0=f'{e}'), ephemeral=True)
        return
    await interaction.response.send_message(
        _t('text.bee90e7d25f20a', p0=f'{log_channel.mention}'), ephemeral=True
    )


