@joinroles_group.command(name="add", description="Añadir uno o varios Roles de ingreso generales.")
@discord.app_commands.checks.has_permissions(manage_guild=True)
@_i18n_context
async def joinroles_add(
    interaction: discord.Interaction,
    rol: discord.Role,
    rol2: Optional[discord.Role] = None,
    rol3: Optional[discord.Role] = None,
    rol4: Optional[discord.Role] = None,
    rol5: Optional[discord.Role] = None,
) -> None:
    if not await configuration_access(interaction):
        return
    roles = _joinroles_command_roles(rol, rol2, rol3, rol4, rol5)
    issue = _joinroles_validate_command_roles(interaction.guild, roles)
    if issue:
        await interaction.response.send_message(_t('text.8904a29c5dcf0c', p0=f'{issue}'), ephemeral=True)
        return
    current = get_join_role_ids(interaction.guild.id)
    for role in roles:
        if role.id not in current:
            current.append(role.id)
    await confirm_configuration(interaction, interaction.guild.id, {
        "join_role_ids": json.dumps(current[:JOIN_ROLES_MAX]),
        "join_roles_enabled": "1",
    })



@joinroles_group.command(name="remove", description="Quitar uno o varios Roles de ingreso generales.")
@discord.app_commands.checks.has_permissions(manage_guild=True)
@_i18n_context
async def joinroles_remove(
    interaction: discord.Interaction,
    rol: discord.Role,
    rol2: Optional[discord.Role] = None,
    rol3: Optional[discord.Role] = None,
    rol4: Optional[discord.Role] = None,
    rol5: Optional[discord.Role] = None,
) -> None:
    if not await configuration_access(interaction):
        return
    remove_ids = {role.id for role in _joinroles_command_roles(rol, rol2, rol3, rol4, rol5)}
    current = [role_id for role_id in get_join_role_ids(interaction.guild.id) if role_id not in remove_ids]
    await confirm_configuration(interaction, interaction.guild.id, {
        "join_role_ids": json.dumps(current),
    })



@joinroles_group.command(name="user_add", description="Añadir un rol específico a un ID de usuario de Discord.")
@discord.app_commands.checks.has_permissions(manage_guild=True)
@_i18n_context
async def joinroles_user_add(
    interaction: discord.Interaction,
    user_id: str,
    rol: discord.Role,
) -> None:
    if not await configuration_access(interaction):
        return
    try:
        target_id = int(user_id.strip())
        if target_id <= 0:
            raise ValueError
    except ValueError:
        await interaction.response.send_message(_t('text.882460ddc9dd41'), ephemeral=True)
        return
    issue = _joinroles_validate_command_roles(interaction.guild, [rol])
    if issue:
        await interaction.response.send_message(_t('text.8904a29c5dcf0c', p0=f'{issue}'), ephemeral=True)
        return
    mapping = get_join_specific_roles(interaction.guild.id)
    roles = mapping.get(target_id, [])
    if rol.id not in roles:
        roles.append(rol.id)
    mapping[target_id] = roles[:JOIN_ROLES_MAX]
    await confirm_configuration(interaction, interaction.guild.id, {
        "join_specific_roles": json.dumps({str(k): v for k, v in mapping.items()}),
    })



@joinroles_group.command(name="user_remove", description="Quitar un rol específico o eliminar el ID de usuario de la lista.")
@discord.app_commands.checks.has_permissions(manage_guild=True)
@_i18n_context
async def joinroles_user_remove(
    interaction: discord.Interaction,
    user_id: str,
    rol: Optional[discord.Role] = None,
) -> None:
    if not await configuration_access(interaction):
        return
    try:
        target_id = int(user_id.strip())
        if target_id <= 0:
            raise ValueError
    except ValueError:
        await interaction.response.send_message(_t('text.882460ddc9dd41'), ephemeral=True)
        return

    mapping = get_join_specific_roles(interaction.guild.id)
    if target_id not in mapping:
        await interaction.response.send_message(_t('text.81794d011abee8'), ephemeral=True)
        return
    if rol is None:
        mapping.pop(target_id, None)
    else:
        roles = [role_id for role_id in mapping[target_id] if role_id != rol.id]
        if roles:
            mapping[target_id] = roles
        else:
            mapping.pop(target_id, None)
    await confirm_configuration(interaction, interaction.guild.id, {
        "join_specific_roles": json.dumps({str(k): v for k, v in mapping.items()}),
    })


