    embed.add_field(name="Condenado", value=f"{member.mention}\n{member}", inline=True)
    embed.add_field(name=_t('text.5a3597afd33f1b'), value=str(row["reason"])[:1024], inline=False)
    embed.add_field(name=_t('text.6d391853f66931'), value=discord.utils.format_dt(condemned_at, "F"), inline=True)
    embed.add_field(name=_t('text.3c827aaf3357f8'), value=pardoned_by.mention, inline=True)
