@bot.tree.command(name="condenar", description="Condenar a un miembro: guarda sus roles, los retira y aplica Condenado.")
@discord.app_commands.describe(
    miembro=_t('text.aa1c67d9753b73'),
    motivo=_t('text.73af3adcc24251'),
    duracion=_t('text.04480e6edd7cf4'),
    purga=_t('text.41dd1fc1084263'),
)
@discord.app_commands.checks.has_permissions(kick_members=True)
@discord.app_commands.guild_only()
@_i18n_context
async def condenar(
    interaction: discord.Interaction,
    miembro: discord.Member,
    motivo: Optional[str] = None,
    duracion: Optional[str] = None,
    purga: Optional[str] = None,
) -> None:
    guild = interaction.guild
    reason = (motivo or "").strip()[:1000]
    is_heraldo_test = heraldo_is_test()
    if not reason and is_heraldo_test:
        reason = _t('text.490ef3a71dc429')
    if not reason:
        await interaction.response.send_message(_t('text.b0272cff91134f'), ephemeral=True)
        return
    duration_minutes: int | None = condemnation_default_duration_minutes(guild.id)
    try:
        if duracion is not None:
            raw_duration = duracion.strip()
            if i18n.indefinite_input(raw_duration):
                duration_minutes = None
            else:
                duration_minutes = parse_duration(raw_duration, 1, get_condemnation_max_minutes(guild.id))
        purge_spec = parse_purge_spec(purga) if purga else HONEYPOT_PURGE_DEFAULT
    except ValueError as e:
        await interaction.response.send_message(_t('text.5f5b3dc37c0a01', p0=f'{e}'), ephemeral=True)
        return

    if miembro.id == interaction.user.id:
        # No es una protección de seguridad; evita una equivocación especialmente fácil con el comando.
        await interaction.response.send_message(_t('text.1fcca229d711a0'), ephemeral=True)
        return

    await interaction.response.defer(ephemeral=True)
    ok, note = await condemn_member(
        miembro,
        reason=reason,
        duration_minutes=duration_minutes,
        purge_spec=purge_spec,
        origin="command",
        applied_by=interaction.user,
    )
    if not ok:
        await interaction.followup.send(_t('text.dceb3ba326f852', p0=f'{note}'), ephemeral=True)
        return
    await interaction.followup.send(
        _t('text.17734404f6672d', p0=f'{miembro.mention}', p1=f"{(format_duration(duration_minutes) if duration_minutes else _t('text.f6920bf7ea3ae9'))}", p2=f'{format_purge_spec(*purge_spec)}'), ephemeral=True,
    )


@condenar.error
@_i18n_context
async def condenar_error(interaction: discord.Interaction, error: discord.app_commands.AppCommandError) -> None:
    if isinstance(error, discord.app_commands.MissingPermissions):
        await interaction.response.send_message(_t('text.04ca1828a4d8b5'), ephemeral=True)
    else:
        await interaction.response.send_message(_t('text.8904a29c5dcf0c', p0=f'{error}'), ephemeral=True)


class PendingRoleRestoreView(discord.ui.View):
    """Reintento no destructivo y explícito de roles pendientes de una condena."""
    @_i18n_context
    def __init__(self, guild_id: int, owner_id: int, target_id: int):
        super().__init__(timeout=300)
        self.guild_id, self.owner_id, self.target_id = guild_id, owner_id, target_id
        self.original = condemnation_pending_roles_get(guild_id, target_id)
        self.finished = False

    @_i18n_context
    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if self.is_finished():
            sender = interaction.followup.send if interaction.response.is_done() else interaction.response.send_message
            await sender(_t('text.0f1f190a61371a'), ephemeral=True)
            return False
        if not await configuration_access(interaction, self.guild_id, self.owner_id):
            return False
        if not interaction.user.guild_permissions.manage_roles:
            sender = interaction.followup.send if interaction.response.is_done() else interaction.response.send_message
            await sender(_t('text.6db5c969e58991'), ephemeral=True)
            return False
        return True

    @discord.ui.button(label=_t('text.f5392be7f841de'), style=discord.ButtonStyle.success)
    @_i18n_context
    async def confirm(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        if not await self.interaction_check(interaction):
            return
        if self.finished:
            await interaction.response.send_message(_t('text.6f5c8804bdb7ae'), ephemeral=True)
            return
        guild = interaction.guild
        bot_member = guild.me
        if bot_member is None or not bot_member.guild_permissions.manage_roles:
            await interaction.response.send_message(_t('text.cfc44683c1b2a8'), ephemeral=True)
            return
        if condemnation_get(self.guild_id, self.target_id) is not None:
            await interaction.response.send_message(
                _t('text.237687dde0d5ba'), ephemeral=True
            )
            return
        pending = condemnation_pending_roles_get(self.guild_id, self.target_id)
        if not pending or pending != self.original:
            await interaction.response.send_message(
                _t('text.0d1778ebe604a8'), ephemeral=True
            )
            return
        await interaction.response.defer()
        member = guild.get_member(self.target_id)
        if member is None:
            try:
                member = await guild.fetch_member(self.target_id)
            except (discord.NotFound, discord.Forbidden, discord.HTTPException):
                await interaction.followup.send(
                    _t('text.1ee92479e71567'), ephemeral=True
                )
                return
        if not await self.interaction_check(interaction):
            return
        if self.finished or condemnation_pending_roles_get(self.guild_id, self.target_id) != pending:
            await interaction.followup.send(_t('text.cff14112373882'), ephemeral=True)
            return
        if guild.me is None or not guild.me.guild_permissions.manage_roles:
            await interaction.followup.send(_t('text.0a82f23067f1d9'), ephemeral=True)
            return
        if condemnation_get(self.guild_id, self.target_id) is not None:
            await interaction.followup.send(_t('text.bf61338d722d6d'), ephemeral=True)
            return
        assignable = []
        for rid in pending:
            role = guild.get_role(rid)
            if role is None or role.managed or not role.is_assignable():
                continue
            if (not interaction.user.guild_permissions.administrator
                    and interaction.user.id != guild.owner_id
                    and role >= interaction.user.top_role):
                continue
            assignable.append(role)
        if not assignable:
            await interaction.followup.send(
                _t('text.9eb55799ba5e2c'),
                ephemeral=True,
            )
            return
        key = (self.guild_id, self.target_id)
        if key in _condemn_inflight:
            await interaction.followup.send(
                _t('text.495eb61065ef5f'), ephemeral=True
            )
            return
        _condemn_inflight.add(key)
        self.finished = True
        try:
            await member.add_roles(*assignable, reason=_t('text.a9d69da44e95b7'))
        except discord.HTTPException:
            self.finished = False
            await interaction.followup.send(
                _t('text.2bd5ae20bac95f'), ephemeral=True
            )
            return
        finally:
            _condemn_inflight.discard(key)
        remaining = [rid for rid in pending if rid not in {role.id for role in assignable}]
        condemnation_pending_roles_set(self.guild_id, self.target_id, remaining)
        self.stop()
        await interaction.edit_original_response(
            content=_t('text.f77dec88c81be9', p0=f'{len(assignable)}', p1=f'{len(remaining)}'), view=None,
        )
        await log_embed(
            guild, _t('text.32e00e03fd6eac'),
            _t('text.edaf6beac31588', p0=f'{interaction.user.mention}', p1=f'{self.target_id}', p2=f'{len(assignable)}', p3=f'{len(remaining)}'),
        )

    @discord.ui.button(label=_t('text.bb9dbb406dcbd5'), style=discord.ButtonStyle.danger)
    @_i18n_context
    async def cancel(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        if not await self.interaction_check(interaction):
            return
        if self.finished:
            await interaction.response.send_message(_t('text.6f5c8804bdb7ae'), ephemeral=True)
            return
        self.finished = True
        self.stop()
        await interaction.response.edit_message(
            content=_t('text.bd0641af01f4c0'), view=None,
        )


