@bot.listen("on_raw_reaction_add")
async def moderation_reaction_add(payload: discord.RawReactionActionEvent) -> None:
    if payload.guild_id is None or payload.user_id == getattr(bot.user, "id", None):
        return

    guild = bot.get_guild(payload.guild_id)
    if guild is None:
        return
    actor = payload.member or guild.get_member(payload.user_id)
    if actor is None:
        try:
            actor = await guild.fetch_member(payload.user_id)
        except discord.HTTPException:
            return
    if actor.bot:
        return

    emoji = str(payload.emoji)
    condemn_emoji = get_condemnation_emoji(guild.id)
    is_condemn = _moderation_emoji_key(emoji) == _moderation_emoji_key(condemn_emoji)
    if is_condemn and not moderation_report_punishment_enabled(guild.id, "condemn"):
        return
    report_rule = moderation_report_rule_for_emoji(guild.id, emoji)
    # Dos acciones configuradas con el mismo emoji no deben ejecutarse juntas.
    # En caso de conflicto se falla cerrado, sin aplicar condena ni advertencia.
    if is_condemn and report_rule is not None:
        return
    report_type = str(report_rule["label"]) if report_rule else None
    if not is_condemn and report_rule is None:
        return
    # Advertir no es una encuesta pública: solo puede iniciarlo el personal autorizado.
    if report_rule and report_rule.get("action") == "warn" and not moderation_can_warn(actor):
        return

    channel = guild.get_channel_or_thread(payload.channel_id)
    if channel is None or not hasattr(channel, "fetch_message"):
        return
    try:
        message = await channel.fetch_message(payload.message_id)
    except (discord.NotFound, discord.Forbidden, discord.HTTPException):
        return
    # fetch_message puede devolver User sin el objeto Member; no descartar por ello
    # una reacción válida. Resolver el miembro real antes de evaluar sus roles.
    target = message.author
    if not isinstance(target, discord.Member):
        target = guild.get_member(message.author.id)
        if target is None:
            try:
                target = await guild.fetch_member(message.author.id)
            except (discord.NotFound, discord.Forbidden, discord.HTTPException):
                return
    if target.bot or target.id == actor.id:
        return

    if report_rule and report_rule.get("action") == "warn":
        # El relevo de reacción debe ser viable antes de abrir un expediente WARN.
        me = guild.me
        perms = channel.permissions_for(me) if me and hasattr(channel, "permissions_for") else None
        if perms is None or not (
            perms.view_channel and perms.read_message_history
            and perms.add_reactions and perms.manage_messages
        ):
            await log_embed(
                guild, _t('text.09865d3bad2668'),
                _t('text.d8293b359dbc4e'),
                discord.Color.orange(),
            )
            return

    if is_condemn:
        if not moderation_can_condemn(actor, target) or target.id == actor.id:
            return
        if condemnation_get(guild.id, target.id) is not None:
            return
        pending_key = (guild.id, message.id)
        if pending_key in _reaction_condemn_pending:
            return
        _reaction_condemn_pending.add(pending_key)
        view = ReactionCondemnReasonView(
            guild_id=guild.id,
            actor_id=actor.id,
            channel_id=message.channel.id,
            message_id=message.id,
            target_id=target.id,
            pending_key=pending_key,
        )
        try:
            prompt = await actor.send(
                _t('text.bc822ac120dec7', p0=f'{guild.name}', p1=f'{target}', p2=f'{target.id}', p3=f'{message.channel.mention}', p4=f'{message.jump_url}'),
                view=view,
                allowed_mentions=discord.AllowedMentions.none(),
            )
            view.prompt_message = prompt
        except discord.HTTPException:
            _reaction_condemn_pending.discard(pending_key)
        return

    # Si no hay un destino exclusivo, reutilizar los registros del servidor.
    # Una configuración incompleta no debe desactivar silenciosamente las reglas.
    report_channel_id = moderation_report_channel_id(guild.id) or get_log_channel_id(guild.id)
    report_channel = guild.get_channel(report_channel_id)
    if not isinstance(report_channel, discord.TextChannel):
        return

    now = time.monotonic()
    dedupe_key = (guild.id, message.id, actor.id, _moderation_emoji_key(emoji))
    last = _moderation_report_dedupe.get(dedupe_key)
    if last is not None and now - last < 3600:
        return
    _moderation_report_dedupe[dedupe_key] = now
    emoji_key = _moderation_emoji_key(emoji)
    reporter_count, action_executed = moderation_report_record(
        guild.id, message.id, target.id, emoji_key, actor.id
    )
    threshold = int(report_rule.get("threshold", 1)) if report_rule else 1
    if len(_moderation_report_dedupe) > 5000:
        cutoff = now - 3600
        for key, stamp in list(_moderation_report_dedupe.items()):
            if stamp < cutoff:
                _moderation_report_dedupe.pop(key, None)

    # Publicar únicamente el primer aviso y el resultado final del umbral.
    # No emitir además un segundo embed de logs por la misma acción.
    if action_executed or (1 < reporter_count < threshold):
        return

    action_result: tuple[bool, str] | None = None
    if report_rule and reporter_count >= threshold and not action_executed:
        action_key = (guild.id, message.id, emoji_key)
        if action_key in _moderation_report_pending:
            return
        _moderation_report_pending.add(action_key)
        try:
            action_result = await execute_moderation_report_action(
                guild, target, message, report_rule, reporter_count,
                actor=actor if report_rule.get("action") == "warn" else None,
            )
            if action_result[0]:
                moderation_report_mark_executed(guild.id, message.id, target.id, emoji_key)
                if report_rule.get("action") == "warn":
                    # Solo tras registrar el WARN: el bot añade su reacción y
                    # elimina la del moderador; el mensaje original no se toca.
                    # Ante error de permisos, el expediente se conserva.
                    try:
                        await message.add_reaction(emoji)
                    except discord.HTTPException:
                        action_result = (True, action_result[1] + _t('text.ff76c621c8d7c0'))
                    else:
                        try:
                            await message.remove_reaction(emoji, actor)
                        except discord.HTTPException:
                            action_result = (True, action_result[1] + _t('text.bcaa9a26dd68d9'))
        except Exception:
            traceback.print_exc()
            action_result = (False, _t('text.24597c46a17769'))
        finally:
            _moderation_report_pending.discard(action_key)

    embed = discord.Embed(
        title=_t('text.519b181eb0831d'),
        description=_t('text.e287a455696692', p0=f'{report_type}'),
        color=discord.Color.orange(),
        timestamp=datetime.now(timezone.utc),
    )
    embed.add_field(name=_t('text.e841f8bfd02f85'), value=target.mention, inline=True)
    embed.add_field(name=_t('text.5337bc07f951de'), value=actor.mention, inline=True)
    embed.add_field(name=_t('text.0119803da01181'), value=message.channel.mention, inline=True)
    embed.add_field(name=_t('text.9e82671db199b2'), value=f"{reporter_count}/{threshold}", inline=True)
    embed.add_field(
        name=_t('text.ba7018efe7b6f5'),
        value=moderation_action_label(str(report_rule.get("action", "report"))) if report_rule else _t('text.fb57b92cfc0723'),
        inline=True,
    )
    if action_result is not None:
        success, explanation = action_result
        embed.add_field(
            name=_t('text.a71bc39fe3f33e'),
            value=(_t('text.c5f990b8159793') if success else _t('text.990628ccf1f474')) + explanation[:950],
            inline=False,
        )
        embed.color = discord.Color.green() if success else discord.Color.orange()
    if message.content:
        embed.add_field(name=_t('text.d2af31712ead04'), value=message.content[:1000], inline=False)
    embed.add_field(name=_t('text.10ddff5fcc6fc5'), value=_t('text.6dac37ee7de44b', p0=f'{message.jump_url}'), inline=False)
    try:
        await report_channel.send(embed=embed, allowed_mentions=discord.AllowedMentions.none())
    except discord.HTTPException:
        _moderation_report_dedupe.pop(dedupe_key, None)
        # Nunca informar como ejecutada una acción cuya trazabilidad no se pudo publicar.
        # El estado real de la acción se conserva para no aplicarla dos veces.
        print("Moderation: no se pudo publicar el resultado de reporte en su canal.")


class ReactionCondemnReasonModal(discord.ui.Modal, title=_t('text.d8a57560eac5f8')):
    reason = discord.ui.TextInput(
        label=_t('text.794cce2e71b56c'),
        style=discord.TextStyle.paragraph,
        required=True,
        min_length=3,
        max_length=1000,
        placeholder=_t('text.358303f18e1176'),
    )

    @_i18n_context
    def __init__(self, view: 'ReactionCondemnReasonView') -> None:
        super().__init__()
        self.parent_view = view

    @_i18n_context
    async def on_submit(self, interaction: discord.Interaction) -> None:
        view = self.parent_view
        if interaction.user.id != view.actor_id:
            await interaction.response.send_message(_t('text.37152f9fdd56f2'))
            return
        guild = bot.get_guild(view.guild_id)
        if guild is None:
            await interaction.response.send_message(_t('text.d7213f054bc34d'))
            _reaction_condemn_pending.discard(view.pending_key)
            return
        actor = guild.get_member(view.actor_id)
        if actor is None or not (actor.guild_permissions.administrator or actor.guild_permissions.kick_members):
            await interaction.response.send_message(_t('text.07c7f017a10022'))
            _reaction_condemn_pending.discard(view.pending_key)
            return
        channel = guild.get_channel_or_thread(view.channel_id)
        if channel is None or not hasattr(channel, "fetch_message"):
            await interaction.response.send_message(_t('text.36f3a2467c0b48'))
            _reaction_condemn_pending.discard(view.pending_key)
            return
        try:
            message = await channel.fetch_message(view.message_id)
        except (discord.NotFound, discord.Forbidden, discord.HTTPException):
            await interaction.response.send_message(_t('text.36f3a2467c0b48'))
            _reaction_condemn_pending.discard(view.pending_key)
            return
        target = guild.get_member(view.target_id)
        if target is None or target.bot or target.id != message.author.id:
            await interaction.response.send_message(_t('text.68793fa9ca3981'))
            _reaction_condemn_pending.discard(view.pending_key)
            return
        if not moderation_report_punishment_enabled(guild.id, "condemn") or not moderation_can_condemn(actor, target):
            await interaction.response.send_message(
                _t('text.be5d1381c004e4')
            )
            _reaction_condemn_pending.discard(view.pending_key)
            return
        reason = str(self.reason).strip()
        if not reason:
            await interaction.response.send_message(_t('text.709ad12f2db0bf'))
            return

        await interaction.response.defer(thinking=True)
        ok, note = await condemn_member(
            target,
            reason=reason,
            duration_minutes=condemnation_default_duration_minutes(guild.id),
            purge_spec=HONEYPOT_PURGE_DEFAULT,
            origin="reaction",
            applied_by=actor,
            source_message_url=message.jump_url,
            source_channel_id=message.channel.id,
        )
        _reaction_condemn_pending.discard(view.pending_key)
        if view.prompt_message is not None:
            try:
                await view.prompt_message.edit(
                    content=(
                        _t('text.d922bc70da8e82', p0=f'{target}', p1=f'{note}')
                        if ok else _t('text.41c9cad4c7a58f', p0=f'{note}')
                    ),
                    view=None,
                )
            except discord.HTTPException:
                await interaction.followup.send(
                    _t('text.d922bc70da8e82', p0=f'{target}', p1=f'{note}')
                    if ok else _t('text.41c9cad4c7a58f', p0=f'{note}')
                )
        else:
            await interaction.followup.send(
                _t('text.d922bc70da8e82', p0=f'{target}', p1=f'{note}')
                if ok else _t('text.41c9cad4c7a58f', p0=f'{note}')
            )


class ReactionCondemnReasonView(discord.ui.View):
    @_i18n_context
    def __init__(
        self, *, guild_id: int, actor_id: int, channel_id: int, message_id: int,
        target_id: int, pending_key: tuple[int, int],
    ) -> None:
        super().__init__(timeout=120)
        self.guild_id = guild_id
        self.actor_id = actor_id
        self.channel_id = channel_id
        self.message_id = message_id
        self.target_id = target_id
        self.pending_key = pending_key
        self.prompt_message: discord.Message | None = None

    @_i18n_context
    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if interaction.user.id != self.actor_id:
            await interaction.response.send_message(_t('text.16b1675a67d203'))
            return False
        return True

    @discord.ui.button(label=_t('text.43b7e050ea2308'), style=discord.ButtonStyle.primary)
    @_i18n_context
    async def enter_reason(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        await interaction.response.send_modal(ReactionCondemnReasonModal(self))

    @discord.ui.button(label=_t('text.bb9dbb406dcbd5'), style=discord.ButtonStyle.danger)
    @_i18n_context
    async def cancel(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        _reaction_condemn_pending.discard(self.pending_key)
        await interaction.response.edit_message(content=_t('text.8df5a9f0c311a7'), view=None)
        self.stop()

    @_i18n_context
    async def on_timeout(self) -> None:
        _reaction_condemn_pending.discard(self.pending_key)
        if self.prompt_message is not None:
            try:
                await self.prompt_message.edit(content=_t('text.4099799416f923'), view=None)
            except discord.HTTPException:
                pass




