@honeypot_group.command(name="setup", description="Ver o cambiar la configuración del honeypot.")
@discord.app_commands.describe(
    activado=_t('text.64a2595b7e31dc'),
    accion=_t('text.d295cf31ea1a6c'),
    rol_castigo=_t('text.156cb9416331c7'),
    purga=_t('text.d84f89283250b4'),
    timeout=_t('text.feee6477ad0d0a'),
    aviso=_t('text.b72e12b3f5a688'),
    ping_rol=_t('text.98961433bcd3ec'),
    retencion=_t('text.82c0266877b627'),
)
@discord.app_commands.choices(accion=[
    discord.app_commands.Choice(name="Purgar y aplicar rol de castigo", value="role"),
    discord.app_commands.Choice(name="Solo registrar (prueba segura)", value="log"),
    discord.app_commands.Choice(name="Aislar (timeout)", value="timeout"),
    discord.app_commands.Choice(name="Expulsar", value="kick_enabled"),
    discord.app_commands.Choice(name="Banear", value="ban_enabled"),
])
@_i18n_context
async def honeypot_config(
    interaction: discord.Interaction,
    activado: Optional[bool] = None,
    accion: Optional[discord.app_commands.Choice[str]] = None,
    rol_castigo: Optional[discord.Role] = None,
    purga: Optional[str] = None,
    timeout: Optional[str] = None,
    aviso: Optional[bool] = None,
    ping_rol: Optional[discord.Role] = None,
    retencion: Optional[str] = None,
) -> None:
    if not await configuration_access(interaction):
        return
    guild = interaction.guild
    if all(v is None for v in (activado, accion, rol_castigo, purga, timeout, aviso, ping_rol, retencion)):
        await interaction.response.send_message(hp_config_summary(guild), ephemeral=True)
        return
    if activado and not hp_traps(guild.id):
        await interaction.response.send_message(
            _t('text.f74417da50136f'),
            ephemeral=True,
        )
        return

    if rol_castigo is not None:
        problem = hp_role_problem(rol_castigo, guild)
        if problem:
            await interaction.response.send_message(_t('text.a01cdb33c8e8cd', p0=f'{rol_castigo.mention}', p1=f'{problem}'), ephemeral=True)
            return
    effective_action = (
        next(
            (key for key, value in HONEYPOT_DESTRUCTIVE_ACTION_STORAGE.items()
             if value == accion.value),
            accion.value,
        ) if accion is not None else hp_action(guild.id)
    )
    if effective_action in {"kick", "ban"} and (accion is not None or activado):
        problem = hp_sanction_permission_problem(
            guild, effective_action, interaction.user.guild_permissions,
        )
        if problem:
            await interaction.response.send_message(
                problem + _t('text.8277e3061b6e2f'), ephemeral=True,
            )
            return
    effective_role_id = rol_castigo.id if rol_castigo is not None else hp_punish_role_id(guild.id)
    if effective_action == "role" and (activado or accion is not None) and guild.get_role(effective_role_id) is None:
        await interaction.response.send_message(
            _t('text.80ec337088547b'),
            ephemeral=True,
        )
        return

    # Validar duraciones antes de guardar nada.
    purga_spec = None
    timeout_min = None
    retencion_min = None
    try:
        if purga is not None:
            purga_spec = parse_purge_spec(purga)
        if timeout is not None:
            timeout_min = parse_duration(timeout, HONEYPOT_TIMEOUT_MIN_MINUTES, HONEYPOT_TIMEOUT_MAX_MINUTES)
        if retencion is not None:
            retencion_min = parse_duration(retencion, 1, PURGE_MAX_MINUTES)
    except ValueError as e:
        await interaction.response.send_message(_t('text.5f38ebd4859078', p0=f'{e}'), ephemeral=True)
        return

    changes: dict[str, str] = {}
    if activado is not None:
        changes["honeypot_enabled"] = "1" if activado else "0"
        if activado:
            changes["honeypot_paused"] = "0"
    if accion is not None:
        changes["honeypot_action"] = accion.value
    if rol_castigo is not None:
        changes["honeypot_punish_role"] = str(rol_castigo.id)
    if purga_spec is not None:
        changes["honeypot_purge_spec"] = f"{purga_spec[0]}:{purga_spec[1]}"
    if timeout_min is not None:
        changes["honeypot_timeout_minutes"] = str(timeout_min)
    if retencion_min is not None:
        changes["honeypot_retention_minutes"] = str(retencion_min)
    if ping_rol is not None:
        changes["honeypot_ping_role"] = str(ping_rol.id)
    if aviso is not None:
        changes["honeypot_warning_enabled"] = "1" if aviso else "0"

    # Todos los cambios pasan por un borrador efímero. Cancelar no escribe.
    await confirm_configuration(interaction, guild.id, changes)

class HoneypotTrapActionConfirmView(discord.ui.View):
    """Confirma y revalida cambios de canales trampa antes de ejecutarlos."""
    @_i18n_context
    def __init__(self, guild_id: int, owner_id: int, action: str,
                 channel_id: int | None = None, *, from_setup: bool = False,
                 parent: HeraldoHoneypotSetupView | None = None):
        super().__init__(timeout=300)
        self.guild_id, self.owner_id = guild_id, owner_id
        self.action, self.channel_id = action, channel_id
        self.from_setup = from_setup
        self.parent = parent
        self.finished = False
        # Al confirmar se distingue crear/registrar de retirar un canal trampa.
        self.confirm.style = discord.ButtonStyle.success

    @_i18n_context
    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        return await configuration_access(interaction, self.guild_id, self.owner_id)

    @discord.ui.button(label=_t('text.0c180627ae3f2b'), style=discord.ButtonStyle.success)
    @honeypot_operation
    @_i18n_context
    async def confirm(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        await interaction.response.defer(ephemeral=True)
        if not await self.interaction_check(interaction):
            return
        if self.finished:
            await interaction.followup.send(_t('text.d02e4a1e58a334'), ephemeral=True)
            return
        guild = interaction.guild
        me = guild.me
        channel = guild.get_channel(self.channel_id) if self.channel_id is not None else None
        if self.action == "create":
            configured_id = get_guild_channel_id(guild.id, "honeypot")
            existing = guild.get_channel(configured_id) if configured_id else None
            if existing is None:
                existing = next((c for c in getattr(guild, "text_channels", [])
                                 if c.name.casefold() == "honeypot"), None)
            if existing is not None:
                await interaction.followup.send(
                    _t('text.0e3cb140568acd'),
                    ephemeral=True,
                )
                return
            if not interaction.user.guild_permissions.manage_channels or (
                me is None or not me.guild_permissions.manage_channels
            ):
                await interaction.followup.send(
                    _t('text.70a78efe2d5af5'),
                    ephemeral=True,
                )
                return
        else:
            if not isinstance(channel, discord.TextChannel):
                await interaction.followup.send(_t('text.d4d55c28021c41'), ephemeral=True)
                return
            registered = channel.id in hp_traps(guild.id)
            if (self.action == "add" and registered) or (self.action == "remove" and not registered):
                await interaction.followup.send(_t('text.abcc83703c8d5c'), ephemeral=True)
                return
            if self.action == "add":
                reason = hp_protected_channel_reason(channel)
                perms = channel.permissions_for(me) if me is not None else None
                if reason or perms is None or not (
                    perms.view_channel and perms.send_messages and perms.manage_messages
                ):
                    await interaction.followup.send(
                        _t('text.31954783c9f830'), ephemeral=True
                    )
                    return
        if self.from_setup and self.action in {"add", "create"} and not hp_traps(guild.id):
            _, activation_error = hp_initial_activation_plan(
                guild, actor_permissions=interaction.user.guild_permissions,
            )
            if activation_error:
                await interaction.followup.send(
                    activation_error + _t('text.4b1bbe89efda90'), ephemeral=True,
                )
                return
        self.finished = True
        self.stop()
        if self.action == "add":
            if self.from_setup:
                note = await _setup_apply_system_channel(
                    guild, "honeypot", channel, publish_messages=True,
                )
                warning = None if "pero " not in note else note
            else:
                hp_add_trap(guild.id, channel.id)
                warning = await hp_sync_warning(channel)
            if self.parent is not None:
                await self._refresh_setup_parent(
                    interaction, _t('text.20408c8f54a41a', p0=f'{channel.mention}', p1=f'{note}'),
                )
            else:
                await interaction.followup.send(
                    _t('text.5ae2b0688bfb86', p0=f'{channel.mention}')
                    + (_t('text.dd8180fe95b79e', p0=f'{warning}') if warning else ""), ephemeral=True,
                )
            await log_embed(guild, _t('text.d8ae5268f3e77f'),
                            _t('text.aee418052feb1c', p0=f'{interaction.user.mention}', p1=f'{channel.mention}'))
        elif self.action == "remove":
            old_message_id = hp_traps(guild.id).get(channel.id)
            if old_message_id:
                try:
                    await (await channel.fetch_message(old_message_id)).delete()
                except (discord.NotFound, discord.Forbidden, discord.HTTPException):
                    pass
            hp_remove_trap(guild.id, channel.id)
            extra = ""
            if not hp_traps(guild.id) and honeypot_enabled(guild.id):
                hp_setting_set(guild.id, "honeypot_enabled", "0")
                extra = _t('text.3c4148e2bcf54b')
            await interaction.followup.send(
                _t('text.92093c28b4fca9', p0=f'{channel.mention}', p1=f'{extra}'), ephemeral=True
            )
            await log_embed(guild, _t('text.ab946656b18202'),
                            _t('text.53ff11e5acf177', p0=f'{interaction.user.mention}', p1=f'{channel.mention}'))
        elif self.action == "create":
            overwrites = {
                guild.default_role: discord.PermissionOverwrite(
                    view_channel=True, send_messages=True, create_public_threads=False,
                    create_private_threads=False, send_messages_in_threads=False,
                )
            }
            try:
                channel = await guild.create_text_channel(
                    "honeypot", overwrites=overwrites, reason=_t('text.3f919395fb9497')
                )
            except discord.HTTPException:
                await interaction.followup.send(
                    _t('text.3ba29694344896'), ephemeral=True
                )
                return
            if self.from_setup:
                note = await _setup_apply_system_channel(
                    guild, "honeypot", channel, publish_messages=True,
                )
                warning = None if "pero " not in note else note
            else:
                hp_add_trap(guild.id, channel.id)
                warning = await hp_sync_warning(channel)
            if self.parent is not None:
                await self._refresh_setup_parent(
                    interaction, _t('text.e29838dec5e3fa', p0=f'{channel.mention}', p1=f'{note}'),
                )
            else:
                await interaction.followup.send(
                    _t('text.66fc2133690aa6', p0=f'{channel.mention}')
                    + (_t('text.dd8180fe95b79e', p0=f'{warning}') if warning else "")
                    + (_t('text.a0d64f6f732233') if honeypot_enabled(guild.id)
                       else _t('text.6c68dd7c8d1c34')),
                    ephemeral=True,
                )
            await log_embed(guild, _t('text.eb2e58c4c66eb4'),
                            _t('text.e62073efb6413c', p0=f'{interaction.user.mention}', p1=f'{channel.mention}'))

    @_i18n_context
    async def _refresh_setup_parent(self, interaction: discord.Interaction, note: str) -> None:
        """Devolver al panel que abrió la confirmación, sin mensaje efímero extra."""
        if self.parent is None:
            return
        parent = self.parent
        parent.original_traps = set(hp_traps(guild_id=parent.guild_id))
        parent.original_enabled = honeypot_enabled(parent.guild_id)
        parent.original_paused = honeypot_paused(parent.guild_id)
        parent.original_action = hp_action(parent.guild_id)
        parent._sync_controls()
        await interaction.edit_original_response(
            content=note, embed=parent._embed(interaction.guild), view=parent,
        )

    @discord.ui.button(label=_t('text.bb9dbb406dcbd5'), style=discord.ButtonStyle.danger)
    @_i18n_context
    async def cancel(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        if not await self.interaction_check(interaction):
            return
        if self.finished:
            await interaction.response.send_message(_t('text.d02e4a1e58a334'), ephemeral=True)
            return
        self.finished = True
        self.stop()
        if self.parent is not None:
            self.parent._sync_controls()
            await interaction.response.edit_message(
                content=_t('text.58f0aceb523f31'),
                embed=self.parent._embed(interaction.guild),
                view=self.parent,
            )
        else:
            await interaction.response.edit_message(
                content=_t('text.736f1c5dfec513'), view=None,
            )


@honeypot_group.command(name="add", description="Convertir un canal de texto existente en canal trampa.")
@discord.app_commands.describe(canal=_t('text.5a64ee449ee931'))
@_i18n_context
async def honeypot_add(interaction: discord.Interaction, canal: discord.TextChannel) -> None:
    if not await configuration_access(interaction):
        return
    if canal.id in hp_traps(interaction.guild.id):
        await interaction.response.send_message(_t('text.08c1fa9b36d17c'), ephemeral=True)
        return
    if hp_protected_channel_reason(canal):
        await interaction.response.send_message(_t('text.cc104b3c629804'), ephemeral=True)
        return
    me = interaction.guild.me
    perms = canal.permissions_for(me) if me is not None else None
    if perms is None or not (perms.view_channel and perms.send_messages and perms.manage_messages):
        await interaction.response.send_message(_t('text.18a8d71b07c78d'), ephemeral=True)
        return
    await interaction.response.send_message(
        _t('text.8b16e75a71f402', p0=f'{canal.mention}'),
        view=HoneypotTrapActionConfirmView(interaction.guild.id, interaction.user.id, "add", canal.id),
        ephemeral=True,
    )

