class HoneypotWarningEmbedModal(discord.ui.Modal, title=_t('text.6350e55d60f80d')):
    title_input = discord.ui.TextInput(
        label=_t('text.4c08a5d5feb22c'),
        required=False,
        max_length=256,
    )
    description_input = discord.ui.TextInput(
        label=_t('text.ee00b96fff266f'),
        style=discord.TextStyle.paragraph,
        required=True,
        max_length=4000,
    )
    color_input = discord.ui.TextInput(
        label=_t('text.810106546c2a6b'),
        required=True,
        max_length=7,
    )
    image_input = discord.ui.TextInput(
        label=_t('text.b669b63fead35c'),
        required=False,
        max_length=2000,
    )
    footer_input = discord.ui.TextInput(
        label=_t('text.db08543ce4f1b7'),
        required=False,
        max_length=2048,
        placeholder=_t('footer.editor_hint'),
    )

    @_i18n_context
    def __init__(self, guild_id: int, *, publish_from_setup: bool = False) -> None:
        super().__init__()
        self.guild_id = guild_id
        self.publish_from_setup = publish_from_setup
        if publish_from_setup:
            self.title = _t('text.cbf50489458de8')
        cfg = hp_warning_custom(guild_id)
        self.title_input.default = cfg["title"]
        self.description_input.default = cfg["description"]
        self.color_input.default = cfg["color"]
        self.image_input.default = cfg["image"]
        self.footer_input.default = cfg["footer"]

    @_i18n_context
    async def on_submit(self, interaction: discord.Interaction) -> None:
        title = str(self.title_input).strip()
        description = str(self.description_input).strip()
        color = str(self.color_input).strip().lstrip("#")
        image = str(self.image_input).strip()
        footer = str(self.footer_input).strip()

        if not description:
            await interaction.response.send_message(_t('text.17a3223bfb129e'), ephemeral=True)
            return
        if not re.fullmatch(r"[0-9a-fA-F]{6}", color):
            await interaction.response.send_message(_t('text.0650b40948be31'), ephemeral=True)
            return
        for label, url in (("imagen", image),):
            if url and not re.match(r"^https?://", url, re.IGNORECASE) and not VAR_PATTERN.search(url):
                await interaction.response.send_message(_t('text.e56d88f8cb6ae7', p0=f'{label}'), ephemeral=True)
                return

        await confirm_configuration(interaction, self.guild_id, {
            "honeypot_warning_title": title,
            "honeypot_warning_description": description,
            "honeypot_warning_color": color.upper(),
            "honeypot_warning_image": image,
            "honeypot_warning_thumbnail": "",
            "honeypot_warning_footer": footer,
            "honeypot_warning_style": "custom",
            **({"honeypot_warning_enabled": "1"} if self.publish_from_setup else {}),
        }, publish_honeypot_notice=self.publish_from_setup)


