        if self.finished:
            await interaction.response.send_message(_t('text.08e419babf38d0'), ephemeral=True)
            return
        self.finished = True
        self.stop()
        await interaction.response.edit_message(
            content=_t('text.58dfe5d6f9dce5'), view=None,
        )


