@bot.tree.command(name="advertencias", description="Consulta el historial de advertencias de un miembro.")
@app_commands.describe(usuario=_t('text.fb5299afaeae8a'))
@app_commands.checks.has_permissions(moderate_members=True)
@app_commands.guild_only()
@_i18n_context
async def moderation_warnings(interaction: discord.Interaction, usuario: discord.Member) -> None:
    if usuario.bot:
        await interaction.response.send_message(
            _t('text.6e039c8a212030'), ephemeral=True,
        )
        return
    abiertas, total = moderation_warning_counts(interaction.guild.id, usuario.id)
    maximum = moderation_warning_limit(interaction.guild.id)
    rows = moderation_case_list(
        interaction.guild.id, user_id=usuario.id, case_type="WARN", limit=8,
    )
    now = datetime.now(timezone.utc)
    lines = [
        f"**{moderation_case_code(int(row['case_number']), interaction.guild.id)}** · "
        f"{_t('text.e7d107cc746492') if row['open'] and (not row['expires_at'] or datetime.fromisoformat(row['expires_at']) > now) else _t('text.881a7769e8780a')}"
        f" · {moderation_case_origin(row)} · {str(row['reason'])[:130]}"
        for row in rows
    ]
    heading = (_t('text.b851647c6d5585', p0=f'{discord.utils.escape_markdown(usuario.display_name)}', p1=f'{abiertas}', p2=f'{maximum}', p3=f'{total}', p4=f'{total - abiertas}'))
    message = heading + ("\n\n" + _i18n_join("\n", lines) if lines else _t('text.b82ecab8fa87c5'))
    await interaction.response.send_message(
        message[:1900], ephemeral=True, allowed_mentions=discord.AllowedMentions.none(),
    )


