# ---------------------------------------------------------------------------
# 13A. PROGRAMACIÓN DE EMBEDS (opt-in, por configuración independiente)
# ---------------------------------------------------------------------------
import embed_schedules as embed_schedule_engine


def scheduled_embed_test_mode():
    return heraldo_is_test()


def scheduled_embed_db():
    conn = db_connect()
    embed_schedule_engine.initialize(conn)
    return conn


@_i18n_context
async def scheduled_embed_deliver(guild, name, channel_id):
    channel = guild.get_channel(channel_id)
    if not isinstance(channel, discord.TextChannel):
        return
    me = guild.me
    if me is None:
        return
    permissions = channel.permissions_for(me)
    if not (permissions.view_channel and permissions.send_messages and permissions.embed_links):
        return
    # No autogenerar menciones ni enviar si la plantilla ya no existe.
    record = embed_get(guild.id, name)
    if record is None:
        return
    data, _ = record
    rendered, _content, _unresolved = build_custom_embed(data, VarContext(guild, None, channel))
    if embed_is_empty(rendered) or len(rendered) > 6000:
        return
    await channel.send(embed=rendered, allowed_mentions=discord.AllowedMentions.none())


@tasks.loop(seconds=10)
@_i18n_context
async def scheduled_embeds_loop():
    now = datetime.now(timezone.utc)
    conn = scheduled_embed_db()
    try:
        jobs = embed_schedule_engine.claim_due(conn, now, scheduled_embed_test_mode())
    finally:
        conn.close()
    for _id, guild_id, name, channel_id in jobs:
        guild = bot.get_guild(guild_id)
        if guild is None:
            continue
        try:
            await scheduled_embed_deliver(guild, name, channel_id)
        except discord.HTTPException:
            print(f"Advertencia: publicación programada { _id } sin entrega confirmada")


@scheduled_embeds_loop.before_loop
async def scheduled_embeds_before_loop():
    await bot.wait_until_ready()


@bot.listen("on_message")
@_i18n_context
async def scheduled_embeds_message_counter(message):
    if message.guild is None or message.author.bot or message.webhook_id is not None:
        return
    conn = scheduled_embed_db()
    try:
        jobs = embed_schedule_engine.advance_message(conn, message.guild.id, message.channel.id)
    finally:
        conn.close()
    for _id, name in jobs:
        try:
            await scheduled_embed_deliver(message.guild, name, message.channel.id)
        except discord.HTTPException:
            print(f"Advertencia: contador de mensajes {_id} sin entrega confirmada")



def embed_schedule_human_details(mode: str, config: dict | None) -> str:
    """Resumir condiciones para moderadores sin exponer parámetros JSON."""
    if config is None:
        return _t('text.398921716ff1fa')
    if mode == "messages":
        return (
            _t('text.561c6a40e7d38d', p0=f"{int(config['count'])}")
        )
    if mode == "once":
        when = datetime.fromisoformat(config["when"]).astimezone(embed_schedule_engine.RD)
        return _t('text.7dfef7c4b436fd', p0=f'{when:%d/%m/%Y}', p1=f'{when:%H:%M}')
    if mode == "interval":
        return _t('text.66839e8c0ba014', p0=f"{config['interval']}")
    if mode == "daily":
        return _t('text.77572d157c13aa', p0=f"{config['time']}")
    if mode == "weekly":
        days = ("lunes", "martes", _t('text.ba08108cd6d174'), "jueves", "viernes", _t('text.04bc66d1db77f0'), "domingo")
        names = _i18n_join(", ", (days[int(day)] for day in config["days"]))
        return _t('text.d762e72956b58c', p0=f'{names}', p1=f"{config['time']}")
    if mode == "monthly":
        names = _i18n_join(", ", (str(day) for day in config["days"]))
        return _t('text.327fb33a1b0f9a', p0=f'{names}', p1=f"{config['time']}")
    return _t('text.7ba2afe619c750')


class EmbedScheduleOptionsModal(discord.ui.Modal, title=_t('text.9f98471bc58961')):
    option = discord.ui.TextInput(label=_t('text.6af0aa10d65c61'), placeholder=_t('text.31a73e03ade377'), max_length=100)
    when = discord.ui.TextInput(label=_t('text.9ce72cf0737737'), required=False, max_length=20)

    @_i18n_context
    def __init__(self, parent):
        super().__init__()
        self.parent = parent
        mode = parent.mode
        self.option.label = {
            "once": _t('text.e157bf6a2ad565'), "interval": _t('text.a118235f4b5db9'),
            "daily": _t('text.e157bf6a2ad565'), "weekly": _t('text.594b947afee082'),
            "monthly": _t('text.e00cad1a9c4d3a'), "messages": _t('text.aa5a1e2f7fa8af')
        }[mode]
        self.option.placeholder = {
            "once": "18:00", "interval": "6h", "daily": "18:00", "weekly": "1,3,5",
            "monthly": "1,15", "messages": "100"
        }[mode]
        if mode == "once":
            self.when.label = _t('text.7b20978aa4de80')
            self.when.placeholder = _t('text.159a055643b7a0')
            self.when.required = True
        elif mode in {"weekly", "monthly"}:
            self.when.label = _t('text.e157bf6a2ad565')
            self.when.placeholder = _t('text.51327e7d83658f')
            self.when.required = True
        else:
            self.remove_item(self.when)

    @_i18n_context
    async def on_submit(self, interaction):
        if not await self.parent.interaction_check(interaction):
            return
        mode = self.parent.mode
        value = str(self.option).strip()
        extra = str(self.when).strip() if mode in {"once", "weekly", "monthly"} else ""
        try:
            if mode == "once":
                date_value = datetime.strptime(extra + " " + value, "%Y-%m-%d %H:%M")
                if date_value.replace(tzinfo=embed_schedule_engine.RD) <= datetime.now(timezone.utc):
                    raise ValueError(_t('text.be9dfe88b977e9'))
                cfg = {"when": date_value.replace(tzinfo=embed_schedule_engine.RD).isoformat()}
            elif mode == "interval":
                cfg = {"interval": value, "anchor": datetime.now(timezone.utc).isoformat()}
            elif mode == "daily":
                cfg = {"time": value}
            elif mode in {"weekly", "monthly"}:
                days = sorted(set(int(x.strip()) for x in value.split(",")))
                cfg = {"days": [x-1 for x in days] if mode == "weekly" else days, "time": extra}
            else:
                cfg = {"count": int(value)}
            embed_schedule_engine.validate(mode, cfg, scheduled_embed_test_mode())
            if mode != "messages":
                embed_schedule_engine.next_due(mode, cfg, datetime.now(timezone.utc), scheduled_embed_test_mode())
        except (ValueError, KeyError, TypeError) as exc:
            await interaction.response.send_message(_t('text.5c0f04bc04a6ac', p0=f'{exc}'), ephemeral=True)
            return
        self.parent.config = cfg
        self.parent.invalidate_review()
        await interaction.response.edit_message(content=self.parent.summary(), view=self.parent)


class EmbedScheduleView(discord.ui.View):
    MODES = [("once", _t('text.05c9525be6d8b4')), ("interval", _t('text.0dd4192180fd77')), ("daily", _t('text.ffa5b3464a52f5')),
             ("weekly", _t('text.01ab23786167d1')), ("monthly", _t('text.acacad0708eeed')), ("messages", _t('text.bfac8a601ec1c4'))]

    @_i18n_context
    def __init__(self, owner_id, guild_id, name):
        super().__init__(timeout=900)
        self.owner_id, self.guild_id, self.name = owner_id, guild_id, name
        self.mode = "weekly"
        self.config = None
        self.channel_id = None
        self.active = False
        self.reviewed = False
        self.channel_menu = discord.ui.ChannelSelect(placeholder=_t('text.ccdc74ed78baa9'),
                                                     channel_types=[discord.ChannelType.text], row=0)
        self.channel_menu.callback = self.select_channel
        self.add_item(self.channel_menu)
        self.mode_menu = discord.ui.Select(placeholder=_t('text.441cc909a46990'),
            options=[discord.SelectOption(label=label, value=key, default=key == self.mode) for key,label in self.MODES],
            row=1)
        self.mode_menu.callback = self.select_mode
        self.add_item(self.mode_menu)
        self.toggle.label = _t('text.254052ea94561f')
        self.toggle.style = discord.ButtonStyle.success

    @_i18n_context
    def invalidate_review(self):
        self.reviewed = False
        self.save.label = _t('text.afda27aac75a77') if isinstance(self, EmbedScheduleEditView) else _t('text.e62842332ca205')

    @_i18n_context
    async def interaction_check(self, interaction):
        if interaction.user.id != self.owner_id or interaction.guild is None or interaction.guild.id != self.guild_id:
            await interaction.response.send_message(_t('text.abdf3493e59a20'), ephemeral=True)
            return False
        if not interaction.user.guild_permissions.manage_guild:
            await interaction.response.send_message(_t('text.5e5ccc8223aec7'), ephemeral=True)
            return False
        return True

    @_i18n_context
    def summary(self):
        is_edit = isinstance(self, EmbedScheduleEditView)
        channel = f"<#{self.channel_id}>" if self.channel_id is not None else _t('text.4865f7e3ff28d7')
        confirm = _t('text.07cb51d2824c53') if is_edit else _t('text.6c13a77b170948')
        review = _t('text.afda27aac75a77') if is_edit else _t('text.e62842332ca205')
        title = _t('text.1a38f5823fd8d2') if is_edit else _t('text.f38010669e7b85')
        if self.reviewed:
            instruction = (
                _t('text.74a0a559e2418a', p0=f'{confirm}')
            )
        else:
            instruction = (
                _t('text.2eb03796ac8a31', p0=f'{review}')
            )
        return (
            _t('text.eb1bb265181682', p0=f'{title}', p1=f'{self.name}', p2=f'{channel}', p3=f'{dict(self.MODES)[self.mode]}', p4=f'{embed_schedule_human_details(self.mode, self.config)}', p5=f"{(_t('text.69d17ca1683468') if self.active else _t('text.987d904d7afee2'))}", p6=f'{instruction}')
        )

    @_i18n_context
    async def select_channel(self, interaction):
        values = self.channel_menu.values
        if not values:
            await interaction.response.send_message(_t('text.d8adde6fe847ca'), ephemeral=True)
            return
        channel = interaction.guild.get_channel(values[0].id)
        if not isinstance(channel, discord.TextChannel):
            await interaction.response.send_message(_t('text.2cf228a41783c1'), ephemeral=True)
            return
        permissions = channel.permissions_for(interaction.guild.me)
        if not (permissions.view_channel and permissions.send_messages and permissions.embed_links):
            await interaction.response.send_message(_t('text.48d1ddd1dc5d3b'), ephemeral=True)
            return
        self.channel_id = channel.id
        self.invalidate_review()
        await interaction.response.edit_message(content=self.summary(), view=self)

    @_i18n_context
    async def select_mode(self, interaction):
        value = self.mode_menu.values[0]
        self.mode = value
        self.config = None
        self.invalidate_review()
        for opt in self.mode_menu.options:
            opt.default = opt.value == value
        await interaction.response.edit_message(content=self.summary(), view=self)

    @discord.ui.button(label=_t('text.57e646488f60b1'), style=discord.ButtonStyle.primary, row=2)
    @_i18n_context
    async def configure(self, interaction, button):
        await interaction.response.send_modal(EmbedScheduleOptionsModal(self))

    @discord.ui.button(label=_t('text.254052ea94561f'), style=discord.ButtonStyle.success, row=2)
    @_i18n_context
    async def toggle(self, interaction, button):
        self.active = not self.active
        self.toggle.label = _t('text.88c0ffe30005b1') if self.active else _t('text.254052ea94561f')
        self.toggle.style = discord.ButtonStyle.danger if self.active else discord.ButtonStyle.success
        self.invalidate_review()
        await interaction.response.edit_message(content=self.summary(), view=self)

    @discord.ui.button(label=_t('text.e62842332ca205'), style=discord.ButtonStyle.primary, row=3)
    @_i18n_context
    async def save(self, interaction, button):
        if isinstance(self, EmbedScheduleEditView):
            return await self.save_existing(interaction, button)
        if self.channel_id is None or self.config is None:
            await interaction.response.send_message(_t('text.059aeae72d2de2'), ephemeral=True)
            return
        if embed_get(self.guild_id, self.name) is None:
            await interaction.response.send_message(_t('text.e1253f6ec41225'), ephemeral=True)
            return
        if not self.reviewed:
            self.reviewed = True
            button.label = _t('text.6c13a77b170948')
            await interaction.response.edit_message(
                content=self.summary(), view=self)
            return
        now = datetime.now(timezone.utc)
        try:
            due = embed_schedule_engine.next_due(self.mode, self.config, now, scheduled_embed_test_mode())
            if self.mode == "once" and due is None:
                raise ValueError(_t('text.3dd8e19c8c84d0'))
        except (ValueError, KeyError, TypeError) as exc:
            await interaction.response.send_message(_t('text.8fbf70aca099de', p0=f'{exc}'), ephemeral=True)
            return
        conn = scheduled_embed_db()
        try:
            cursor = conn.execute(
                "INSERT INTO scheduled_embeds (guild_id,embed_name,channel_id,mode,config,enabled,next_due,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?)",
                (self.guild_id, self.name, self.channel_id, self.mode, json.dumps(self.config),
                 int(self.active), due.isoformat() if due else None, now.isoformat(),now.isoformat()))
            conn.commit()
            ident = cursor.lastrowid
        finally:
            conn.close()
        self.stop()
        await interaction.response.edit_message(content=_t('text.9345ce2f6cd0c6', p0=f'{ident}', p1=f"{(_t('text.913dba3a79e33b') if self.active else _t('text.f7f5a5c6c80d49'))}"),view=None)

    @discord.ui.button(label=_t('text.bb9dbb406dcbd5'), style=discord.ButtonStyle.danger, row=3)
    @_i18n_context
    async def cancel(self, interaction, button):
        self.stop()
        await interaction.response.edit_message(content=_t('text.b369d756855d7d'),view=None)



