class EmbedScheduleEditView(EmbedScheduleView):
    """Edits an existing schedule with optimistic concurrency and a two-step save."""
    @_i18n_context
    def __init__(self, owner_id, guild_id, schedule_id):
        conn = scheduled_embed_db()
        try:
            row = conn.execute(
                "SELECT embed_name,channel_id,mode,config,enabled,updated_at FROM scheduled_embeds "
                "WHERE id=? AND guild_id=?", (schedule_id, guild_id)).fetchone()
        finally:
            conn.close()
        if row is None:
            raise ValueError(_t('text.b882a3fcabc604'))
        name, channel_id, mode, config_json, enabled, version = row
        super().__init__(owner_id, guild_id, name)
        self.schedule_id, self.version = schedule_id, version
        self.channel_id, self.mode, self.config, self.active = channel_id, mode, json.loads(config_json), bool(enabled)
        self.toggle.label = _t('text.88c0ffe30005b1') if self.active else _t('text.254052ea94561f')
        self.toggle.style = discord.ButtonStyle.danger if self.active else discord.ButtonStyle.success
        for option in self.mode_menu.options:
            option.default = option.value == mode
        self.reviewed = False
        self.save.label = _t('text.afda27aac75a77')

    @_i18n_context
    async def save_existing(self, interaction, button):
        if self.channel_id is None or self.config is None:
            await interaction.response.send_message(_t('text.059aeae72d2de2'), ephemeral=True)
            return
        guild = interaction.guild
        channel = guild.get_channel(self.channel_id) if guild else None
        if not isinstance(channel, discord.TextChannel) or guild.me is None:
            await interaction.response.send_message(_t('text.fb4203094cb4e3'), ephemeral=True)
            return
        perms = channel.permissions_for(guild.me)
        if not (perms.view_channel and perms.send_messages and perms.embed_links):
            await interaction.response.send_message(_t('text.473dfa485e7e27'), ephemeral=True)
            return
        if embed_get(self.guild_id, self.name) is None:
            await interaction.response.send_message(_t('text.5836938719b1fd'), ephemeral=True)
            return
        try:
            now = datetime.now(timezone.utc)
            due = embed_schedule_engine.next_due(self.mode, self.config, now, scheduled_embed_test_mode())
            if self.active and self.mode == "once" and due is None:
                raise ValueError(_t('text.e01460a9ba8053'))
        except (ValueError, KeyError, TypeError) as exc:
            await interaction.response.send_message(_t('text.f5d39c5d5636d7', p0=f'{exc}'), ephemeral=True)
            return
        if not self.reviewed:
            self.reviewed = True
            button.label = _t('text.07cb51d2824c53')
            await interaction.response.edit_message(
                content=self.summary(), view=self)
            return
        conn = scheduled_embed_db()
        try:
            cursor = conn.execute(
                "UPDATE scheduled_embeds SET channel_id=?,mode=?,config=?,enabled=?,next_due=?,"
                "message_count=0,updated_at=? WHERE id=? AND guild_id=? AND updated_at=?",
                (self.channel_id,self.mode,json.dumps(self.config),int(self.active),
                 due.isoformat() if due else None,now.isoformat(),self.schedule_id,self.guild_id,self.version))
            if cursor.rowcount != 1:
                conn.rollback()
                await interaction.response.send_message(
                    _t('text.b9fb4ed7f83f4e'),ephemeral=True)
                return
            conn.commit()
        finally:
            conn.close()
        self.stop()
        await interaction.response.edit_message(
            content=_t('text.f54ae4b6e9cdbe', p0=f'{self.schedule_id}'),view=None)

    @discord.ui.button(label=_t('text.4ccf118d16da15'), style=discord.ButtonStyle.danger, row=4)
    @_i18n_context
    async def discard(self, interaction, button):
        self.stop()
        await interaction.response.edit_message(content=_t('text.a8a29ceb0d4cee'),view=None)


class EmbedScheduleDeleteView(discord.ui.View):
    @_i18n_context
    def __init__(self, owner_id, guild_id, schedule_id):
        super().__init__(timeout=180)
        self.owner_id, self.guild_id, self.schedule_id = owner_id, guild_id, schedule_id
        conn = scheduled_embed_db()
        try:
            self.snapshot = conn.execute(
                "SELECT embed_name,channel_id,mode,updated_at FROM scheduled_embeds "
                "WHERE guild_id=? AND id=?", (guild_id,schedule_id)).fetchone()
        finally:
            conn.close()

    @_i18n_context
    async def interaction_check(self, interaction):
        if (interaction.guild is None or interaction.guild.id != self.guild_id
                or interaction.user.id != self.owner_id
                or not interaction.user.guild_permissions.manage_guild):
            await interaction.response.send_message(_t('text.d3cbb9179a2d1c'),ephemeral=True)
            return False
        return True

    @discord.ui.button(label=_t('text.b4bb6c6db58f7c'), style=discord.ButtonStyle.danger)
    @_i18n_context
    async def confirm_delete(self, interaction, button):
        if self.snapshot is None:
            await interaction.response.send_message(_t('text.b882a3fcabc604'),ephemeral=True)
            return
        conn = scheduled_embed_db()
        try:
            cursor = conn.execute(
                "DELETE FROM scheduled_embeds WHERE guild_id=? AND id=? AND updated_at=?",
                (self.guild_id,self.schedule_id,self.snapshot[3]))
            if cursor.rowcount != 1:
                conn.rollback()
                await interaction.response.send_message(
                    _t('text.d3df17234f1a01'),ephemeral=True)
                return
            conn.commit()
        finally:
            conn.close()
        self.stop()
        await interaction.response.edit_message(
            content=_t('text.2adf2dd2692233', p0=f'{self.schedule_id}'),
            view=None)

    @discord.ui.button(label=_t('text.bb9dbb406dcbd5'), style=discord.ButtonStyle.danger)
    @_i18n_context
    async def cancel_delete(self, interaction, button):
        self.stop()
        await interaction.response.edit_message(content=_t('text.1974f317689ef2'),view=None)


class EmbedSchedulesManageView(discord.ui.View):
    @_i18n_context
    def __init__(self, owner_id, guild_id):
        super().__init__(timeout=900)
        self.owner_id, self.guild_id = owner_id, guild_id
        self.selected_id = None
        conn = scheduled_embed_db()
        try:
            rows = conn.execute(
                "SELECT id, embed_name, mode, enabled FROM scheduled_embeds WHERE guild_id=? ORDER BY id DESC LIMIT 25",
                (guild_id,)).fetchall()
        finally:
            conn.close()
        if rows:
            select = discord.ui.Select(
                placeholder=_t('text.f80a1c04b2b87b'),
                options=[discord.SelectOption(label=f"#{ident} · {name}"[:100],
                    description=f"{mode} · {_t('text.69d17ca1683468') if enabled else _t('text.2c762c700650af')}",
                    value=str(ident)) for ident, name, mode, enabled in rows], row=0)
            select.callback = self.pick
            self.add_item(select)

    @_i18n_context
    async def interaction_check(self, interaction):
        if interaction.user.id != self.owner_id or not interaction.user.guild_permissions.manage_guild:
            await interaction.response.send_message(_t('text.1c6c28763f9c3c'), ephemeral=True)
            return False
        return interaction.guild is not None and interaction.guild.id == self.guild_id

    @_i18n_context
    async def pick(self, interaction):
        self.selected_id = int(interaction.data["values"][0])
        await interaction.response.edit_message(content=_t('text.9051d26771c6bf', p0=f'{self.selected_id}'), view=self)

    @discord.ui.button(label=_t('text.2eba946b2e1ee4'), style=discord.ButtonStyle.primary, row=2)
    @_i18n_context
    async def edit_schedule(self, interaction, button):
        if self.selected_id is None:
            await interaction.response.send_message(_t('text.5f9ed1c204ef74'),ephemeral=True)
            return
        try:
            view = EmbedScheduleEditView(self.owner_id, self.guild_id, self.selected_id)
        except ValueError as exc:
            await interaction.response.send_message(str(exc),ephemeral=True)
            return
        await interaction.response.send_message(
            content=view.summary(),
            view=view,ephemeral=True)

    @discord.ui.button(label=_t('text.c9894cf002f90b'), style=discord.ButtonStyle.danger, row=2)
    @_i18n_context
    async def delete_schedule(self, interaction, button):
        if self.selected_id is None:
            await interaction.response.send_message(_t('text.5f9ed1c204ef74'),ephemeral=True)
            return
        view = EmbedScheduleDeleteView(self.owner_id,self.guild_id,self.selected_id)
        if view.snapshot is None:
            await interaction.response.send_message(_t('text.b882a3fcabc604'),ephemeral=True)
            return
        name, channel, mode, _ = view.snapshot
        await interaction.response.send_message(
            content=_t('text.99cbc620dd0de2', p0=f'{self.selected_id}', p1=f'{name}', p2=f'{channel}', p3=f'{mode}'),
            view=view,ephemeral=True)

    @discord.ui.button(label=_t('text.0caefec4720faf'), style=discord.ButtonStyle.primary, row=1)
    @_i18n_context
    async def toggle(self, interaction, button):
        if self.selected_id is None:
            await interaction.response.send_message(_t('text.5f9ed1c204ef74'), ephemeral=True)
            return
        conn = scheduled_embed_db()
        try:
            row = conn.execute(
                "SELECT mode, config, enabled FROM scheduled_embeds WHERE guild_id=? AND id=?",
                (self.guild_id, self.selected_id)).fetchone()
            if row is None:
                await interaction.response.send_message(_t('text.f544cefcb08d98'), ephemeral=True)
                return
            mode, raw, active = row
            activate = not bool(active)
            try:
                next_date = embed_schedule_engine.next_due(
                    mode, json.loads(raw), datetime.now(timezone.utc), scheduled_embed_test_mode()
                ) if activate else None
                if activate and mode == "once" and next_date is None:
                    raise ValueError(_t('text.8d5007760e97ad'))
            except (ValueError, KeyError, TypeError) as exc:
                await interaction.response.send_message(_t('text.e47cf374863a96', p0=f'{exc}'), ephemeral=True)
                return
            conn.execute("UPDATE scheduled_embeds SET enabled=?,next_due=?,updated_at=? WHERE guild_id=? AND id=?",
                (int(activate), next_date.isoformat() if next_date else None,
                 datetime.now(timezone.utc).isoformat(), self.guild_id, self.selected_id))
            conn.commit()
        finally:
            conn.close()
        await interaction.response.edit_message(
            content=_t('text.77e25587cb74b6', p0=f'{self.selected_id}', p1=f"{(_t('text.adfcbfc83b5cc5') if activate else _t('text.189dced1c43601'))}"), view=self)


