if __name__ == "__main__":
    from enzonic_test_host import refuse_legacy_test_start
    refuse_legacy_test_start()
    token = os.environ.get("DISCORD_TOKEN")
    if not token:
        raise RuntimeError(
            _t('text.3487aaf925f307')
        )
    try:
        # Impide restaurar SQLite mientras este proceso mantiene el Gateway vivo.
        # El bloqueo se libera al cerrar o interrumpirse el proceso.
        from sqlite_recovery import service_lock
        from enzonic_test_host import is_enzonic, before_discord
        with service_lock(DB_PATH, exclusive=is_enzonic()):
            before_discord()
            bot.run(token)
    except discord.PrivilegedIntentsRequired:
        if os.environ.get("MESSAGE_CONTENT_INTENT") != "1":
            raise
        # MESSAGE_CONTENT_INTENT=1 sin activar el intent en el portal: en vez de quedarse
        # sin conectar, el bot se reinicia sin él (el log del honeypot no mostrará el texto).
        print("Advertencia: El intent Message Content no está activado en el portal de desarrolladores: "
              "reiniciando sin él. Actívalo en el portal o quita MESSAGE_CONTENT_INTENT.")
        os.environ["MESSAGE_CONTENT_INTENT"] = "0"
        os.execv(sys.executable, [sys.executable, *sys.argv])
